window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[24]={"id":"024","numero":24,"titre":"Principales complications de la grossesse","objectifs":[{"id":"24-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la prise en charge d’une hémorragie du premier trimestre","contenu":"<div class=\"notion-course\"><p>Les hémorragies du 1er trimestre concernent <span>25 %</span> des grossesses ; <strong><span><span class=\"nc-red nc-bold\">50 %</span></span><span class=\"nc-red nc-bold\"> de ces femmes auront une </span><span><span class=\"nc-red nc-bold\">évolution</span></span><span class=\"nc-red nc-bold\"> défavorable</span></strong>. Trois diagnostics dominent : <span><span class=\"nc-green_bg\">GIU évolutive</span></span> avec <span><span class=\"nc-orange nc-bold\">hématome décidual</span></span>, <span>fausse couche spontanée</span>, <span><span class=\"nc-red_bg\">GEU</span></span>.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Dogme.</strong> Toute femme avec hémorragie du 1er trimestre = <span><span class=\"nc-red_bg\">GEU</span> jusqu’à preuve du contraire</span>.\n      </div>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewbox=\"0 0 620 282\" role=\"img\" aria-label=\"Arbre décisionnel devant des métrorragies du premier trimestre, qui sont une grossesse extra-utérine jusqu&#x27;à preuve du contraire. Première étape : examen au spéculum pour éliminer une cause cervico-vaginale, dosage des béta-hCG plasmatiques et groupe Rhésus RAI. Deuxième étape : échographie pelvienne par voie endovaginale, qui oriente vers trois diagnostics. Premier : grossesse intra-utérine évolutive si sac intra-utérin conforme avec embryon et activité cardiaque, et béta-hCG qui doublent à 48 heures. Deuxième : grossesse extra-utérine si utérus vide avec béta-hCG supérieurs à 1500, parfois masse latéro-utérine, et béta-hCG en stagnation à 48 heures. Troisième : fausse couche spontanée si œuf clair ou sac aplati ou embryon sans activité cardiaque, et béta-hCG en décroissance à 48 heures.\" style=\"height:auto;display:block;border-radius:8px\">\n          <rect class=\"fb-blue\" x=\"160\" y=\"12\" width=\"300\" height=\"44\" rx=\"6\"></rect>\n          <text class=\"tx-blue\" x=\"310\" y=\"30\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">Métrorragies du 1ᵉʳ trimestre</text>\n          <text class=\"tx-blue\" x=\"310\" y=\"47\" text-anchor=\"middle\" font-size=\"9.5\">→ GEU jusqu’à preuve du contraire</text>\n\n          <line class=\"ln\" x1=\"310\" y1=\"56\" x2=\"310\" y2=\"72\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"310,74 305,66 315,66\"></polygon>\n\n          <rect class=\"fb-grey\" x=\"140\" y=\"74\" width=\"340\" height=\"34\" rx=\"6\"></rect>\n          <text class=\"tx-grey\" x=\"310\" y=\"95\" text-anchor=\"middle\" font-size=\"10\">Spéculum + β-hCG plasmatique + groupe-Rhésus-RAI</text>\n\n          <line class=\"ln\" x1=\"310\" y1=\"108\" x2=\"310\" y2=\"122\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"310,124 305,116 315,116\"></polygon>\n\n          <rect class=\"fb-teal\" x=\"200\" y=\"124\" width=\"220\" height=\"30\" rx=\"6\"></rect>\n          <text class=\"tx-teal\" x=\"310\" y=\"143\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"600\"><span>Échographie</span> endovaginale</text>\n\n          <line class=\"ln\" x1=\"310\" y1=\"154\" x2=\"310\" y2=\"168\" stroke-width=\"2\"></line>\n          <line class=\"ln\" x1=\"110\" y1=\"168\" x2=\"510\" y2=\"168\" stroke-width=\"2\"></line>\n          <line class=\"ln\" x1=\"110\" y1=\"168\" x2=\"110\" y2=\"180\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"110,182 105,174 115,174\"></polygon>\n          <line class=\"ln\" x1=\"310\" y1=\"168\" x2=\"310\" y2=\"180\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"310,182 305,174 315,174\"></polygon>\n          <line class=\"ln\" x1=\"510\" y1=\"168\" x2=\"510\" y2=\"180\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"510,182 505,174 515,174\"></polygon>\n\n          <rect class=\"fb-ok\" x=\"15\" y=\"182\" width=\"190\" height=\"86\" rx=\"6\"></rect>\n          <text class=\"tx-ok\" x=\"110\" y=\"201\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\">GIU évolutive</text>\n          <text class=\"tx-ok\" x=\"110\" y=\"217\" text-anchor=\"middle\" font-size=\"9\">Sac IU conforme + embryon</text>\n          <text class=\"tx-ok\" x=\"110\" y=\"231\" text-anchor=\"middle\" font-size=\"9\">+ activité cardiaque</text>\n          <text class=\"tx-ok\" x=\"110\" y=\"252\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">β-hCG : doublement /<span>48 h</span></text>\n\n          <rect class=\"fb-red\" x=\"215\" y=\"182\" width=\"190\" height=\"86\" rx=\"6\"></rect>\n          <text class=\"tx-red\" x=\"310\" y=\"201\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\">GEU</text>\n          <text class=\"tx-red\" x=\"310\" y=\"217\" text-anchor=\"middle\" font-size=\"9\">Utérus vide + β-hCG &gt; 1500</text>\n          <text class=\"tx-red\" x=\"310\" y=\"231\" text-anchor=\"middle\" font-size=\"9\">± <span>masse</span> latéro-utérine</text>\n          <text class=\"tx-red\" x=\"310\" y=\"252\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">β-hCG : stagnation /<span>48 h</span></text>\n\n          <rect class=\"fb-amber\" x=\"415\" y=\"182\" width=\"190\" height=\"86\" rx=\"6\"></rect>\n          <text class=\"tx-amber\" x=\"510\" y=\"201\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\">Fausse couche spontanée</text>\n          <text class=\"tx-amber\" x=\"510\" y=\"217\" text-anchor=\"middle\" font-size=\"9\">Œuf clair / sac aplati</text>\n          <text class=\"tx-amber\" x=\"510\" y=\"231\" text-anchor=\"middle\" font-size=\"9\">ou embryon sans AC</text>\n          <text class=\"tx-amber\" x=\"510\" y=\"252\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">β-hCG : décroissance /<span>48 h</span></text>\n        </svg>\n        <figcaption>La <strong>cinétique des β-hCG à<span> 48 h</span></strong> oriente mais n’élimine jamais formellement : toute cinétique peut se voir en GEU → contrôle écho à 5-7 j si doute.</figcaption>\n      </figure>\n\n      <h4>Étiologies du 1er trimestre</h4>\n      <table>\n        <thead><tr><th>Étiologie</th><th>Fréquence / particularités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span><span class=\"nc-green_bg\">GIU évolutive</span></span> + <span><span class=\"nc-orange_bg\">hématome décidual</span></span></strong></td><td><span>12 %</span> — saignement bénin, abdomen <span class=\"nc-green_bg nc-bold\">indolore</span>, écho conforme à l’âge gestationnel + <span>image liquidienne entre œuf et paroi</span></td></tr>\n          <tr><td><strong><span>Avortement spontané</span> (<span>fausse couche</span>)</strong></td><td><span>12 %</span> — <span class=\"nc-blue_bg\">métrorragies</span> rouges <span class=\"nc-red nc-bold\">abondantes</span> avec <span class=\"nc-red nc-bold\">caillots</span>/<span class=\"nc-red nc-bold\">débris</span>, douleurs « comme des règles »</td></tr>\n          <tr><td><strong><span>GEU</span></strong></td><td><span>1 %</span> — sang sépia, douleurs latéralisées, β-hCG &gt; 1500 + vacuité utérine</td></tr>\n          <tr><td><strong>Causes cervico-vaginales</strong></td><td>Au spéculum : <span><span class=\"nc-red nc-bold\">cancer du col</span></span>, <span class=\"nc-green nc-bold\">ectropion</span>, <span class=\"nc-orange_bg\">cervicite</span>, polype</td></tr>\n          <tr><td><strong>Rares</strong></td><td><span class=\"nc-orange nc-bold\">Lyse d’un jumeau</span> (gémellaire), <span><span class=\"nc-red nc-bold\">grossesse môlaire</span></span> (hCG &gt; 100 000, <span>« nid d’abeilles »</span> écho)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>CAT systématique devant métrorragies du 1er trimestre</h4>\n      <ol>\n        <li><strong>Examen au spéculum</strong> — différencier origine cervico-vaginale <span>vs</span> endo-utérine</li>\n        <li><span>β-<span class=\"nc-blue_bg nc-bold\">hCG</span> <span class=\"nc-blue_bg\">plasmatique</span></span> en cas de doute sur l’état de <span>grossesse</span> + <span><span class=\"nc-blue_bg\">groupe sanguin + Rhésus</span> + RAI</span> systématiques ⭐</li>\n        <li><span><span class=\"nc-blue_bg\">Échographie pelvienne</span> par voie endovaginale</span> + abdominale (recherche hémopéritoine)</li>\n        <li>Si <strong>Rh-</strong> et fœtus Rh+ ou inconnu : <span>Ig anti-D</span> dans les <span>72 h</span></li>\n      </ol>\n\n      <h4>Orientation clinique synthétique</h4>\n      <table>\n        <thead><tr><th></th><th><span>GIU évolutive</span></th><th><span>GEU</span></th><th><span>Avortement spontané</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Signes sympathiques</strong></td><td>Oui</td><td>Oui</td><td><span>Disparition</span> ⭐</td></tr>\n          <tr><td><strong>Douleurs</strong></td><td>Absentes ⭐</td><td>Latéralisées, sourdes</td><td><span class=\"nc-red nc-bold\">Médianes</span>, intermittentes</td></tr>\n          <tr><td><strong><span class=\"nc-blue_bg\">Métrorragies</span></strong></td><td>Faibles</td><td>Peu <span class=\"nc-red nc-bold\">abondantes</span>, noirâtres (sépia)</td><td><span class=\"nc-red nc-bold\">Abondantes</span>, rouges, avec <span class=\"nc-red nc-bold\">caillots</span>/<span class=\"nc-red nc-bold\">débris</span></td></tr>\n          <tr><td><strong><span>TV</span> col</strong></td><td>Fermé</td><td>Tonique, fermé</td><td><span class=\"nc-yellow_bg nc-bold\">Mou</span>, <span class=\"nc-yellow_bg nc-bold\">perméable au doigt</span></td></tr>\n          <tr><td><strong>Utérus</strong></td><td>Taille = terme</td><td>Plus petit qu’attendu ± <span>masse</span> latéro-utérine</td><td>Taille = terme</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span><span class=\"nc-blue_bg\">Échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span> — résultats normaux et interprétation</h4>\n      <ul>\n        <li><strong>Sac ovulaire intra-utérin</strong> (<span>image liquidienne entourée d’une couronne échogène trophoblastique</span>) : visible dès <span><span class=\"nc-pink nc-bold\">5 SA</span></span></li>\n        <li><strong>Embryon + <span class=\"nc-green nc-bold\">activité</span> cardiaque</strong> : entre <span>5,5 et 6 SA</span></li>\n        <li><strong>Sac intra-utérin conforme</strong> → <span><span class=\"nc-green nc-bold\">GIU évolutive</span></span></li>\n        <li><strong><span>Œuf clair, aplati, contour irrégulier, petit</span></strong> → <span><span class=\"nc-orange nc-bold\">avortement spontané</span></span></li>\n        <li><strong><span>Utérus vide</span></strong> avec β-hCG &gt; 1500 → <span>GEU</span> jusqu’à preuve du contraire ; <span>masse hétérogène floconneuse vésiculaire</span> → <span>môle</span></li>\n        <li><strong>Si doute</strong> : refaire écho <span>5-7 jours</span> après le 1er contrôle</li>\n      </ul>\n\n      <h4>Cinétique des β-hCG à <span>48 h</span></h4>\n      <ul>\n        <li><strong>Doublement</strong> → <span><span class=\"nc-orange nc-bold\">grossesse</span></span> évolutive (<span class=\"nc-green nc-bold\">GIU</span> le plus souvent, parfois <span><span class=\"nc-red nc-bold\">GEU</span></span>)</li>\n        <li><strong>Décroissance × 2</strong> → <span>fausse couche spontanée</span></li>\n        <li><strong>Stagnation ou élévation insuffisante</strong> → <span><span class=\"nc-red nc-bold\">GEU</span></span> plutôt</li>\n        <li><em>KB :</em> toute cinétique peut se voir en <span><span class=\"nc-red nc-bold\">GEU</span></span> — la cinétique oriente mais n’élimine jamais formellement</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span class=\"nc-red_bg\">GEU</span> · 43 — Hémorragie génitale chez la femme · 23 — <span><span class=\"nc-orange nc-bold\">Grossesse</span></span> normale · 27 — Prévention des risques fœtaux</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":1},{"id":"24-2","rang":"A","rubrique":"Prise en charge","titre":"Connaître la prise en charge une fausse couche du premier trimestre","contenu":"<div class=\"notion-course\"><p>La <span><span class=\"nc-yellow_bg\">fausse couche spontanée</span> précoce (FCP)</span> = expulsion d’une <span class=\"nc-green nc-bold\">GIU</span> avant <span>14 SA</span>. Fréquence <span>10-15 %</span> des grossesses. Cause principale : <strong>anomalie chromosomique embryonnaire (<span>60 %</span>)</strong>.</p>\n\n      <h4>Terminologie clé</h4>\n      <table>\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Grossesse</span> de localisation indéterminée</strong></td><td>hCG positif mais écho ne visualisant aucune <span>grossesse</span></td></tr>\n          <tr><td><strong>GIU d’<span>évolution</span> incertaine</strong></td><td>Sac gestationnel &lt; <span>25 mm</span> sans embryon, ou embryon avec LCC &lt; <span>7 mm</span> sans <span class=\"nc-green nc-bold\">activité</span> cardiaque</td></tr>\n          <tr><td><strong><span>Grossesse</span> arrêtée précoce</strong></td><td>Arrêt <span class=\"nc-pink nc-bold\">&lt; </span><span><span class=\"nc-pink nc-bold\">14 SA</span></span> : stagnation du sac et/ou LCC, disparition de l’AC</td></tr>\n          <tr><td><strong><span>FCP</span> complète</strong></td><td>Vacuité utérine + absence de symptôme</td></tr>\n          <tr><td><strong><span>FCP</span> incomplète</strong></td><td>Persistance de matériel intra-utérin à l’écho</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span>Diagnostic positif</span></h4>\n      <ul>\n        <li><strong>Clinique :</strong> disparition récente des signes sympathiques + <span class=\"nc-blue_bg\">métrorragies</span> rouges <span class=\"nc-red nc-bold\">franches</span> avec <span class=\"nc-red nc-bold\">caillots</span>/<span class=\"nc-red nc-bold\">débris</span> + douleurs <span class=\"nc-red nc-bold\">médianes</span> <span class=\"nc-red nc-bold\">intermittentes</span> « comme des règles »</li>\n        <li><strong><span>TV</span> :</strong> col <span class=\"nc-yellow_bg nc-bold\">mou</span> <span class=\"nc-yellow_bg nc-bold\">perméable au doigt</span> (ouvert après expulsion), culs-de-sac libres, <span class=\"nc-green_bg\">mobilisation utérine indolore</span></li>\n        <li><strong>Écho :</strong> sac ovulaire reconnaissable mais anormal — embryon sans AC, ou œuf clair sans embryon, aplati, <span class=\"nc-red nc-bold\">à contours irréguliers</span></li>\n      </ul>\n\n      <h4>Stratégies thérapeutiques</h4>\n      <table>\n        <thead><tr><th>Option</th><th>Indications / modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Abstention surveillée</strong></td><td><span class=\"nc-green_bg\">Expulsion spontanée dans la majorité des cas</span> (avec majoration transitoire d’hémorragie et douleurs)</td></tr>\n          <tr><td><strong><span class=\"nc-pink_bg\">Traitement</span> médical</strong> — <span><span class=\"nc-pink nc-bold\">misoprostol</span></span> (prostaglandine)</td><td>Si <strong>œuf de petite taille</strong> et <strong><span class=\"nc-green nc-bold\">hémorragies peu importantes</span></strong>. À éviter si <span>FCP</span> avec fœtus déjà expulsé.</td></tr>\n          <tr><td><strong><span class=\"nc-pink_bg\">Traitement</span> <span class=\"nc-pink_bg\">chirurgical</span></strong></td><td><span>Hospitalisation</span> + bilan préop + consultation <span class=\"nc-green_bg\">anesthésie</span>. AG ou AL : <strong><span class=\"nc-pink nc-bold\">dilatation du col</span> + <span class=\"nc-pink_bg\">aspiration</span> à la canule</strong> + <strong>examen anatomopathologique du produit</strong>. <span class=\"nc-yellow_bg\">Sortie le</span> <span class=\"nc-yellow_bg\">jour même</span> <span class=\"nc-yellow_bg\">ou le</span> <span class=\"nc-yellow_bg\">lendemain</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <h4>CAT KB selon le tableau</h4>\n      <ul>\n        <li><strong><span>Grossesse</span> arrêtée</strong> (pas d’embryon visible, ou embryon sans AC, non expulsé) → expulsion par <span><span class=\"nc-pink nc-bold\">misoprostol</span></span> ou aspiration</li>\n        <li><strong><span>FCP</span> fœtus expulsé</strong> → abstention si expulsion complète, aspiration si débris trophoblastiques ou hémorragie ; <em>éviter <span><span class=\"nc-pink nc-bold\">misoprostol</span></span></em></li>\n      </ul>\n\n      <h4>Mesures associées systématiques</h4>\n      <ul>\n        <li><span>Groupe + Rhésus + RAI</span></li>\n        <li>Si <strong>Rh-</strong> et fœtus Rh+ ou inconnu : <span>Ig anti-D</span> dans les <span>72 h</span></li>\n        <li><strong>Soutien psychologique</strong> — banale pour le médecin, source de traumatisme pour la femme</li>\n        <li>Information : <strong><span class=\"nc-green_bg\">aucune conséquence sur l’avenir obstétrical</span></strong> ; <span class=\"nc-green nc-bold\">activité</span> <span class=\"nc-green nc-bold\">physique</span> et <span class=\"nc-green nc-bold\">voiture</span> <span>ne sont pas</span> des causes ❌</li>\n        <li><strong>Bilan étiologique</strong> seulement si <strong><span><span class=\"nc-orange_bg nc-bold\">≥ 3</span></span><span class=\"nc-orange_bg nc-bold\"> épisodes</span> consécutifs &lt; <span>14 SA</span></strong></li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Avortements spontanés à répétition (rang C).</strong> <span>≥ 3</span> FCS <span class=\"nc-pink nc-bold\">&lt; </span><span><span class=\"nc-pink nc-bold\">14 SA</span></span> consécutives. Bilan : <span>caryotype des 2 conjoints</span> (translocations équilibrées), <span>anticoagulant circulant + anti-cardiolipine + anti-β2GP1</span> (<span class=\"nc-orange nc-bold\">SAPL</span>), <span>écho 3D pelvienne</span> (malformation), <span>prélèvements bactério vaginaux/endocervicaux</span> (endométrite chronique), <span><span class=\"nc-blue_bg\">bilan hormonal + glycémie</span></span>. <span class=\"nc-pink_bg\">Traitement</span> préventif <span>aspirine faible dose + HBPM préventive</span> uniquement efficace si <span class=\"nc-orange nc-bold\">SAPL</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span class=\"nc-red_bg\">GEU</span> · 23 — <span><span class=\"nc-orange nc-bold\">Grossesse</span></span> normale · 43 — Hémorragie génitale chez la femme · 27 — Prévention des risques fœtaux</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":0},{"id":"24-3","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître la prise en charge d’une grossesse extra-utérine","contenu":"<div class=\"notion-course\"><p>Cet objectif est <strong>traité intégralement dans l’item 25 — <span><span class=\"nc-orange nc-bold\">Grossesse</span></span> extra-utérine</strong>. Synthèse opérationnelle ici pour la PEC de l’item 24.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Dogme.</strong> Toute <span>femme en âge de procréer</span> avec douleur pelvienne et/ou <span class=\"nc-blue_bg\">métrorragies</span> = <strong><span><span class=\"nc-red_bg\">GEU</span></span> jusqu’à preuve du contraire</strong>. Triade systématique : <strong>examen clinique + écho endovaginale + abdominale + β-<span class=\"nc-blue_bg nc-bold\">hCG</span></strong>.\n      </div>\n\n      <h4>Tableau clinique typique</h4>\n      <ul>\n        <li><strong><span class=\"nc-blue_bg\">Métrorragies</span> :</strong> peu <span class=\"nc-red nc-bold\">abondantes</span>, foncées (<em>sépia</em>)</li>\n        <li><strong>Douleurs :</strong> latéralisées, sourdes avec accès plus intenses</li>\n        <li><strong><span>TV</span> :</strong> col tonique fermé, utérus plus petit qu’attendu, <span>masse</span> latéro-utérine, douleur au Douglas / <span class=\"nc-red nc-bold\">mobilisation utérine</span></li>\n        <li><strong>Formes évoluées :</strong> scapulalgies (irritation diaphragmatique), <span>malaise</span>, agitation</li>\n      </ul>\n\n      <h4><span>Signes de gravité</span> = <span>urgence</span> chirurgicale</h4>\n      <ul>\n        <li><span>Hypotension, tachycardie, malaise</span></li>\n        <li><span>Défense / contracture abdominale</span></li>\n        <li><span>Hémopéritoine</span> à l’écho (Douglas, espace de Morisson)</li>\n      </ul>\n\n      <h4>Stratégie thérapeutique</h4>\n      <table>\n        <thead><tr><th>Option</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Cœlioscopie</span></strong> (gold standard)</td><td>Patiente symptomatique, β-hCG &gt; 5000, <span>masse</span> &gt; <span>4 cm</span>, AC visible, instabilité</td></tr>\n          <tr><td><strong><span>Laparotomie</span></strong></td><td>Hémopéritoine massif + <span>choc</span>, CI à la <span>cœlioscopie</span></td></tr>\n          <tr><td><strong><span>Méthotrexate</span></strong> IM</td><td><span>GEU</span> paucisymptomatique, β-hCG &lt; 5000 (jusqu’à 10 000), pas d’AC, pas de <span>masse</span> &gt; <span>4 cm</span>. <span>Surveillance</span> hebdo β-hCG. Contraception <span>3 mois</span>.</td></tr>\n          <tr><td><strong>Abstention surveillée</strong></td><td>Asymptomatique + β-hCG &lt; 1000 + décroissance constante + observance</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Mesures associées</h4>\n      <ul>\n        <li><strong>Si Rh-</strong> : <span>Ig anti-D</span> dans les <span>72 h</span></li>\n        <li><strong><span>Dépistage</span> IST</strong> chez patiente + partenaire si séquelles d’IGH à la cœlio</li>\n        <li><strong>Récidive ≈ <span>20 %</span></strong> → écho précoce à <span>6 SA</span> pour <span>grossesse</span> suivante ⭐</li>\n        <li><strong><span>Sevrage</span> tabagique</strong> systématique</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Item lié principal : 25 — <span><span class=\"nc-orange nc-bold\">Grossesse</span></span> extra-utérine · 43 — Hémorragie génitale chez la femme · 162 — IST · 332 — États de <span>choc</span></em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":0},{"id":"24-4","rang":"A","rubrique":"Diagnostic","titre":"Connaître la prise en charge d’une hémorragie du deuxième ou du troisième trimestre","contenu":"<div class=\"notion-course\"><ul><li><b>Hémorragie du deuxième ou troisième trimestre : évaluation obstétricale urgente.</b> Apprécier quantité, douleur, constantes et état fœtal ; réanimation, bilan et diagnostic peuvent être simultanés. L’importance du saignement extériorisé peut sous-estimer l’hémorragie, notamment dans l’HRP.</li><li><b>Ne pas effectuer de toucher vaginal digital avant exclusion d’un placenta prævia.</b> L’<span class=\"nc-blue_bg\">échographie</span>, y compris endovaginale, localise le placenta ; enregistrement du rythme fœtal selon terme. Bilan : NFS-<span class=\"nc-pink_bg\">plaquettes</span>, groupe/RAI, hémostase et <span class=\"nc-pink_bg\">fibrinogène</span> selon gravité ; anticiper les besoins transfusionnels. Anti-D si mère RhD négatif non immunisée et fœtus RhD positif ou inconnu, selon protocole du terme concerné.</li><li><b>Placenta prævia :</b> saignement souvent rouge et <span class=\"nc-green_bg nc-bold\">indolore</span>, <span class=\"nc-green_bg\">utérus</span> <span class=\"nc-green_bg nc-bold\">souple</span>. Préciser le recouvrement et la distance au col ; la notion de placenta bas inséré utilise généralement une distance inférieure à 20 mm, et non 50 mm. Un placenta antérieur bas sur cicatrice expose aussi au placenta accreta.</li><li><b>Placenta prævia stable :</b> surveillance et préparation de la naissance selon saignements, terme et conditions locales ; corticothérapie si naissance prématurée probable. Tocolyse seulement dans des situations sélectionnées, jamais pour retarder une naissance urgente. Pas d’alitement strict systématique prolongé.</li><li><b>Voie et terme de naissance :</b> un placenta <span class=\"nc-red nc-bold\">recouvrant</span> impose une césarienne ; hors recouvrement, décision selon distance au col, saignements et conditions obstétricales. Programmer avant le travail selon le protocole spécialisé ; ne pas retenir « après 39 SA » comme règle. Les repères varient entre recommandations (RCOG souvent 36–37 SA ; protocole régional français cité 38–38+6 SA dans certaines situations stables). Une hémorragie importante ou une anomalie fœtale impose une décision plus précoce.</li><li><b><span class=\"nc-orange nc-bold\">Hématome rétroplacentaire</span> :</b> douleur brutale, utérus contracturé, sang parfois <span class=\"nc-red nc-bold\">noirâtre</span>, troubles du rythme fœtal et coagulopathie possibles. L’<span class=\"nc-blue_bg\">échographie</span> peut être normale : elle n’exclut pas le diagnostic. Rechercher HTA/<span class=\"nc-orange_bg\">prééclampsie</span> et autres facteurs de risque.</li><li><b>HRP : avis obstétrical et réanimation immédiats.</b> <span class=\"nc-pink nc-bold\">Naissance rapide</span> si compromis maternel ou fœtal ; voie selon état maternel, vitalité fœtale et avancement du travail. En cas de <span class=\"nc-red\">mort fœtale</span>, voie basse souvent privilégiée si compatible avec la sécurité maternelle. Corriger la coagulopathie et surveiller après la naissance ; stratégie individualisée pour les formes stables.</li><li><b>Hémorragie de Benckiser :</b> rupture de vaisseaux fœtaux prævia, souvent à la rupture des membranes ; anomalie brutale du rythme alors que la mère peut rester stable. Urgence fœtale extrême nécessitant une naissance immédiate et une réanimation néonatale. Rechercher aussi rupture <span class=\"nc-pink_bg nc-bold\">utérine</span>, lésion cervicovaginale ou hématome marginal.</li><li><b>Après l’épisode :</b> surveillance clinique et biologique, traitement de l’anémie, information et prévention adaptée à la cause. Après pathologie vasculaire placentaire, discuter la prévention par aspirine d’une grossesse ultérieure selon CNGOF 2023.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":3,"liens":[{"href":"https://radiopaedia.org/articles/placenta-praevia","label":"Radiopaedia : Placenta praevia"},{"href":"https://radiopaedia.org/articles/retroplacental-haemorrhage","label":"Radiopaedia : Hématome rétroplacentaire"}]},{"id":"24-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la définition de l’hémorragie du post partum (HPP)","contenu":"<div class=\"notion-course\"><p>L’<span><span class=\"nc-orange_bg\">hémorragie du post-partum</span> (HPP)</span> est définie de manière <strong>quantitative</strong> à partir des pertes sanguines mesurées dans les <span>24 h</span> suivant l’accouchement.</p>\n\n      <h4>Définitions à connaître</h4>\n      <table>\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong>HPP</strong></td><td>Pertes sanguines <span>≥ 500 mL</span> dans les <strong><span>24 h</span> suivant l’accouchement</strong> (voie basse ou césarienne)</td></tr>\n          <tr><td><strong>HPP sévère</strong></td><td>Pertes <span>≥ 1000 mL</span> dans les <span>24 h</span></td></tr>\n          <tr><td><strong>Hémorragie de la délivrance</strong></td><td>HPP dans les <strong><span>2 h</span> post-accouchement par voie basse</strong> (période d’hémorragies immédiates les plus fréquentes)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Repères épidémiologiques</h4>\n      <ul>\n        <li><strong>Fréquence :</strong> <span>≈ 7 %</span> des accouchements (selon source de référence)</li>\n        <li><strong>1ʳᵉ cause de <span>mortalité</span> maternelle</strong> dans le monde et en France</li>\n        <li><strong>Cause principale = <span class=\"nc-red nc-bold\">atonie utérine</span></strong> (mécanisme le plus fréquent)</li>\n      </ul>\n\n      <h4>Mesure des pertes sanguines</h4>\n      <ul>\n        <li><strong>Sac de recueil sous-fessier gradué</strong> systématique à l’accouchement par voie basse — seule méthode fiable</li>\n        <li>L’estimation visuelle <strong>sous-estime</strong> systématiquement les pertes réelles ❌</li>\n        <li><strong>Évaluation horaire</strong> des pertes pendant les <span>2 h</span> post-accouchement (<span>surveillance</span> en salle de naissance)</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Mécanismes physiopathologiques.</strong> Les 4 « T » à retenir :\n        <ul>\n          <li><strong>Tonus</strong> — <span class=\"nc-red nc-bold\">atonie utérine</span> (cause n°1, ≈ <span>80 %</span>)</li>\n          <li><strong>Tissu</strong> — rétention placentaire (cotylédon, <span>placenta accreta</span>)</li>\n          <li><strong>Traumatisme</strong> — déchirure cervico-vaginale, <span>rupture utérine</span></li>\n          <li><strong>Thrombine</strong> — coagulopathie (<span>HRP</span>, <span>CIVD</span>, traitement <span>anticoagulant</span>)</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 329 — Transfusion sanguine · 332 — États de <span>choc</span> · 213 — Anémie</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":0},{"id":"24-6","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge d’une HPP","contenu":"<div class=\"notion-course\"><ul><li>Reconnaître l’hémorragie et sa dynamique : quantifier les pertes, suivre pouls, PA, conscience et diurèse. L’état clinique peut imposer le <span class=\"nc-pink_bg\">traitement</span> avant tout seuil volumique.</li><li>Alerter immédiatement obstétricien, anesthésiste et équipe ; chronométrer. Réanimation, voies veineuses, bilan NFS–plaquettes–coagulation–fibrinogène, groupage/RAI et préparation transfusionnelle en parallèle du contrôle de la cause.</li><li>Rechercher les 4 T : Tone (atonie), Tissue (rétention), Trauma (lésion), Thrombin (coagulopathie). Délivrance artificielle/révision si indiquées, examen et suture des lésions, massage utérin et oxytocine si atonie.</li><li>Acide tranexamique IV précoce dans les trois heures suivant la naissance : 1 g sur dix minutes, renouvelable une fois si le saignement persiste après trente minutes ou reprend dans les vingt-quatre heures, selon contre-indications/protocole.</li><li>Si atonie persistante : utérotonique de deuxième ligne, notamment sulprostone selon protocole, puis tamponnement intra-utérin si adapté. L’instabilité ou l’échec impose une escalade immédiate.</li><li>Embolisation si conditions hémodynamiques et disponibilité compatibles ; chirurgie d’hémostase si nécessaire, jusqu’à l’hystérectomie de sauvetage. Ne pas prolonger des étapes inefficaces ni retarder la chirurgie pour attendre une embolisation.</li></ul><figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewbox=\"0 0 620 250\" role=\"img\" aria-label=\"Frise d&#x27;escalade chronométrée de la prise en charge d&#x27;une hémorragie du post-partum. La réanimation maternelle et l&#x27;hémostase obstétricale se mènent en parallèle, jamais en série. À 0 minute : diagnostic dès 500 millilitres au sac de recueil, appel de l&#x27;obstétricien, de l&#x27;anesthésiste et de la sage-femme, chronomètre lancé. De 15 à 30 minutes : mesures obstétricales avec délivrance artificielle, révision utérine, examen sous valves et massage utérin, plus ocytocine intraveineuse en première intention. À 30 minutes en cas d&#x27;échec : sulprostone intraveineuse, Nalador, en deuxième intention. À 60 minutes en cas d&#x27;échec : embolisation artérielle si la patiente est stable, ou chirurgie d&#x27;hémostase de type B-Lynch et ligatures vasculaires, jusqu&#x27;à l&#x27;hystérectomie d&#x27;hémostase en ultime recours. En parallèle tout du long, la réanimation maternelle : deux voies veineuses, bilan NFS plaquettes TP TCA fibrinogène, remplissage et transfusion de culots, plasma et plaquettes, acide tranexamique avant 3 heures, prévention de l&#x27;hypothermie.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"700\">HPP — escalade chronométrée</text>\n          <text class=\"tx-muted\" x=\"310\" y=\"34\" text-anchor=\"middle\" font-size=\"10\">Hémostase obstétricale &amp; réa maternelle EN PARALLÈLE, jamais en série</text>\n\n          <rect class=\"fb-ok\" x=\"15\" y=\"50\" width=\"135\" height=\"84\" rx=\"6\"></rect>\n          <text class=\"tx-ok\" x=\"82\" y=\"67\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\"><span>0 min</span> — Diagnostic</text>\n          <text class=\"tx-ok\" x=\"82\" y=\"84\" text-anchor=\"middle\" font-size=\"9\"><span>≥ 500 mL</span> au sac</text>\n          <text class=\"tx-ok\" x=\"82\" y=\"98\" text-anchor=\"middle\" font-size=\"9\">Appel obst.+anesth.+SF</text>\n          <text class=\"tx-ok\" x=\"82\" y=\"112\" text-anchor=\"middle\" font-size=\"9\">Chronomètre lancé</text>\n\n          <rect class=\"fb-amber\" x=\"160\" y=\"50\" width=\"135\" height=\"84\" rx=\"6\"></rect>\n          <text class=\"tx-amber\" x=\"227\" y=\"67\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\"><span>15–30 min</span> — Obstétr.</text>\n          <text class=\"tx-amber\" x=\"227\" y=\"84\" text-anchor=\"middle\" font-size=\"9\">Délivr. artif. + révision</text>\n          <text class=\"tx-amber\" x=\"227\" y=\"98\" text-anchor=\"middle\" font-size=\"9\">Valves + massage utérin</text>\n          <text class=\"tx-amber\" x=\"227\" y=\"112\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">Oxytocine IV (1ʳᵉ int.)</text>\n\n          <rect class=\"fb-red\" x=\"305\" y=\"50\" width=\"135\" height=\"84\" rx=\"6\"></rect>\n          <text class=\"tx-red\" x=\"372\" y=\"67\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\"><span>30 min</span> ✗ — 2ᵉ ligne</text>\n          <text class=\"tx-red\" x=\"372\" y=\"87\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\">Sulprostone IV</text>\n          <text class=\"tx-red\" x=\"372\" y=\"101\" text-anchor=\"middle\" font-size=\"9\">(Nalador®, PGE2)</text>\n          <text class=\"tx-red\" x=\"372\" y=\"119\" text-anchor=\"middle\" font-size=\"8.5\">si échec oxytocine</text>\n\n          <rect class=\"fb-red\" x=\"450\" y=\"50\" width=\"155\" height=\"84\" rx=\"6\"></rect>\n          <text class=\"tx-red\" x=\"527\" y=\"67\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\"><span>60 min</span> ✗ — sauvetage</text>\n          <text class=\"tx-red\" x=\"527\" y=\"84\" text-anchor=\"middle\" font-size=\"9\">Embolisation (si stable)</text>\n          <text class=\"tx-red\" x=\"527\" y=\"98\" text-anchor=\"middle\" font-size=\"9\">ou chir. hémostase (B-Lynch)</text>\n          <text class=\"tx-red\" x=\"527\" y=\"112\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">→ hystérectomie (ultime)</text>\n\n          <line class=\"ln\" x1=\"150\" y1=\"92\" x2=\"158\" y2=\"92\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"160,92 152,88 152,96\"></polygon>\n          <line class=\"ln\" x1=\"295\" y1=\"92\" x2=\"303\" y2=\"92\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"305,92 297,88 297,96\"></polygon>\n          <line class=\"ln\" x1=\"440\" y1=\"92\" x2=\"448\" y2=\"92\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"450,92 442,88 442,96\"></polygon>\n\n          <rect class=\"fb-band\" x=\"15\" y=\"150\" width=\"590\" height=\"50\" rx=\"6\"></rect>\n          <text class=\"tx-title\" x=\"310\" y=\"169\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">⇅ EN PARALLÈLE — <span>Réanimation</span> maternelle</text>\n          <text class=\"tx-muted\" x=\"310\" y=\"186\" text-anchor=\"middle\" font-size=\"9\">2 VVP · <span>NFS</span>-plaq-TP-TCA-fibrinogène · remplissage + transfusion CGR/PFC/plaq · acide tranexamique &lt;<span> 3 h</span> · prévention <span>hypothermie</span></text>\n        </svg>\n        <figcaption>L’escalade est <strong>chronométrée</strong> : tout palier non maîtrisé en <span>30 min</span> fait passer au suivant. La <strong>bande grise</strong> = réa maternelle menée simultanément, pas après.</figcaption>\n      </figure></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":3},{"id":"24-7","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de prévention de l’HPP","contenu":"<div class=\"notion-course\"><p>La prévention de l’HPP repose sur <strong>3 piliers</strong> : identification des FR avant l’accouchement, <strong>délivrance dirigée systématique</strong>, <span>surveillance</span> rapprochée du post-partum immédiat.</p>\n\n      <h4>Identification des FR</h4>\n      <table>\n        <thead><tr><th>Catégorie</th><th><span>Facteurs de risque</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Antécédents</strong></td><td>ATCD d’HPP, <span class=\"nc-pink_bg\">ATCD de</span> <span class=\"nc-pink\">césarienne</span>, <span class=\"nc-green nc-bold\">multiparité</span> (<span>≥ 4</span>), grand âge maternel</td></tr>\n          <tr><td><strong>Distension utérine</strong></td><td><span>Grossesse</span> multiple, macrosomie, hydramnios</td></tr>\n          <tr><td><strong>Travail anormal</strong></td><td>Travail prolongé, déclenchement, dystocie, instrumentation, césarienne</td></tr>\n          <tr><td><strong>Placentaires</strong></td><td><span><span class=\"nc-red_bg\">Placenta praevia</span></span>, <span>placenta accreta</span>, <span>HRP</span>, rétention placentaire ancienne</td></tr>\n          <tr><td><strong>Coagulation</strong></td><td>Coagulopathie connue, traitement <span>anticoagulant</span>, <span>prééclampsie</span> sévère, <span>HELLP</span></td></tr>\n          <tr><td><strong>Anémie pré-accouchement</strong></td><td>Tolérance hémodynamique moindre</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Délivrance dirigée — pivot de la prévention</h4>\n      <div class=\"callout callout-info\">\n        <strong>Définition.</strong> Administration d’un <span>utérotonique</span> au moment du dégagement des épaules (voie basse) ou à l’extraction (césarienne).\n        <ul>\n          <li><strong>Molécule :</strong> <span>oxytocine 5-10 UI IV lente</span> (ou IM)</li>\n          <li><strong>Alternative :</strong> <span>carbétocine</span> (Pabal®) après césarienne</li>\n          <li><strong>Bénéfice :</strong> <span>réduction</span> du risque d’HPP de <span>≈ 60 %</span></li>\n          <li><strong>Recommandation :</strong> à proposer à <strong>toutes les patientes</strong>, indépendamment des FR</li>\n        </ul>\n      </div>\n\n      <h4>Mesures organisationnelles</h4>\n      <ul>\n        <li><strong>Sac de recueil sous-fessier gradué</strong> systématique à l’accouchement par voie basse</li>\n        <li><strong><span>Surveillance</span> des <span>2 h</span> post-partum</strong> en salle de naissance : globe utérin, pertes sanguines, constantes</li>\n        <li><strong>Protocole HPP</strong> écrit, affiché, connu de toutes les équipes</li>\n        <li><strong>Salle équipée</strong> en utérotoniques (oxytocine, sulprostone, <span>misoprostol</span>)</li>\n        <li><strong>Disponibilité immédiate</strong> de PSL (CGR, PFC) et accès rapide à l’embolisation / <span>chirurgie</span></li>\n      </ul>\n\n      <h4>Mesures spécifiques selon FR</h4>\n      <ul>\n        <li><strong>Anémie prénatale :</strong> correction par <span>fer oral / IV</span> en fin de <span>grossesse</span> (objectif Hb <span>≥ 11 g/dL</span> à l’accouchement)</li>\n        <li><strong><span>Placenta accreta</span> suspecté :</strong> orientation vers maternité avec plateau technique chirurgical complet</li>\n        <li><strong>ATCD d’HPP :</strong> <span>RCP</span> anténatale, choix d’une maternité adaptée, voie d’abord large</li>\n        <li><strong>Traitement <span>anticoagulant</span> :</strong> protocole de relais péri-accouchement</li>\n      </ul>\n\n      <h4>Information de la patiente</h4>\n      <ul>\n        <li>Explication du <strong>risque <span>hémorragique</span> du post-partum</strong> et des mesures de prévention</li>\n        <li><strong>Consentement éclairé</strong> aux gestes de sauvetage (embolisation, hystérectomie)</li>\n        <li>Anticipation des situations à risque (<span>RCP</span>, choix de la maternité)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 213 — Anémie · 326 — Anti-thrombotiques · 326 — <span>Antalgiques</span> (péridurale)</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":2},{"id":"24-8","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’hypertension artérielle (HTA) gravidique (HTAg)","contenu":"<div class=\"notion-course\"><ul><li><b>HTA pendant la grossesse :</b> PAS ≥ 140 mmHg et/ou PAD ≥ 90 mmHg, confirmée par des mesures correctes. En cas de valeur sévère (PAS ≥ 160 ou PAD ≥ 110 mmHg), confirmer rapidement et traiter sans attendre quatre heures.</li><li><b>HTA chronique :</b> connue avant la grossesse ou découverte avant 20 SA ; la réévaluation après l’accouchement permet de confirmer sa persistance. <b>HTA gestationnelle :</b> apparue après 20 SA, sans protéinurie ni signe de complication au bilan initial ; elle peut évoluer vers une <span class=\"nc-orange_bg\">prééclampsie</span>.</li><li><b><span class=\"nc-orange_bg\">Prééclampsie</span>, définition CNGOF 2023 :</b> HTA après 20 SA associée à une protéinurie ≥ 0,3 g/24 h ou un rapport protéinurie/créatininurie ≥ 30 mg/mmol. <span class=\"nc-orange_bg\">Prééclampsie</span> surajoutée si elle survient sur une HTA chronique.</li><li><b>Urgence même sans protéinurie :</b> atteinte neurologique, HELLP, œdème pulmonaire ou autre défaillance nécessite une prise en charge immédiate. Certaines définitions internationales sont plus larges ; les distinguer de la définition CNGOF.</li><li><b>Éclampsie :</b> crise convulsive dans ce contexte, après recherche des diagnostics différentiels. <b>HELLP :</b> hémolyse, élévation des enzymes hépatiques et thrombopénie. Ces complications peuvent apparaître après la naissance.</li><li><b>Mesure :</b> repos, position adaptée, brassard de bonne taille et appareil validé pour la grossesse. Automesure ou MAPA en cas de doute, sans retarder la prise en charge de signes de gravité.</li></ul><figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewbox=\"0 0 620 286\" role=\"img\" aria-label=\"Arbre de classification des troubles hypertensifs de la grossesse, définis par une PAS supérieure ou égale à 140 ou une PAD supérieure ou égale à 90, à deux reprises à 4 heures d&#x27;intervalle. Premier embranchement selon le terme. Si l&#x27;HTA est connue avant la grossesse ou apparaît avant 20 SA, c&#x27;est une HTA chronique, qui persiste au-delà de 6 semaines post-partum. Si l&#x27;HTA apparaît après 20 SA, on regarde la protéinurie et l&#x27;atteinte d&#x27;organe. Sans protéinurie et avec régression avant 6 semaines post-partum, c&#x27;est une HTA gravidique. Avec une protéinurie supérieure ou égale à 0,3 gramme par 24 heures ou une atteinte d&#x27;organe, c&#x27;est une prééclampsie. La prééclampsie peut se compliquer d&#x27;une éclampsie en cas de crise convulsive, ou d&#x27;un HELLP syndrome en cas d&#x27;hémolyse, cytolyse hépatique et thrombopénie. Note : une HTA chronique à laquelle s&#x27;ajoute une protéinurie après 20 SA définit une prééclampsie surajoutée, et environ 20 pour cent des HTA gravidiques évoluent vers une prééclampsie.\" style=\"height:auto;display:block;border-radius:8px\">\n          <rect class=\"fb-blue\" x=\"200\" y=\"10\" width=\"220\" height=\"44\" rx=\"6\"></rect>\n          <text class=\"tx-blue\" x=\"310\" y=\"29\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\"><span>HTA</span> en grossesse</text>\n          <text class=\"tx-blue\" x=\"310\" y=\"46\" text-anchor=\"middle\" font-size=\"9\">PAS <span>≥ 140</span> et/ou PAD ≥ 90 (×2,<span> 4 h</span>)</text>\n\n          <line class=\"ln\" x1=\"310\" y1=\"54\" x2=\"310\" y2=\"64\" stroke-width=\"2\"></line>\n          <line class=\"ln\" x1=\"155\" y1=\"64\" x2=\"465\" y2=\"64\" stroke-width=\"2\"></line>\n          <line class=\"ln\" x1=\"155\" y1=\"64\" x2=\"155\" y2=\"78\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"155,80 150,72 160,72\"></polygon>\n          <line class=\"ln\" x1=\"465\" y1=\"64\" x2=\"465\" y2=\"78\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"465,80 460,72 470,72\"></polygon>\n          <text class=\"tx-muted\" x=\"150\" y=\"76\" text-anchor=\"end\" font-size=\"8.5\">&lt; 20 SA</text>\n          <text class=\"tx-muted\" x=\"470\" y=\"76\" text-anchor=\"start\" font-size=\"8.5\">&gt; 20 SA</text>\n\n          <rect class=\"fb-grey\" x=\"55\" y=\"80\" width=\"200\" height=\"30\" rx=\"6\"></rect>\n          <text class=\"tx-grey\" x=\"155\" y=\"99\" text-anchor=\"middle\" font-size=\"9.5\">Connue avant grossesse / &lt; 20 SA</text>\n          <rect class=\"fb-grey\" x=\"320\" y=\"80\" width=\"270\" height=\"30\" rx=\"6\"></rect>\n          <text class=\"tx-grey\" x=\"455\" y=\"99\" text-anchor=\"middle\" font-size=\"9.5\">Apparition après 20 SA</text>\n\n          <line class=\"ln\" x1=\"155\" y1=\"110\" x2=\"155\" y2=\"122\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"155,124 150,116 160,116\"></polygon>\n\n          <rect class=\"fb-blue\" x=\"55\" y=\"124\" width=\"200\" height=\"48\" rx=\"6\"></rect>\n          <text class=\"tx-blue\" x=\"155\" y=\"144\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">HTA chronique</text>\n          <text class=\"tx-blue\" x=\"155\" y=\"161\" text-anchor=\"middle\" font-size=\"9\">persiste &gt; 6 sem post-partum</text>\n\n          <line class=\"ln\" x1=\"455\" y1=\"110\" x2=\"455\" y2=\"118\" stroke-width=\"2\"></line>\n          <line class=\"ln\" x1=\"387\" y1=\"118\" x2=\"536\" y2=\"118\" stroke-width=\"2\"></line>\n          <line class=\"ln\" x1=\"387\" y1=\"118\" x2=\"387\" y2=\"130\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"387,132 382,124 392,124\"></polygon>\n          <line class=\"ln\" x1=\"536\" y1=\"118\" x2=\"536\" y2=\"130\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"536,132 531,124 541,124\"></polygon>\n\n          <rect class=\"fb-amber\" x=\"320\" y=\"132\" width=\"135\" height=\"62\" rx=\"6\"></rect>\n          <text class=\"tx-amber\" x=\"387\" y=\"151\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">HTA gravidique</text>\n          <text class=\"tx-amber\" x=\"387\" y=\"167\" text-anchor=\"middle\" font-size=\"8.5\"><span>protéinurie</span> négative</text>\n          <text class=\"tx-amber\" x=\"387\" y=\"181\" text-anchor=\"middle\" font-size=\"8.5\">régresse &lt; 6 sem PP</text>\n\n          <rect class=\"fb-red\" x=\"468\" y=\"132\" width=\"137\" height=\"62\" rx=\"6\"></rect>\n          <text class=\"tx-red\" x=\"536\" y=\"151\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">Prééclampsie</text>\n          <text class=\"tx-red\" x=\"536\" y=\"167\" text-anchor=\"middle\" font-size=\"8.5\">+ <span>protéinurie</span> <span>≥ 0,3 g</span>/<span>24 h</span></text>\n          <text class=\"tx-red\" x=\"536\" y=\"181\" text-anchor=\"middle\" font-size=\"8.5\">ou atteinte d’organe</text>\n\n          <line class=\"ln\" x1=\"536\" y1=\"194\" x2=\"536\" y2=\"202\" stroke-width=\"2\"></line>\n          <line class=\"ln\" x1=\"501\" y1=\"202\" x2=\"572\" y2=\"202\" stroke-width=\"2\"></line>\n          <line class=\"ln\" x1=\"501\" y1=\"202\" x2=\"501\" y2=\"214\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"501,216 496,208 506,208\"></polygon>\n          <line class=\"ln\" x1=\"572\" y1=\"202\" x2=\"572\" y2=\"214\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"572,216 567,208 577,208\"></polygon>\n\n          <rect class=\"fb-red\" x=\"468\" y=\"216\" width=\"66\" height=\"40\" rx=\"5\"></rect>\n          <text class=\"tx-red\" x=\"501\" y=\"233\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\">Éclampsie</text>\n          <text class=\"tx-red\" x=\"501\" y=\"246\" text-anchor=\"middle\" font-size=\"8\">+ <span>convulsions</span></text>\n          <rect class=\"fb-red\" x=\"539\" y=\"216\" width=\"66\" height=\"40\" rx=\"5\"></rect>\n          <text class=\"tx-red\" x=\"572\" y=\"233\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\">HELLP</text>\n          <text class=\"tx-red\" x=\"572\" y=\"246\" text-anchor=\"middle\" font-size=\"8\">H · EL · LP</text>\n\n          <text class=\"tx-muted\" x=\"20\" y=\"232\" text-anchor=\"start\" font-size=\"9\">◗ HTA chronique +</text>\n          <text class=\"tx-muted\" x=\"20\" y=\"245\" text-anchor=\"start\" font-size=\"9\"><span>protéinurie</span> &gt; 20 SA</text>\n          <text class=\"tx-muted\" x=\"20\" y=\"258\" text-anchor=\"start\" font-size=\"9\">= PE surajoutée</text>\n          <text class=\"tx-muted\" x=\"20\" y=\"276\" text-anchor=\"start\" font-size=\"9\">◗ ~<span>20 %</span> HTAg → prééclampsie</text>\n        </svg>\n        <figcaption>Le <strong>pivot diagnostique</strong> : le terme (avant/après 20 SA) puis la <strong><span>protéinurie</span> / atteinte d’organe</strong>. HTAg pure = bon <span>pronostic</span> ; <span>prééclampsie</span> = <span>urgence</span> obstétricale.</figcaption>\n      </figure></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":2},{"id":"24-9","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la fréquence de l’HTAg","contenu":"<div class=\"notion-course\"><p>L’<span>HTA</span> pendant la <span>grossesse</span> est <strong>fréquente</strong> et constitue l’une des principales causes de morbi-<span>mortalité</span> maternelle et fœtale dans les pays développés.</p>\n\n      <h4>Données épidémiologiques</h4>\n      <table>\n        <thead><tr><th>Entité</th><th>Fréquence</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Troubles hypertensifs de la <span>grossesse</span> (toutes formes)</strong></td><td><span>10-15 %</span> des grossesses</td></tr>\n          <tr><td><strong><span>HTA</span> gravidique (HTAg)</strong></td><td><span>5-10 %</span> des grossesses</td></tr>\n          <tr><td><strong><span>Prééclampsie</span></strong></td><td><span>2-3 %</span> des grossesses en France (<span>5-7 %</span> primipares, <span>1-2 %</span> multipares)</td></tr>\n          <tr><td><strong><span>Prééclampsie</span> sévère</strong></td><td><span>~ 1 %</span> des grossesses</td></tr>\n          <tr><td><strong><span>Éclampsie</span></strong></td><td><span>1/2 000 à 1/3 000</span> grossesses</td></tr>\n          <tr><td><strong><span>HELLP</span> syndrome</strong></td><td><span>~ 0,5 %</span> des grossesses, complique <span>10-20 %</span> des prééclampsies sévères</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span>Mortalité</span> maternelle</h4>\n      <ul>\n        <li>La <strong><span><span class=\"nc-orange_bg\">prééclampsie</span></span>/<span>éclampsie</span></strong> est la <strong>2ᵉ cause de <span>mortalité</span> maternelle</strong> en France (après l’HPP)</li>\n        <li><strong>1ʳᵉ cause de <span>mortalité</span> maternelle</strong> par cause directe dans les pays développés selon certaines séries</li>\n        <li><strong>~ 30 décès maternels / an</strong> en France attribuables aux troubles hypertensifs</li>\n      </ul>\n\n      <h4><span>Mortalité</span> et morbidité fœtales</h4>\n      <ul>\n        <li><strong>1ʳᵉ cause d’accouchement prématuré induit</strong> (~ <span>15 %</span> des AP &lt; <span>32 SA</span>)</li>\n        <li><strong>1ʳᵉ cause de <span>RCIU</span></strong> d’origine vasculaire</li>\n        <li>Risque de <strong>mort fœtale in utero</strong> par <span>HRP</span> ou insuffisance placentaire sévère</li>\n      </ul>\n\n      <h4><span>Facteurs de risque</span> épidémiologiques</h4>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Facteurs</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Terrain</span></strong></td><td>Primiparité, âge &gt;<span> 35 ans</span> (ou &lt; 18), <span>obésité</span>, origine afro-caribéenne</td></tr>\n          <tr><td><strong>Antécédents</strong></td><td>ATCD personnel de <span>prééclampsie</span> (RR × 7), ATCD familial de <span>prééclampsie</span> au 1ᵉʳ degré</td></tr>\n          <tr><td><strong>Pathologies associées</strong></td><td><span>HTA</span> chronique, <span>diabète</span> préexistant, néphropathie chronique, <span>lupus</span> / SAPL, thrombophilie</td></tr>\n          <tr><td><strong><span>Grossesse</span></strong></td><td><span>Grossesse</span> multiple, grossesse issue de don d’ovocyte, intervalle long entre grossesses</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span>HTA</span> · 344 — HTA gravidique et <span class=\"nc-orange_bg\">prééclampsie</span> · 255 — <span>Diabète gestationnel</span> · 22 — Maladies rares</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":0},{"id":"24-10","rang":"B","rubrique":"Examens complémentaires","titre":"Savoir prescrire et interpréter les examens complémentaires en cas d’HTA gravidique","contenu":"<div class=\"notion-course\"><ul><li><b>Trois objectifs :</b> distinguer HTA gestationnelle et prééclampsie, rechercher une atteinte maternelle et apprécier le retentissement fœtal. Interpréter les résultats avec le terme, les symptômes et leur évolution.</li><li><b>Protéinurie :</b> quantification des 24 h ou rapport protéinurie/créatininurie sur échantillon. Les seuils ≥ 0,3 g/24 h ou ≥ 30 mg/mmol s’interprètent avec une HTA apparue après 20 SA ; une protéinurie isolée ne suffit pas à définir la <span class=\"nc-orange_bg\">prééclampsie</span>.</li><li><b>Bilan maternel :</b> NFS-plaquettes, créatinine, transaminases ; LDH, haptoglobine, bilirubine et frottis si hémolyse suspectée. Hémostase/fibrinogène selon gravité, saignement ou thrombopénie. L’uricémie ne pose pas à elle seule le diagnostic et ne décide pas seule de la naissance.</li><li><b>HELLP :</b> arguments d’hémolyse, cytolyse hépatique et thrombopénie ; douleur épigastrique ou de l’hypochondre droit fait rechercher une complication hépatique. Une anomalie évolutive peut précéder un syndrome complet.</li><li><b>Fœtus :</b> échographie de croissance et liquide amniotique, Doppler et surveillance du rythme selon indication. Un poids estimé inférieur au 10e percentile définit un petit poids pour l’âge gestationnel ; la restriction de croissance nécessite le contexte et la dynamique, pas le percentile seul.</li><li><b>Examens orientés :</b> imagerie cérébrale si signe neurologique atypique/persistant, bilan cardiopulmonaire si dyspnée ou douleur thoracique. PlGF ou ratio sFlt-1/PlGF ne sont pas recommandés en routine par CNGOF 2023 dans le seul but de réduire la morbidité.</li><li><b>Pas de bilan systématique de thrombophilie héréditaire après <span class=\"nc-orange_bg\">prééclampsie</span> isolée.</b> La recherche d’un SAPL est discutée séparément selon les critères obstétricaux et le contexte. Adapter la répétition des examens à la gravité et à l’évolution.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":3},{"id":"24-11","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les complications de l’HTAg","contenu":"<div class=\"notion-course\"><p>L’<span>HTA</span> gravidique expose à des <strong>complications maternelles</strong> (<span><span class=\"nc-orange_bg\">prééclampsie</span></span> et ses formes graves) et <strong>fœtales</strong> (<span>RCIU</span>, prématurité induite, <span>MFIU</span>).</p>\n\n      <h4>Complications maternelles</h4>\n      <table>\n        <thead><tr><th>Complication</th><th>Mécanisme / clinique</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Prééclampsie</span></strong></td><td>~ <span>20 %</span> des HTAg pures évoluent vers <span>prééclampsie</span> (<span>HTA</span> + <span>protéinurie</span>)</td></tr>\n          <tr><td><span>Éclampsie</span></td><td><span>Crise convulsive</span> tonico-clonique généralisée sur <span><span class=\"nc-orange_bg\">prééclampsie</span></span> — peut survenir <em>avant, pendant ou après</em> l’accouchement (jusqu’à <span>7 jours</span> post-partum)</td></tr>\n          <tr><td><span>HELLP syndrome</span></td><td>Hémolyse + cytolyse hépatique + thrombopénie ; risque <strong>d’hématome sous-capsulaire du foie</strong></td></tr>\n          <tr><td><span>Hématome rétroplacentaire (HRP)</span></td><td>Décollement prématuré → <span>CIVD</span> + souffrance fœtale ; <em>fréquemment associé à l’HTAg / <span><span class=\"nc-orange_bg\">prééclampsie</span></span></em></td></tr>\n          <tr><td><strong><span>Insuffisance rénale aiguë</span></strong></td><td><span>NTA</span>, voire <span>nécrose</span> corticale ; favorisée par hypovolémie + <span>CIVD</span></td></tr>\n          <tr><td><strong><span>Œdème aigu pulmonaire</span> (<span>OAP</span>)</strong></td><td>Surcharge + altération de la perméabilité capillaire</td></tr>\n          <tr><td><strong><span>AVC</span> <span>hémorragique</span></strong></td><td>Cause principale de <span>mortalité</span> maternelle dans la <span>prééclampsie</span> sévère</td></tr>\n          <tr><td><strong><span>PRES</span> syndrome</strong> (<span>œdème</span> cérébral postérieur réversible)</td><td><span>Céphalées</span> + troubles visuels + crises ; <span>IRM</span> caractéristique</td></tr>\n          <tr><td><strong><span>CIVD</span></strong></td><td>Surtout en cas de <span>HELLP</span>, <span>HRP</span> ou <span>hémorragie massive</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Complications fœtales</h4>\n      <table>\n        <thead><tr><th>Complication</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>RCIU</span> (retard de croissance intra-utérin)</strong></td><td>Insuffisance vasculaire utéroplacentaire ; surtout en cas de <span><span class=\"nc-orange_bg\">prééclampsie</span></span> précoce</td></tr>\n          <tr><td><strong>Prématurité induite</strong></td><td>Accouchement déclenché pour sauvetage maternel ou fœtal</td></tr>\n          <tr><td><strong>Souffrance fœtale aiguë</strong></td><td>Anomalies du RCF, oligoamnios, <span>doppler</span> ombilical pathologique</td></tr>\n          <tr><td><strong>Mort fœtale in utero (<span>MFIU</span>)</strong></td><td>Insuffisance placentaire sévère ou <span>HRP</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Complications du post-partum à connaître</h4>\n      <ul>\n        <li><strong><span>Éclampsie</span> du post-partum</strong> — possible jusqu’à <strong><span>7 jours</span> après l’accouchement</strong> ⚠️</li>\n        <li><strong>Persistance de l’<span>HTA</span></strong> au-delà de <span>6 semaines</span> → réévaluer en cardio (<span>HTA</span> chronique sous-jacente ?)</li>\n        <li><strong><span>Thrombose veineuse profonde</span> / EP</strong> — risque <span>MTEV</span> majoré</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong>Triade de l’<span>éclampsie</span> imminente.</strong>\n        <ul>\n          <li><span>Céphalées intenses</span> (en casque, frontales)</li>\n          <li><span>Troubles visuels</span> (phosphènes, flou visuel, scotomes)</li>\n          <li><span>Douleur épigastrique en barre</span> (signe de Chaussier — distension de la capsule de Glisson)</li>\n        </ul>\n        <strong>Hyperréflexie ostéo-tendineuse</strong> souvent associée.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span>HTA</span> · 344 — HTA gravidique et <span class=\"nc-orange_bg\">prééclampsie</span> · 332 — États de <span>choc</span> · 105 — Épilepsies · 213 — Anémie</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":0},{"id":"24-12","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les éléments de sévérité","contenu":"<div class=\"notion-course\"><p>L’identification des <strong><span>critères de</span> sévérité</strong> conditionne la <strong>conduite à tenir immédiate</strong> : <span>hospitalisation</span>, <span>surveillance</span> rapprochée, indication d’accouchement.</p>\n\n      <h4><span>Critères de</span> sévérité maternels — Cliniques</h4>\n      <div class=\"callout callout-danger\">\n        <strong><span>HTA</span> sévère.</strong>\n        <ul>\n          <li><span>PAS ≥ 160 mmHg</span> et/ou <span>PAD ≥ 110 mmHg</span></li>\n        </ul>\n        <strong>Signes fonctionnels d’<span>éclampsie</span> imminente.</strong>\n        <ul>\n          <li><span>Céphalées intenses, rebelles aux antalgiques</span></li>\n          <li><span>Troubles visuels :</span> phosphènes, flou, scotomes, amaurose</li>\n          <li><span>Douleur épigastrique en barre (signe de Chaussier)</span></li>\n          <li><span>Nausées / vomissements</span></li>\n          <li><span>Hyperréflexie ostéo-tendineuse</span></li>\n          <li><span>Crise convulsive</span> = <span>éclampsie</span> déclarée</li>\n        </ul>\n        <strong>Signes d’hypoperfusion / <span>défaillance</span>.</strong>\n        <ul>\n          <li><strong><span>Oligurie</span></strong> (&lt; <span>500 mL</span>/<span>24 h</span>)</li>\n          <li><strong><span>OAP</span></strong> (<span>dyspnée</span>, <span>crépitants</span>)</li>\n          <li><strong>Troubles de la conscience</strong></li>\n        </ul>\n      </div>\n\n      <h4><span>Critères de</span> sévérité — Biologiques</h4>\n      <table>\n        <thead><tr><th>Paramètre</th><th>Seuil de sévérité</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Protéinurie</span></strong></td><td>&gt; <span>3 g / 24 h</span> (<span>prééclampsie</span> sévère)</td></tr>\n          <tr><td><strong><span>Créatininémie</span></strong></td><td>&gt; <span>90 µmol/L</span> ou doublement de la créat de base</td></tr>\n          <tr><td><strong><span>Plaquettes</span></strong></td><td>&lt; <span>100 G/L</span> (<span>HELLP</span>)</td></tr>\n          <tr><td><strong>Transaminases (<span>ASAT</span>/<span>ALAT</span>)</strong></td><td>&gt; <span>2 × normale</span> (<span>HELLP</span>)</td></tr>\n          <tr><td><strong><span>LDH</span> + <span>bilirubine</span></strong></td><td>↑ + <span>haptoglobine</span> ↓ = hémolyse (<span>HELLP</span>)</td></tr>\n          <tr><td><strong>Uricémie</strong></td><td>Élevée et corrélée à la sévérité</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span>Critères de</span> sévérité — Fœtaux</h4>\n      <ul>\n        <li><strong><span>RCIU</span> sévère</strong> &lt; 3ᵉ percentile</li>\n        <li><strong>Oligoamnios</strong> sévère (index amniotique <span>≤ 5</span>)</li>\n        <li><strong><span>Doppler</span> ombilical pathologique</strong> : <span>diastole nulle ou reverse-flow</span></li>\n        <li><strong>Anomalies sévères du RCF</strong></li>\n        <li><strong>Mort fœtale in utero</strong></li>\n      </ul>\n\n      <h4>Critères selon le terme</h4>\n      <ul>\n        <li><strong><span>Prééclampsie</span> précoce &lt; <span>32-34 SA</span></strong> → forme habituellement plus sévère, <span>pronostic</span> moins bon</li>\n        <li><strong><span>Prééclampsie</span> tardive <span>≥ 34 SA</span></strong> → <span>pronostic</span> globalement meilleur</li>\n      </ul>\n\n      <h4>Conduite à tenir devant un <span>critère de</span> sévérité</h4>\n      <ol>\n        <li><strong><span>Hospitalisation</span> immédiate</strong> en maternité de niveau adapté (3 si &lt; <span>32 SA</span>)</li>\n        <li><strong>Bilan complet</strong> maternel + fœtal (cf. obj-9)</li>\n        <li><strong>Traitement antihypertenseur</strong> en <span>urgence</span> si <span>HTA</span> sévère (cf. obj-12)</li>\n        <li><strong>Sulfate de magnésium</strong> en prévention de l’<span>éclampsie</span> si signes neurologiques</li>\n        <li><strong><span>Corticothérapie</span> prénatale</strong> &lt; <span>34 SA</span> (préparation à l’accouchement éventuel)</li>\n        <li><strong>Discussion d’extraction fœtale</strong> selon terme et tolérance maternelle</li>\n      </ol>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span>HTA</span> · 344 — HTA gravidique et <span class=\"nc-orange_bg\">prééclampsie</span> · 332 — États de <span>choc</span> · 105 — Épilepsies · 359 — <span>Détresse</span> respiratoire aiguë</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":0},{"id":"24-13","rang":"B","rubrique":"Prise en charge","titre":"Savoir prescrire les mesures de repos et le traitement antihypertenseur chez une femme enceinte","contenu":"<div class=\"notion-course\"><p>La PEC de l’HTAg associe <strong>mesures non médicamenteuses</strong>, <strong>antihypertenseurs adaptés à la <span>grossesse</span></strong>, et <strong>traitement spécifique des formes sévères</strong> (sulfate de Mg, accouchement).</p>\n\n      <h4>Mesures non médicamenteuses</h4>\n      <table>\n        <thead><tr><th>Mesure</th><th>Recommandation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Repos relatif</strong></td><td><strong>Pas d’alitement strict</strong> ❌ (majore le risque de <span>MTEV</span>) — <strong>repos modulé</strong>, arrêt de travail si pénible</td></tr>\n          <tr><td><strong>Arrêt de travail</strong></td><td>Selon situation et terme</td></tr>\n          <tr><td><strong>Régime</strong></td><td><strong>Pas de régime hyposodé</strong> ❌ — peut aggraver l’hypovolémie maternelle</td></tr>\n          <tr><td><strong>Bas de contention</strong></td><td>Prévention de la <span>MTEV</span> en cas de repos</td></tr>\n          <tr><td><strong><span>Surveillance</span> domicile</strong></td><td>Auto-mesure tensionnelle, recherche signes d’alerte</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Antihypertenseurs autorisés pendant la <span>grossesse</span></h4>\n      <table>\n        <thead><tr><th>Classe</th><th>Molécules</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Antihypertenseurs centraux</strong></td><td><span>Alpha-méthyldopa</span> (Aldomet®)</td><td><strong>1ʳᵉ intention historique</strong>, recul d’utilisation pendant la <span>grossesse</span>, bonne tolérance fœtale</td></tr>\n          <tr><td><strong><span>Inhibiteurs calciques</span></strong></td><td><span>Nicardipine</span> (Loxen®), <span>Nifédipine</span></td><td><strong>1ʳᵉ intention</strong> orale et IV ; rapide d’action, utilisable en aigu</td></tr>\n          <tr><td><strong><span>Bêtabloquants</span></strong></td><td><span>Labétalol</span> (Trandate®, α + β-)</td><td><strong>1ʳᵉ intention</strong> particulièrement en aigu IV ; alternative orale</td></tr>\n          <tr><td><strong>Vasodilatateurs périphériques</strong></td><td><span>Clonidine</span></td><td>Réserve</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Antihypertenseurs CONTRE-INDIQUÉS pendant la <span>grossesse</span></h4>\n      <div class=\"callout callout-danger\">\n        <strong><span>Contre-indications</span> absolues — à connaître ⭐.</strong>\n        <ul>\n          <li><span>IEC</span> (énalapril, <span>ramipril</span>...) — <strong>fœtotoxicité</strong> : oligoamnios, <span>IRA</span> fœtale, malformations rénales</li>\n          <li><span>ARA II / sartans</span> (<span>losartan</span>, <span>valsartan</span>...) — <strong>même toxicité que les <span>IEC</span></strong></li>\n          <li><span>Inhibiteurs directs de la rénine</span> (aliskirène)</li>\n          <li><span>Diurétiques</span> (sauf indication spécifique : <span>OAP</span>, IC) — risque d’hypoperfusion utéroplacentaire</li>\n        </ul>\n      </div>\n\n      <h4>Objectifs tensionnels</h4>\n      <table>\n        <thead><tr><th>Situation</th><th>Objectif PA</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>HTA</span> non sévère</strong></td><td>PAS &lt; <span>150 mmHg</span> et PAD &lt; <span>100 mmHg</span> (objectif large, pas trop bas pour préserver la perfusion utéroplacentaire)</td></tr>\n          <tr><td><strong><span>HTA</span> sévère (PAS <span>≥ 160</span> ou PAD ≥ 110)</strong></td><td><span>Réduction</span> progressive vers PAS 140-150 / PAD 90-100 — <strong>pas de chute brutale</strong> ⚠️ (risque d’hypoperfusion fœtale)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Stratégie thérapeutique selon sévérité</h4>\n      <ul>\n        <li><strong>HTAg modérée :</strong> traitement oral (alpha-méthyldopa OU nicardipine OU <span>labétalol</span>), monothérapie en 1ʳᵉ intention</li>\n        <li><strong>HTAg sévère (<span>urgence</span>) :</strong> <span>hospitalisation</span> + <span>nicardipine IV à la seringue électrique</span> ou <span>labétalol IV</span></li>\n        <li><strong>Bithérapie</strong> si <span>HTA</span> non contrôlée par la monothérapie</li>\n      </ul>\n\n      <h4>Sulfate de magnésium — prévention de l’<span>éclampsie</span></h4>\n      <div class=\"callout callout-warn\">\n        <strong>Indications du sulfate de Mg ⭐.</strong>\n        <ul>\n          <li><strong><span>Prééclampsie</span> sévère</strong> avec signes neurologiques (<span>céphalées</span>, phosphènes, hyperréflexie)</li>\n          <li><strong><span>Éclampsie</span></strong> (traitement curatif)</li>\n          <li><strong>Neuroprotection fœtale</strong> avant <span>32 SA</span> en cas de naissance imminente</li>\n        </ul>\n        <strong>Posologie :</strong> dose de charge <span>4 g</span> IVL en <span>20 min</span> puis entretien <span>1 g/h</span>.<br>\n        <strong><span>Surveillance</span> :</strong> ROT (disparition = surdosage), FR (&gt;<span> 12/min</span>), diurèse.<br>\n        <strong>Antidote :</strong> gluconate de calcium IV.\n      </div>\n\n      <h4>Indications d’extraction fœtale</h4>\n      <ul>\n        <li><strong>HTAg non sévère :</strong> accouchement à partir de <strong><span>37-38 SA</span></strong></li>\n        <li><strong><span>Prééclampsie</span> modérée :</strong> accouchement à <strong><span>37 SA</span></strong></li>\n        <li><strong><span>Prééclampsie</span> sévère :</strong> accouchement <strong>quel que soit le terme</strong> (<span>urgence</span> si retentissement maternel ou fœtal)</li>\n        <li><strong><span>Éclampsie</span> / <span>HELLP</span> / <span>HRP</span> :</strong> accouchement en <span>urgence</span> (césarienne le plus souvent)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span>HTA</span> · 326 — Prescription des antihypertenseurs · 344 — HTA gravidique et <span class=\"nc-orange_bg\">prééclampsie</span> · 359 — <span>Détresse</span> respiratoire aiguë</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":4},{"id":"24-14","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Savoir surveiller une HTAg","contenu":"<div class=\"notion-course\"><p>La <span>surveillance</span> d’une HTAg doit être <strong>rapprochée et structurée</strong>, à la fois <strong>maternelle</strong> (recherche d’<span>évolution</span> vers une <span>prééclampsie</span>, d’une sévérité) et <strong>fœtale</strong> (croissance, bien-être, perfusion).</p>\n\n      <h4>Rythme de <span>surveillance</span> — HTAg pure (non sévère, sans <span>protéinurie</span>)</h4>\n      <table>\n        <thead><tr><th>Volet</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Consultations</strong></td><td><strong>Toutes les <span>1 à 2 semaines</span></strong> selon <span>évolution</span></td></tr>\n          <tr><td><strong>Auto-mesure tensionnelle</strong></td><td>Plusieurs fois/jour à domicile, carnet de <span>surveillance</span></td></tr>\n          <tr><td><strong><span>Bandelette urinaire</span></strong></td><td>À chaque consultation — <span>dépistage</span> de l’apparition d’une <span>protéinurie</span></td></tr>\n          <tr><td><strong>Biologie</strong></td><td><span>NFS</span> <span>plaquettes</span>, <span>créatinine</span>, <span>ASAT</span>/<span>ALAT</span>, <span>uricémie</span>, <span>protéinurie</span>/<span>24 h</span> <strong>toutes les <span>2 semaines</span></strong></td></tr>\n          <tr><td><strong><span>Échographie</span> fœtale</strong></td><td><strong>Toutes les <span>3-4 semaines</span></strong> — croissance, <span>doppler</span> ombilical/utérin</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Critères imposant une <span>hospitalisation</span></h4>\n      <div class=\"callout callout-danger\">\n        <strong><span>Hospitalisation</span> immédiate si :</strong>\n        <ul>\n          <li><span>HTA sévère</span> (PAS <span>≥ 160</span> ou PAD ≥ 110)</li>\n          <li><span>Apparition de protéinurie</span> <span>≥ 0,3 g/24 h</span></li>\n          <li><span>Signes neurologiques</span> (<span>céphalées</span>, troubles visuels)</li>\n          <li><span>Signes biologiques</span> de <span>HELLP</span> ou <span>IRA</span></li>\n          <li><span>RCIU</span> ou <span>doppler</span> ombilical pathologique</li>\n          <li><strong>Mauvaise observance</strong>, <span>surveillance</span> ambulatoire impossible</li>\n        </ul>\n      </div>\n\n      <h4>Auto-<span>surveillance</span> — éducation de la patiente</h4>\n      <ul>\n        <li><strong>Auto-mesure tensionnelle</strong> matin + soir + en cas de symptôme</li>\n        <li><strong>Signes d’alerte</strong> à connaître et signaler en <span>urgence</span> : <span>céphalées</span>, phosphènes, douleur épigastrique, <span>nausées</span>, diminution des mouvements fœtaux</li>\n        <li><strong>Carnet de <span>surveillance</span></strong> avec chiffres tensionnels et symptômes</li>\n        <li><strong>Numéro d’<span>urgence</span></strong> de la maternité</li>\n      </ul>\n\n      <h4><span>Surveillance</span> fœtale — <span>critères de</span> bien-être</h4>\n      <ul>\n        <li><strong>Mouvements actifs fœtaux</strong> ressentis par la mère</li>\n        <li><strong><span>Échographie</span> :</strong> croissance, biométrie (poids estimé), quantité de liquide amniotique</li>\n        <li><strong><span>Doppler</span> ombilical :</strong> recherche d’une diminution du flux diastolique, signe d’insuffisance placentaire</li>\n        <li><strong>RCF / Cardiotocographie</strong> en <span>hospitalisation</span> si <span>HTA</span> mal contrôlée ou signes de sévérité</li>\n      </ul>\n\n      <h4>Lieux de prise en charge</h4>\n      <ul>\n        <li><strong>HTAg modérée bien contrôlée :</strong> <span>surveillance</span> ambulatoire en consultation</li>\n        <li><strong>HTAg sévère ou <span>prééclampsie</span> :</strong> <span>hospitalisation</span> en maternité de niveau adapté</li>\n        <li><strong>Avant <span>32 SA</span> + retentissement fœtal :</strong> <strong>maternité de niveau 3</strong> (réa néonatale)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 224 — <span>HTA</span> · 344 — HTA gravidique et <span class=\"nc-orange_bg\">prééclampsie</span></em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":1},{"id":"24-15","rang":"B","rubrique":"Prise en charge","titre":"Connaître la conduite à tenir après l’accouchement en cas d’HTAg","contenu":"<div class=\"notion-course\"><p>Le post-partum est une période <strong>à haut risque</strong> chez les patientes ayant présenté une HTAg/<span><span class=\"nc-orange_bg\">prééclampsie</span></span>. L’<span>éclampsie</span> peut survenir <strong>jusqu’à <span>7 jours</span> après l’accouchement</strong>. La <span>surveillance</span> et le traitement doivent être poursuivis.</p>\n\n      <h4><span>Surveillance</span> immédiate (premières <span>48 h</span>)</h4>\n      <ul>\n        <li><strong>Monitorage tensionnel</strong> rapproché (toutes les <span>4 h</span>, puis allégé selon <span>évolution</span>)</li>\n        <li><strong><span>Surveillance</span> neurologique</strong> : ROT, <span>céphalées</span>, troubles visuels (risque d’<span>éclampsie</span> post-partum jusqu’à <strong><span>7 jours</span></strong>)</li>\n        <li><strong>Diurèse</strong> horaire pendant <span>24 h</span> (<span>surveillance</span> fonction rénale)</li>\n        <li><strong>Bilan <span>biologique</span></strong> à <span>H6</span>, H24, H48 : <span>NFS</span> <span>plaquettes</span>, créat, <span>ASAT</span>/<span>ALAT</span>, <span>LDH</span> (recherche aggravation <span>HELLP</span>)</li>\n        <li><strong>Poursuite du sulfate de Mg</strong> <span>24 h</span> après l’accouchement si <span><span class=\"nc-orange_bg\">prééclampsie</span></span> sévère / <span>éclampsie</span></li>\n      </ul>\n\n      <h4><span>Évolution</span> attendue de l’<span>HTA</span></h4>\n      <table>\n        <thead><tr><th>Phase</th><th>Évolution typique</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>J0</span>-J3</strong></td><td>Possibilité d’aggravation transitoire de l’<span>HTA</span> (pic des résistances vasculaires)</td></tr>\n          <tr><td><strong><span>J3</span>-J10</strong></td><td>Diurèse augmentée, baisse progressive de la TA</td></tr>\n          <tr><td><strong>J10-S6</strong></td><td>Normalisation tensionnelle attendue dans l’HTAg pure</td></tr>\n          <tr><td><strong>&gt; <span>6 semaines</span></strong></td><td>Persistance de l’<span>HTA</span> → suspicion d’<strong><span>HTA</span> chronique sous-jacente</strong> (<span>réévaluation</span> cardio)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Adaptation du traitement antihypertenseur</h4>\n      <ul>\n        <li><strong>Poursuite</strong> de l’antihypertenseur en post-partum, en adaptant la posologie à la TA</li>\n        <li><strong>Décroissance progressive</strong> sur <span>2-6 semaines</span> en cas de normalisation</li>\n        <li><strong>Possibilité d’élargir l’éventail</strong> de molécules après l’accouchement (les <span>IEC</span> redeviennent utilisables — <strong>captopril, énalapril</strong> sont compatibles avec l’<span>allaitement</span>)</li>\n      </ul>\n\n      <h4><span>Allaitement</span></h4>\n      <table>\n        <thead><tr><th>Molécule</th><th>Compatibilité allaitement</th></tr></thead>\n        <tbody>\n          <tr><td><span>Alpha-méthyldopa</span></td><td>Compatible</td></tr>\n          <tr><td><span>Nicardipine</span></td><td>Compatible</td></tr>\n          <tr><td><span>Labétalol</span></td><td>Compatible (préférer aux <span>bêtabloquants</span> liposolubles)</td></tr>\n          <tr><td><span>Captopril / Énalapril</span></td><td>Compatible avec l’<span>allaitement</span> (en post-partum uniquement, jamais pendant la grossesse)</td></tr>\n          <tr><td><span>Diurétiques</span></td><td>Peuvent diminuer la lactation</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Prévention thromboembolique</h4>\n      <ul>\n        <li>Le post-partum d’une HTAg / <span><span class=\"nc-orange_bg\">prééclampsie</span></span> est un <strong>contexte à risque accru de <span>MTEV</span></strong></li>\n        <li><strong>Thromboprophylaxie par <span>HBPM</span></strong> à discuter (durée <span>6 semaines</span> selon FR associés)</li>\n        <li><strong>Bas de contention</strong> + mobilisation précoce</li>\n      </ul>\n\n      <h4>Consultation post-natale (<span>6-8 semaines</span>)</h4>\n      <ul>\n        <li><strong><span>Réévaluation</span> tensionnelle</strong> — confirmer la résolution ou identifier une <span>HTA</span> chronique</li>\n        <li><strong>Bilan rénal complet</strong> (créat, <span>protéinurie</span>/<span>24 h</span>)</li>\n        <li><strong>Information sur le risque cardiovasculaire à long terme</strong> (cf. obj-16)</li>\n        <li><strong>Discussion des grossesses ultérieures</strong> (cf. obj-15)</li>\n        <li><strong>Choix contraceptif</strong> tenant compte des FR vasculaires (privilégier méthodes non-œstrogéniques)</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong><span>Éclampsie</span> du post-partum.</strong> Survenue possible jusqu’à <strong><span>7 jours</span> après l’accouchement</strong>. <span>Surveillance</span> neurologique active + maintien du sulfate de Mg <span>24 h</span> après la naissance dans les prééclampsies sévères.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span>HTA</span> · 326 — Anti-thrombotiques · 344 — HTA gravidique et <span class=\"nc-orange_bg\">prééclampsie</span> · 36 — Contraception</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":0},{"id":"24-16","rang":"A","rubrique":"Prise en charge","titre":"Connaître la prévention lors des grossesses ultérieures","contenu":"<div class=\"notion-course\"><p>Après une HTAg ou une <span><span class=\"nc-orange_bg\">prééclampsie</span></span>, le risque de <strong>récidive lors d’une <span>grossesse</span> ultérieure est significatif</strong> : <span>10-20 %</span> pour la <span><span class=\"nc-orange_bg\">prééclampsie</span></span> (jusqu’à <span>40 %</span> en cas de PE précoce sévère). La <strong>prévention par <span>aspirine</span></strong> est le pivot.</p>\n\n      <h4>Risque de récidive</h4>\n      <table>\n        <thead><tr><th>Contexte</th><th>Risque de récidive</th></tr></thead>\n        <tbody>\n          <tr><td><strong>HTAg pure (non compliquée)</strong></td><td>Risque modéré de récidive d’HTAg, faible risque de <span>prééclampsie</span></td></tr>\n          <tr><td><strong><span>Prééclampsie</span> modérée à terme</strong></td><td><span>~ 10-15 %</span> de récidive</td></tr>\n          <tr><td><strong><span>Prééclampsie</span> sévère ou précoce (&lt; <span>34 SA</span>)</strong></td><td><span>~ 30-40 %</span> de récidive</td></tr>\n          <tr><td><strong>Antécédent d’<span>éclampsie</span> ou <span>HELLP</span></strong></td><td>Risque élevé de récidive (idem PE sévère)</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span>Aspirine</span> faible dose — pivot de la prévention</h4>\n      <div class=\"callout callout-info\">\n        <strong>Indications de l’<span>aspirine 100-160 mg/jour</span> ⭐.</strong>\n        <ul>\n          <li><strong>ATCD personnel de <span>prééclampsie</span></strong> (surtout précoce ou sévère)</li>\n          <li><strong><span>HTA</span> chronique</strong> ou <strong>néphropathie chronique</strong></li>\n          <li><strong><span>Diabète</span> préexistant</strong> (<span>DT1</span> ou <span>DT2</span>)</li>\n          <li><strong><span>Lupus</span> / SAPL</strong> connu</li>\n          <li>Présence de <strong><span>≥ 2</span> FR modérés</strong> : 1ʳᵉ <span>grossesse</span>, âge &gt;<span> 35-40 ans</span>, IMC <span>≥ 35,</span> ATCD familial PE, intervalle long entre grossesses, grossesse multiple, origine afro-caribéenne</li>\n        </ul>\n        <strong>Modalités :</strong>\n        <ul>\n          <li><strong>Début :</strong> entre 12 et <span>16 SA</span> (au plus tard avant <span>20 SA</span>)</li>\n          <li><strong>Prise vespérale</strong> (efficacité maximale démontrée)</li>\n          <li><strong>Arrêt à <span>35-36 SA</span></strong> (avant l’accouchement)</li>\n          <li><strong><span>Réduction</span> du risque de PE de <span>40-60 %</span></strong> dans les indications validées</li>\n        </ul>\n      </div>\n\n      <h4>Autres mesures préventives</h4>\n      <table>\n        <thead><tr><th>Mesure</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Consultation préconceptionnelle</strong></td><td>Bilan complet de la pathologie sous-jacente, optimisation du traitement (substitution <span>IEC</span>/ARA II → alpha-méthyldopa/<span>labétalol</span>), équilibration du <span>diabète</span>, <span>perte de poids</span></td></tr>\n          <tr><td><strong>Supplémentation en calcium</strong></td><td><span>1 g/jour</span> recommandée chez les femmes à apport calcique faible (efficacité modérée)</td></tr>\n          <tr><td><strong><span>Sevrage</span> tabagique</strong></td><td>Important — bien que paradoxalement le <span>tabac</span> diminue le risque de PE, il majore le risque de <span>HRP</span> et <span>RCIU</span></td></tr>\n          <tr><td><strong>Contrôle pondéral</strong></td><td><span>Réduction</span> de l’IMC avant la conception si <span>obésité</span></td></tr>\n          <tr><td><strong>Bilan thrombophilie</strong></td><td>Si <span>prééclampsie</span> précoce / sévère : recherche SAPL, déficit en protéine S, protéine C, antithrombine, mutation Leiden, prothrombine</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span>Surveillance</span> rapprochée de la <span>grossesse</span> suivante</h4>\n      <ul>\n        <li><strong>Consultations rapprochées</strong> dès le 1ᵉʳ trimestre</li>\n        <li><strong><span>Bandelette urinaire</span> + TA</strong> à chaque consultation</li>\n        <li><strong><span>Échographie</span> + <span>doppler</span> utérin à <span>22-24 SA</span></strong> — recherche d’<strong>incisure protodiastolique</strong> ou index de pulsatilité élevé (signes prédictifs de PE)</li>\n        <li><strong><span>Suivi</span> conjoint</strong> obstétricien + médecin référent de la pathologie sous-jacente (cardio, néphro, internal med)</li>\n        <li><strong>Maternité de niveau adapté</strong> au risque</li>\n      </ul>\n\n      <h4>Mesures NON recommandées</h4>\n      <ul>\n        <li><strong>Repos au lit</strong> ❌ — pas d’efficacité préventive prouvée, majore le risque <span>MTEV</span></li>\n        <li><strong>Régime hyposodé</strong> ❌ — pas d’efficacité, peut aggraver l’hypovolémie</li>\n        <li><strong>Vitamines C/E</strong> ❌ — pas d’efficacité (essais négatifs)</li>\n        <li><strong><span>HBPM</span> systématique</strong> ❌ — uniquement si thrombophilie diagnostiquée</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 224 — <span>HTA</span> · 326 — Anti-thrombotiques · 344 — HTA gravidique et <span class=\"nc-orange_bg\">prééclampsie</span></em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":0},{"id":"24-17","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les complications à long terme de l’HTAg","contenu":"<div class=\"notion-course\"><p>L’<span>HTA</span> gravidique et la <span><span class=\"nc-orange_bg\">prééclampsie</span></span> ne sont pas des « événements isolés » de la <span>grossesse</span> : elles constituent un <strong>marqueur de risque cardiovasculaire à long terme</strong> pour la femme, justifiant un <strong><span>suivi</span> médical au long cours</strong>.</p>\n\n      <h4>Risques cardiovasculaires à long terme</h4>\n      <table>\n        <thead><tr><th>Risque</th><th>Magnitude</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>HTA</span> chronique</strong></td><td>RR <span>× 2-4</span> <span>vs</span> population générale ; ~ <span>20-30 %</span> des HTAg/PE développent une <span>HTA</span> chronique dans les <span>10-15 ans</span></td></tr>\n          <tr><td><strong>Maladie coronarienne / <span>IDM</span></strong></td><td>RR <span>× 2</span> à long terme (jusqu’à × 8 si PE précoce sévère)</td></tr>\n          <tr><td><strong><span>AVC</span></strong></td><td>RR <span>× 1,5-2</span></td></tr>\n          <tr><td><strong><span>Insuffisance rénale chronique</span></strong></td><td>Risque accru, notamment en cas de PE sévère ou récidivante</td></tr>\n          <tr><td><strong><span>Diabète de type 2</span></strong></td><td>Risque modérément augmenté (<span>terrain</span> métabolique partagé)</td></tr>\n          <tr><td><strong><span>Mortalité</span> cardiovasculaire</strong></td><td>RR <span>× 2</span> globalement</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Mécanismes proposés</h4>\n      <ul>\n        <li><strong>Marqueur d’un <span>terrain</span> prédisposant</strong> (insulinorésistance, dysfonction endothéliale, terrain <span>inflammatoire</span>)</li>\n        <li><strong>Effet propre</strong> de l’<span>HTA</span>/PE sur l’endothélium et la fonction rénale</li>\n        <li><strong>Persistance de <span>facteurs de risque</span></strong> partagés (<span>surpoids</span>, <span>sédentarité</span>)</li>\n      </ul>\n\n      <h4>Conséquences à très long terme — Spécifiques</h4>\n      <ul>\n        <li><strong>Risque accru de <span>prééclampsie</span></strong> dans les grossesses ultérieures (cf. obj-15)</li>\n        <li><strong><span>Insuffisance rénale chronique</span> :</strong> <span>dépistage</span> par <span>créatininémie</span> + <span>protéinurie</span> tous les <span>1-2 ans</span>, surtout si PE sévère ou avec atteinte rénale</li>\n        <li><strong>Hématome sous-capsulaire hépatique</strong> en post-<span>HELLP</span> : généralement résolutif mais risque de séquelles hépatiques</li>\n        <li><strong>Persistance de séquelles neurologiques</strong> exceptionnelles après <span>éclampsie</span> ou <span>PRES</span> syndrome</li>\n      </ul>\n\n      <h4><span>Suivi</span> médical au long cours — recommandations</h4>\n      <div class=\"callout callout-info\">\n        <strong>Plan de <span>suivi</span> systématique après HTAg / <span>prééclampsie</span>.</strong>\n        <ul>\n          <li><strong>Consultation à <span>6-8 semaines</span> :</strong> bilan tensionnel + <span>bilan rénal</span> complet</li>\n          <li><strong>Consultation à <span>3-6 mois</span> :</strong> confirmation de la normalisation</li>\n          <li><strong><span>Suivi</span> annuel</strong> par le médecin traitant : TA, IMC, <span>glycémie à jeun</span>, <span>bilan lipidique</span>, créat + <span>protéinurie</span></li>\n          <li><strong>Évaluation cardiologique</strong> rapprochée si signes ou ATCD de PE sévère</li>\n        </ul>\n        <strong>Éducation à long terme.</strong>\n        <ul>\n          <li>Activité physique régulière</li>\n          <li>Alimentation équilibrée (régime méditerranéen)</li>\n          <li>Maintien d’un poids normal</li>\n          <li><span>Sevrage</span> tabagique impératif</li>\n          <li><span>Dépistage</span> des autres <span>FRCV</span> (<span>diabète</span>, <span>dyslipidémie</span>)</li>\n        </ul>\n      </div>\n\n      <h4>Complications fœtales à long terme</h4>\n      <ul>\n        <li><strong>Enfants nés prématurément</strong> (PE → AP induit) : risque accru de troubles du neurodéveloppement, séquelles respiratoires</li>\n        <li><strong>Enfants avec <span>RCIU</span></strong> : risque augmenté à l’âge adulte d’<span>HTA</span>, <span>diabète</span>, maladie cardiovasculaire (hypothèse de Barker)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span>HTA</span> · 253 — <span>Obésité</span> · 222 — FDR cardiovasculaire · 254 — Nutrition</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":0},{"id":"24-18","rang":"A","rubrique":"Epidémiologie","titre":"Définir et diagnostiquer une menace d’accouchement prématuré","contenu":"<div class=\"notion-course\"><p>La <span>menace d’accouchement prématuré (MAP)</span> = <span class=\"nc-yellow_bg\">association de </span><strong><span class=\"nc-yellow_bg\">modifications cervicales</span> + <span class=\"nc-yellow_bg\">contractions utérines</span> <span class=\"nc-yellow_bg nc-bold\">régulières</span> et <span class=\"nc-yellow_bg nc-bold\">douloureuses</span></strong>, survenant entre <strong><span>22 SA</span> et <span>36 SA</span> + <span>6 jours</span></strong>. C’est l’une des principales causes d’<span>hospitalisation</span> pendant la <span>grossesse</span>.</p>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewbox=\"0 0 620 276\" role=\"img\" aria-label=\"Frise des seuils gestationnels de la menace d&#x27;accouchement prématuré. L&#x27;axe va de 22 à 41 semaines d&#x27;aménorrhée. Trois fenêtres d&#x27;intervention se lisent au-dessus de l&#x27;axe : le sulfate de magnésium en neuroprotection fœtale et l&#x27;orientation en maternité de type 3 s&#x27;appliquent avant 32 SA ; la corticothérapie prénatale par bétaméthasone ou dexaméthasone s&#x27;applique avant 34 SA ; la tocolyse de 48 heures, le temps d&#x27;organiser le transfert in utero et de laisser agir les corticoïdes, s&#x27;arrête à 34 SA. Sous l&#x27;axe, les zones de prématurité : prématurité extrême de 22 à 27 SA plus 6 jours environ 10 pour cent, grande prématurité de 28 à 31 SA plus 6 jours environ 10 pour cent, prématurité moyenne ou tardive de 32 à 36 SA plus 6 jours environ 80 pour cent, puis à terme à partir de 37 SA. Le seuil de viabilité est à 22 SA ou 500 grammes ou 25 centimètres, et un terme inférieur à 28 SA est un facteur de gravité de la MAP.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"700\">Seuils gestationnels — MAP &amp; prématurité</text>\n          <text class=\"tx-muted\" x=\"310\" y=\"34\" text-anchor=\"middle\" font-size=\"10.5\">MAP : 22 → 36 SA + 6 j · prématurité = naissance &lt; 37 SA</text>\n\n          <rect class=\"fb-purple\" x=\"45\" y=\"44\" width=\"284\" height=\"22\" rx=\"5\"></rect>\n          <text class=\"tx-purple\" x=\"187\" y=\"59\" text-anchor=\"middle\" font-size=\"10\">Sulfate de Mg (neuroprotection) · Maternité type III — &lt; 32 SA</text>\n          <rect class=\"fb-teal\" x=\"45\" y=\"72\" width=\"341\" height=\"22\" rx=\"5\"></rect>\n          <text class=\"tx-teal\" x=\"215\" y=\"87\" text-anchor=\"middle\" font-size=\"10\"><span>Corticothérapie</span> prénatale (béta-/<span>dexaméthasone</span>) — &lt; 34 SA</text>\n          <rect class=\"fb-ok\" x=\"45\" y=\"100\" width=\"341\" height=\"22\" rx=\"5\"></rect>\n          <text class=\"tx-ok\" x=\"215\" y=\"115\" text-anchor=\"middle\" font-size=\"10\">Tocolyse <span>48 h</span> (transfert + délai cortico) — stop 34 SA</text>\n\n          <line class=\"ln-dash\" x1=\"329\" y1=\"44\" x2=\"329\" y2=\"150\" stroke-width=\"1.5\"></line>\n          <line class=\"ln-dash\" x1=\"386\" y1=\"72\" x2=\"386\" y2=\"150\" stroke-width=\"1.5\"></line>\n\n          <line class=\"ln\" x1=\"45\" y1=\"150\" x2=\"585\" y2=\"150\" stroke-width=\"2\"></line>\n          <g stroke-width=\"2\">\n            <line class=\"ln\" x1=\"45\" y1=\"145\" x2=\"45\" y2=\"155\"></line>\n            <line class=\"ln\" x1=\"215\" y1=\"145\" x2=\"215\" y2=\"155\"></line>\n            <line class=\"ln\" x1=\"329\" y1=\"145\" x2=\"329\" y2=\"155\"></line>\n            <line class=\"ln\" x1=\"386\" y1=\"145\" x2=\"386\" y2=\"155\"></line>\n            <line class=\"ln\" x1=\"471\" y1=\"145\" x2=\"471\" y2=\"155\"></line>\n            <line class=\"ln\" x1=\"585\" y1=\"145\" x2=\"585\" y2=\"155\"></line>\n          </g>\n          <text class=\"tx-title\" x=\"45\" y=\"169\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">22</text>\n          <text class=\"tx-title\" x=\"215\" y=\"169\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">28</text>\n          <text class=\"tx-title\" x=\"329\" y=\"169\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">32</text>\n          <text class=\"tx-title\" x=\"386\" y=\"169\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">34</text>\n          <text class=\"tx-title\" x=\"471\" y=\"169\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">37</text>\n          <text class=\"tx-title\" x=\"585\" y=\"169\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">41 SA</text>\n\n          <rect class=\"fb-red\" x=\"45\" y=\"184\" width=\"170\" height=\"42\" rx=\"5\"></rect>\n          <text class=\"tx-red\" x=\"130\" y=\"201\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">Extrême</text>\n          <text class=\"tx-red\" x=\"130\" y=\"216\" text-anchor=\"middle\" font-size=\"9.5\">22–27 SA+6 · ~<span>10 %</span></text>\n          <rect class=\"fb-amber\" x=\"215\" y=\"184\" width=\"114\" height=\"42\" rx=\"5\"></rect>\n          <text class=\"tx-amber\" x=\"272\" y=\"201\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">Grande</text>\n          <text class=\"tx-amber\" x=\"272\" y=\"216\" text-anchor=\"middle\" font-size=\"9.5\">28–31+6 · ~<span>10 %</span></text>\n          <rect class=\"fb-blue\" x=\"329\" y=\"184\" width=\"142\" height=\"42\" rx=\"5\"></rect>\n          <text class=\"tx-blue\" x=\"400\" y=\"201\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">Moyenne / tardive</text>\n          <text class=\"tx-blue\" x=\"400\" y=\"216\" text-anchor=\"middle\" font-size=\"9.5\">32–36+6 · ~<span>80 %</span></text>\n          <rect class=\"fb-ok\" x=\"471\" y=\"184\" width=\"114\" height=\"42\" rx=\"5\"></rect>\n          <text class=\"tx-ok\" x=\"528\" y=\"201\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">À terme</text>\n          <text class=\"tx-ok\" x=\"528\" y=\"216\" text-anchor=\"middle\" font-size=\"9.5\"><span>≥ 37</span> SA</text>\n\n          <text class=\"tx-muted\" x=\"45\" y=\"248\" text-anchor=\"start\" font-size=\"10\">◗ 22 SA = seuil de viabilité (ou <span>≥ 500 g</span> / <span>≥ 25 cm</span>)</text>\n          <text class=\"tx-muted\" x=\"45\" y=\"264\" text-anchor=\"start\" font-size=\"10\">◗ &lt; 28 SA = facteur de gravité de la MAP</text>\n        </svg>\n        <figcaption>Les seuils d’intervention se lisent par leur <strong>borne droite</strong> : sulfate de Mg &amp; maternité III avant 32 SA, <span>corticothérapie</span> avant 34 SA, tocolyse jusqu’à 34 SA. Synthèse statique du chapitre MAP (obj-17/20/21).</figcaption>\n      </figure>\n\n      <h4>Définitions à connaître</h4>\n      <table>\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Prématurité</strong></td><td>Naissance avant <span>37 SA</span></td></tr>\n          <tr><td><strong><span>Menace</span> d’accouchement prématuré (MAP)</strong></td><td>Modifications cervicales + CU <span class=\"nc-yellow_bg nc-bold\">régulières</span> et <span class=\"nc-yellow_bg nc-bold\">douloureuses</span>, entre <span>22 SA</span> et <span>36 SA + 6 j</span></td></tr>\n          <tr><td><strong>Prématurité <span class=\"nc-red\">moyenne</span> / <span class=\"nc-red\">tardive</span></strong></td><td><span>32-36 SA + 6 j</span> — ≈ <span>80 %</span> des AP</td></tr>\n          <tr><td><strong>Grande prématurité</strong></td><td><span>28-31 SA + 6 j</span> — ≈ <span>10 %</span> des AP</td></tr>\n          <tr><td><strong>Très grande prématurité / prématurité <span class=\"nc-red\">extrême</span></strong></td><td><span>22-27 SA + 6 j</span> — ≈ <span>10 %</span> des AP</td></tr>\n          <tr><td><strong>Seuil de viabilité</strong></td><td>Terme <span><span class=\"nc-pink nc-bold\">≥ 22 SA</span></span> et/ou poids <span><span class=\"nc-pink nc-bold\">≥ 500 g</span></span> et/ou taille <span>≥ 25 cm</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Diagnostic de MAP — <span class=\"nc-red nc-bold\">3 critères</span> associés</h4>\n      <table>\n        <thead><tr><th>Critère</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Terme</strong></td><td>Entre <span>22 SA et 37 SA</span></td></tr>\n          <tr><td><strong><span class=\"nc-yellow_bg\">Contractions utérines</span></strong></td><td>\n            <strong><span class=\"nc-yellow_bg nc-bold\">Régulières</span>, <span class=\"nc-yellow_bg nc-bold\">douloureuses</span></strong> (à distinguer des CU <span class=\"nc-green nc-bold\">physiologiques</span> <span class=\"nc-green nc-bold\">irrégulières</span> et <span class=\"nc-green nc-bold\">indolores</span>)<br>\n            <strong>Cardiotocographie externe</strong> : objective et précise la nature des CU\n          </td></tr>\n          <tr><td><strong>Modifications cervicales</strong></td><td>\n            <strong>Au <span>TV</span> :</strong> <span class=\"nc-red nc-bold\">ramollissement</span>, <span class=\"nc-red nc-bold\">effacement</span>, <span class=\"nc-red nc-bold\">dilatation du col</span><br>\n            <strong><span><span class=\"nc-blue_bg\">Échographie</span></span><span class=\"nc-blue_bg\"> du col</span> :</strong> <span>longueur cervicale <span class=\"nc-pink nc-bold\">&lt; 25 mm</span></span> = <span class=\"nc-red nc-bold\">col raccourci</span> → MAP\n          </td></tr>\n        </tbody>\n      </table>\n\n      <h4>Marqueur <span>biologique</span> d’aide au diagnostic</h4>\n      <div class=\"callout callout-info\">\n        <strong>Fibronectine fœtale</strong> (non systématique).\n        <ul>\n          <li><strong>Intérêt :</strong> prédit le risque d’accouchement avant <span>34 SA</span> (<span>VPN à 90 %</span>, spécificité supérieure au <span>TV</span>)</li>\n          <li><strong>Rationnel :</strong> fibronectine <span class=\"nc-red nc-bold\">normalement </span><strong><span class=\"nc-red nc-bold\">absente des sécrétions vaginales au-delà de </span><span><span class=\"nc-red nc-bold\">24 SA</span></span></strong></li>\n          <li>Sa positivité oriente vers un risque accru, sa négativité quasi-élimine la MAP</li>\n          <li><em>Réservée aux cas douteux ; ne se prescrit pas si MAP évidente</em></li>\n        </ul>\n      </div>\n\n      <h4>Col normal <span>vs</span> col raccourci</h4>\n      <ul>\n        <li><strong>Col normal de la nullipare :</strong> long, postérieur, fermé, consistance dure (« comme un nez »)</li>\n        <li>En cas de CU actives → le col se <strong>raccourcit, se centre, se ramollit, s’ouvre</strong></li>\n        <li><strong>Mesure échographique du col :</strong> coupe sagittale, visualisation orifices interne et externe, mesure de la longueur en dehors et pendant la contraction → <strong>seuil <span>25 mm</span></strong></li>\n      </ul>\n\n      <h4><span>Diagnostic différentiel</span></h4>\n      <ul>\n        <li><strong><span class=\"nc-yellow_bg\">Contractions utérines</span> <span class=\"nc-green nc-bold\">physiologiques</span></strong> (Braxton-Hicks) : <span class=\"nc-green nc-bold\">irrégulières</span>, <span class=\"nc-green nc-bold\">indolores</span>, ne modifient pas le col</li>\n        <li><strong>Faux travail :</strong> CU douloureuses mais sans modification cervicale</li>\n        <li><strong>Travail réel</strong> avant <span>37 SA</span> : CU + col en travail (<span class=\"nc-red nc-bold\">effacement</span> et dilatation avancés) → <span>urgence</span></li>\n        <li><strong><span><span class=\"nc-red_bg\">Rupture</span></span><span class=\"nc-red_bg\"> prématurée des membranes</span></strong> : peut être associée à MAP, ou isolée</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Attention.</strong> Ce n’est pas parce qu’une femme a des <span class=\"nc-yellow_bg\">contractions utérines</span> qu’elle a forcément une MAP. <strong>Au moindre doute → <span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> du col</span></strong> pour mesurer objectivement la longueur cervicale.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 27 — Prévention des risques fœtaux · 359 — <span>Détresse</span> respiratoire néonatale</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":3},{"id":"24-19","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les facteurs de risque de la menace d’accouchement prématuré","contenu":"<div class=\"notion-course\"><p>Le bilan étiologique d’une MAP est <strong>indispensable</strong> mais reste <strong>négatif dans <span>40 %</span></strong> des cas (MAP idiopathique). La connaissance des FR oriente la PEC et la prévention.</p>\n\n      <h4><span>Facteurs de risque</span> maternels (terrain)</h4>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Facteurs</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Âge</strong></td><td><span>&lt; 18 ans</span> ou <span>&gt; 35 ans</span></td></tr>\n          <tr><td><strong>Toxiques</strong></td><td><span><span class=\"nc-red nc-bold\">Tabac</span></span>, <span><span class=\"nc-red nc-bold\">alcool</span></span>, <span><span class=\"nc-red nc-bold\">drogues</span></span> (cocaïne ++)</td></tr>\n          <tr><td><strong>Socio-éducatif</strong></td><td><span class=\"nc-green_bg\">Célibat</span>, <span class=\"nc-green_bg\">très bas niveau socio-économique</span>, mauvais <span>suivi</span> prénatal</td></tr>\n          <tr><td><strong>Travail / vie quotidienne</strong></td><td><span class=\"nc-green_bg\">Travail pénible</span>, <span class=\"nc-green_bg\">trajets longs quotidiens</span>, <span class=\"nc-green_bg\">nombreux enfants à charge</span></td></tr>\n          <tr><td><strong>Psychologique</strong></td><td><span><span class=\"nc-orange_bg\">Dépression</span></span>, <span class=\"nc-orange_bg\">anxiété</span>, <span class=\"nc-orange_bg\">stress maternel</span></td></tr>\n          <tr><td><strong>Traumatisme</strong></td><td><span class=\"nc-orange_bg\">Traumatisme abdominal</span></td></tr>\n          <tr><td><strong>Métrorragies</strong></td><td>Au 2ᵉ/3ᵉ trimestre, même hors <span><span class=\"nc-orange_bg\">placenta praevia</span></span> (favorisent <span>RPM</span>)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Causes infectieuses</h4>\n      <ul>\n        <li><strong>Toute infection</strong> peut entraîner des CU via la <span>fièvre</span></li>\n        <li><strong><span class=\"nc-purple_bg\">Infections urinaires</span></strong>, <span class=\"nc-purple_bg\">bactériuries asymptomatiques</span> (colonisation urinaire gravidique)</li>\n        <li><strong><span class=\"nc-purple_bg\">Infections vaginales</span></strong> (<span><span class=\"nc-red_bg\">vaginose bactérienne</span></span>)</li>\n        <li><strong><span>Chorioamniotite</span></strong> (« infection de l’œuf ») et/ou <span>RPM</span></li>\n      </ul>\n\n      <h4>Facteurs cervicaux</h4>\n      <ul>\n        <li><strong><span class=\"nc-pink_bg\">ATCD de conisation</span></strong> (<span>chirurgie</span> visant à réséquer une partie du col)</li>\n        <li><strong><span class=\"nc-yellow_bg\">Col court</span></strong> mesuré en <span>échographie</span> (mesure non systématique)</li>\n        <li><strong>Béance cervico-isthmique</strong> (incompétence cervicale) — cause principale de <span>FCT</span> et AP très précoce / <span>RPM</span> avant <span>32 SA</span></li>\n      </ul>\n\n      <h4>Facteurs corps utérin</h4>\n      <ul>\n        <li><strong><span class=\"nc-red nc-bold\">Diminution</span> de la taille utérine</strong> avant <span>grossesse</span> : fibromes, <span class=\"nc-orange_bg\">utérus polymyomateux</span>, utérus diéthylstilbœstrol (exposition in utero à Distilbène®), malformations utérines (utérus hypoplasiques, unicornes, bicornes, cloisonnés)</li>\n        <li><strong>Augmentation de la distension utérine</strong> pendant la <span>grossesse</span> : <span class=\"nc-orange_bg\">hydramnios</span>, macrosomie fœtale, <strong><span class=\"nc-green_bg\">grossesses multiples</span></strong> (taux de prématurité <span>45 %</span>, RR × 7)</li>\n      </ul>\n\n      <h4>Autres FR liés à la <span>grossesse</span></h4>\n      <ul>\n        <li><strong>FIV</strong></li>\n        <li><strong>Intervalle court</strong> entre <span <span=\"\">&gt;2</span> grossesses (<span class=\"nc-pink nc-bold\">&lt; </span><span><span class=\"nc-pink nc-bold\">18 mois</span></span>)</li>\n        <li><strong><span><span class=\"nc-orange_bg\">Placenta praevia</span></span></strong> (RR × 6-7 d’AP), décollement placentaire</li>\n        <li><strong>Anémie maternelle</strong></li>\n        <li><strong><span>Diabète gestationnel</span></strong> (par macrosomie, hydramnios, infection intercurrente)</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Facteurs de gravité de la MAP (rang C — à connaître).</strong>\n        <ul>\n          <li>Âge gestationnel <span>&lt; 28 SA</span></li>\n          <li>Importance des modifications cervicales</li>\n          <li>Patiente accueillie dans une <span class=\"nc-green_bg\">maternité</span> de <strong>niveau non adapté</strong></li>\n          <li><strong><span>Grossesse</span> multiple</strong></li>\n          <li><strong><span><span class=\"nc-red_bg\">Rupture</span></span><span class=\"nc-red_bg\"> des membranes</span> ou <span><span class=\"nc-purple_bg\">chorioamniotite</span></span></strong> associée</li>\n          <li><strong>Métrorragies</strong> associées</li>\n          <li>Col fortement modifié, très menaçant, poche des eaux visible au spéculum</li>\n          <li>Tentative inefficace de tocolyse</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 255 — <span>Diabète gestationnel</span> · 75 — Addiction <span>tabac</span> · 76 — Addictions <span><span class=\"nc-red nc-bold\">alcool</span></span> · 78 — Addictions <span class=\"nc-red nc-bold\">drogues</span></em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":0},{"id":"24-20","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le bilan d’une menace d’accouchement prématuré","contenu":"<div class=\"notion-course\"><p>Le bilan d’une MAP comporte 4 volets : <strong>clinique</strong>, <strong>fœtal</strong>, <strong>étiologique</strong>, <strong>pré-thérapeutique</strong>.</p>\n\n      <h4>1. Bilan clinique</h4>\n      <ul>\n        <li><strong>Constantes habituelles</strong> : PA, FC, température, <span>BU</span></li>\n        <li><strong><span class=\"nc-yellow_bg\">Examen au spéculum</span></strong> : recherche d’un <strong>écoulement liquidien</strong> (<span>RPM</span> ?), métrorragies, leucorrhées</li>\n        <li><strong>Toucher vaginal</strong> : évaluation du col (<span class=\"nc-red nc-bold\">ramollissement</span>, <span class=\"nc-red nc-bold\">effacement</span>, dilatation)</li>\n        <li><strong>Mesure de la hauteur utérine :</strong>\n          <ul>\n            <li><strong>Augmentée</strong> → oriente vers une <strong>macrosomie fœtale</strong> ou un <strong><span class=\"nc-red nc-bold\">hydramnios</span></strong></li>\n            <li><strong>Diminuée</strong> → peut faire suspecter une <strong><span><span class=\"nc-red nc-bold\">rupture</span></span><span class=\"nc-red nc-bold\"> spontanée des membranes</span></strong></li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>2. Bilan fœtal</h4>\n      <ul>\n        <li><strong>Enregistrement du RCF</strong> par cardiotocographie externe</li>\n        <li><strong><span><span class=\"nc-blue_bg\">Échographie</span></span><span class=\"nc-blue_bg\"> obstétricale</span> :</strong> mouvements actifs fœtaux, estimation du poids fœtal, quantité de liquide amniotique, présentation, position du placenta</li>\n        <li><strong><span><span class=\"nc-blue_bg\">Échographie</span></span><span class=\"nc-blue_bg\"> du col</span></strong> par voie endovaginale : mesure de la longueur cervicale, recherche d’une protrusion des membranes</li>\n      </ul>\n\n      <h4>3. Bilan étiologique</h4>\n      <table>\n        <thead><tr><th>Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><span>NFS, CRP</span></td><td>Recherche d’un <strong><span>syndrome inflammatoire</span></strong> (<span>chorioamniotite</span>, infection)</td></tr>\n          <tr><td><span>ECBU</span></td><td>Recherche d’une <strong><span>infection urinaire</span></strong> ou bactériurie</td></tr>\n          <tr><td><span>Prélèvement cervico-vaginal</span></td><td>Recherche de <strong><span>vaginose</span></strong>, <strong><span>streptocoque B</span></strong>, autres germes</td></tr>\n          <tr><td><strong>Test biochimique de <span>RPM</span></strong></td><td>Si doute sur <span>RPM</span> : <span><span class=\"nc-pink nc-bold\">IGFBP-1</span> (Actim-PROM)</span>, <span><span class=\"nc-pink nc-bold\">PAMG-1</span> (AmniSure)</span>, ou DAO — recherche de composants du liquide amniotique dans le vagin</td></tr>\n        </tbody>\n      </table>\n\n      <h4>4. <span>Bilan pré-thérapeutique</span></h4>\n      <ul>\n        <li><strong><span><span class=\"nc-pink nc-bold\">Glycémie</span></span></strong> — risque de <strong>déséquilibre d’un <span>diabète gestationnel</span> non diagnostiqué</strong> sous <span>corticothérapie</span></li>\n        <li><strong><span><span class=\"nc-blue_bg\">ECG</span></span></strong> avant <span>32 SA</span>, en prévision d’un traitement par <strong><span class=\"nc-pink_bg\">sulfate de magnésium</span></strong> (jugé inutile selon Masson, à pondérer)</li>\n        <li><span><span class=\"nc-blue_bg\">Groupe, Rhésus, RAI</span></span> en cas d’<span class=\"nc-orange nc-bold\">accouchement imminent</span></li>\n      </ul>\n\n      <h4><span class=\"nc-pink_bg\">Fibronectine fœtale</span> — quand la prescrire ?</h4>\n      <div class=\"callout callout-info\">\n        <strong>Indication.</strong> Cas <strong>douteux</strong> (CU ressenties par la patiente, col légèrement modifié) où le diagnostic de MAP n’est ni évident ni écarté.\n        <ul>\n          <li><strong>Si négative</strong> → quasi-élimine une MAP (VPN ≈ <span>90 %</span>) → <span>surveillance</span> allégée</li>\n          <li><strong>Si positive</strong> → renforce le diagnostic → <span>hospitalisation</span>, traitement</li>\n          <li><strong>Non indiquée si MAP évidente</strong> (col déjà très modifié) ❌</li>\n        </ul>\n      </div>\n\n      <h4>Conclusion du bilan</h4>\n      <ul>\n        <li>Confirmer / écarter le diagnostic de MAP</li>\n        <li>Identifier une étiologie traitable (infection, <span>RPM</span>)</li>\n        <li>Évaluer la sévérité (terme, modifications cervicales, RCF, <span>signes de gravité</span> associés)</li>\n        <li>Orienter vers une <strong><span class=\"nc-green_bg\">maternité</span> de niveau adapté</strong> (cf. obj-20)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 161 — Infection urinaire · 255 — <span>Diabète gestationnel</span></em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":1},{"id":"24-21","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge d’une menace d’accouchement prématuré","contenu":"<div class=\"notion-course\"><ul><li>Confirmer le risque d’accouchement prématuré : terme, contractions et modifications cervicales, membranes, infection et état fœtal. Une simple activité utérine ne suffit pas à diagnostiquer une MAP.</li><li>Organiser l’accueil dans une <span class=\"nc-green_bg\">maternité</span> adaptée aux besoins néonataux : transfert in utero si réalisable sans danger, en concertation avec le réseau. La stabilité maternelle et fœtale prime ; une naissance imminente ou une urgence ne doit pas être retardée pour un transfert.</li><li>Si naissance probable avant 34 SA : corticothérapie anténatale, habituellement bétaméthasone 12 mg IM puis 12 mg 24 heures plus tard. Elle ne justifie pas de différer une extraction urgente.</li><li><span class=\"nc-yellow_bg\">Tocolyse</span> courte, généralement jusqu’à 48 heures, pour permettre corticothérapie et transfert chez une femme éligible. <span class=\"nc-pink nc-bold\">Nifédipine</span> ou <span class=\"nc-pink nc-bold\">atosiban</span> selon le contexte ; pas de traitement d’entretien systématique.</li><li>Pas de tocolyse en cas d’infection intra-amniotique suspectée, hémorragie menaçante, souffrance fœtale ou indication maternelle à faire naître. Les antibiotiques ne sont pas systématiques à membranes intactes ; traiter une infection documentée et appliquer le protocole de <span class=\"nc-red_bg\">rupture prématurée des membranes</span>.</li><li>Si naissance imminente avant 32 SA : discuter <span class=\"nc-pink_bg\">sulfate de magnésium</span> pour neuroprotection selon protocole, distinct de son emploi dans la prééclampsie. Information parentale et avis pédiatrique.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":2},{"id":"24-22","rang":"A","rubrique":"Prise en charge","titre":"Connaître les mesures de prévention de la menace d’accouchement prématuré","contenu":"<div class=\"notion-course\"><p>La prévention de la MAP repose sur (1) <strong>prévention pré-conceptionnelle</strong>, (2) <strong>prise en charge des FR</strong> pendant la <span>grossesse</span>, (3) <strong>traitements spécifiques</strong> chez les patientes à haut risque.</p>\n\n      <h4>Prévention pré-conceptionnelle</h4>\n      <ul>\n        <li><strong><span>Sevrage</span> tabagique</strong> — <span class=\"nc-yellow_bg\">seul FR modifiable d’AP dont le sevrage est associé à une diminution de la prématurité</span></li>\n        <li><strong>Limitation des <span class=\"nc-green_bg\">grossesses multiples</span></strong> en cas de PMA (transfert d’1 seul embryon)</li>\n        <li><strong>Information</strong> sur les risques des <span class=\"nc-red_bg\">grossesses rapprochées</span> (intervalle <span class=\"nc-pink\">&lt; </span><span><span class=\"nc-pink\">18 mois</span></span>)</li>\n        <li><strong>Bilan préconceptionnel</strong> en cas d’ATCD d’AP ou de <span>FCT</span></li>\n      </ul>\n\n      <h4>Prise en charge des FR pendant la <span>grossesse</span></h4>\n      <table>\n        <thead><tr><th>FR</th><th>Mesure</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span><span class=\"nc-yellow_bg\">Tabac</span></span></strong></td><td><strong><span>Sevrage</span></strong> (seul FR modifiable avec efficacité prouvée)</td></tr>\n          <tr><td><strong><span>Alcool</span>, toxiques</strong></td><td>Arrêt + accompagnement addictologique</td></tr>\n          <tr><td><strong><span class=\"nc-green_bg\">Travail pénible</span></strong></td><td>Arrêt de travail (station debout &gt; <span>6 h</span>, longs trajets)</td></tr>\n          <tr><td><strong><span class=\"nc-orange_bg\">Stress maternel</span></strong></td><td>PEC psychologique possible, soutien</td></tr>\n          <tr><td><strong>Alimentation</strong></td><td>Équilibrée</td></tr>\n          <tr><td><strong>Pathologies préexistantes</strong></td><td>Optimisation (<span>diabète</span>, <span>asthme</span>, <span>HTA</span>...)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Malformations utérines</h4>\n      <ul>\n        <li><strong>Rechercher</strong> les malformations utérines (<span>échographie</span> pelvienne 3D, <span>hystérographie</span>)</li>\n        <li><strong>Corriger</strong> avant la <span>grossesse</span> si possible : <span><span class=\"nc-pink nc-bold\">résection de cloison utérine</span></span></li>\n      </ul>\n\n      <h4><span class=\"nc-red_bg\">Vaginose </span><span><span class=\"nc-red_bg\">bactérienne</span></span></h4>\n      <div class=\"callout callout-info\">\n        <strong>Si ATCD d’AP dans un contexte d’infection materno-fœtale <span>bactérienne</span> :</strong>\n        <ol>\n          <li><strong><span>Dépistage</span></strong> de la <span><span class=\"nc-red_bg\">vaginose bactérienne</span></span> par <strong>prélèvement vaginal au 1ᵉʳ trimestre</strong></li>\n          <li><strong>Si positive → traitement systématique :</strong> <span><span class=\"nc-pink nc-bold\">métronidazole</span></span> ou <span><span class=\"nc-pink nc-bold\">clindamycine</span></span> pendant <span><span class=\"nc-pink_bg\">7 jours</span></span></li>\n        </ol>\n      </div>\n\n      <h4>Béance cervicale — <span class=\"nc-pink nc-bold\">Cerclage</span> <span>vs</span> <span class=\"nc-pink_bg\">progestérone</span></h4>\n      <table>\n        <thead><tr><th>Contexte</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>≥ 3</span> ATCD d’AP ou <span>FCT</span></strong></td><td><strong>Cerclage formellement indiqué</strong> (placé à la fin du 1ᵉʳ trimestre)</td></tr>\n          <tr><td><strong>1 ou 2 ATCD d’AP ou <span>FCT</span></strong></td><td><span>Surveillance</span> écho col entre 16 et <span>22 SA</span> + <strong><span class=\"nc-pink nc-bold\">cerclage</span> si col <span class=\"nc-pink\">&lt; </span><span><span class=\"nc-pink\">25 mm</span></span></strong> ; <span class=\"nc-pink nc-bold\">progestérone micronisée vaginale</span> possible</td></tr>\n          <tr><td><strong>Pas d’ATCD</strong></td><td><span>Échographie</span> entre <span class=\"nc-pink\">16 et </span><span><span class=\"nc-pink\">24 SA</span></span> ; si <strong>col <span class=\"nc-pink\">&lt; </span><span><span class=\"nc-pink\">20 mm</span></span> → <span class=\"nc-pink nc-bold\">progestérone micronisée vaginale</span></strong> formellement indiquée</td></tr>\n          <tr><td><strong>Cerclage préventif systématique</strong></td><td><span>Non recommandé</span> sur seul <span class=\"nc-pink_bg\">ATCD de conisation</span>, <span class=\"nc-orange_bg\">malformation utérine</span>, <span>grossesse</span> gémellaire ou ATCD isolé d’AP</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Principe du cerclage</h4>\n      <ul>\n        <li><strong>Définition :</strong> mise en place d’un « nœud » (suture) autour du col pour empêcher mécaniquement son ouverture</li>\n        <li><strong>Placement :</strong> fin du 1ᵉʳ trimestre</li>\n        <li><strong>Retrait :</strong> en fin de <span>grossesse</span> pour permettre l’accouchement</li>\n        <li><strong>Attention :</strong> le cerclage n’est <strong>pas un traitement de la MAP</strong> mais une mesure préventive chez patientes à risque</li>\n      </ul>\n\n      <h4>Mesures NON recommandées</h4>\n      <ul>\n        <li><strong><span>Hospitalisation</span> prolongée</strong> ❌ — ne réduit pas le risque d’AP, majore le risque <span><span class=\"nc-orange nc-bold\">MTEV</span></span></li>\n        <li><strong><span class=\"nc-green_bg\">Repos</span> au lit strict</strong> ❌ — pas d’efficacité, majore <span><span class=\"nc-orange nc-bold\">MTEV</span></span></li>\n        <li><strong>Recherche systématique de <span class=\"nc-pink_bg\">fibronectine fœtale</span></strong> ❌ — réservée aux cas de suspicion de MAP</li>\n        <li><strong>Mesure systématique du col</strong> en <span>échographie</span> chez patientes sans FR ❌</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Risque de récidive</strong> lors de la <span>grossesse</span> suivante est <strong>important</strong>, justifiant un bilan étiologique attentif, bien souvent négatif (<span>40 %</span> idiopathiques).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 75 — Addiction <span>tabac</span> · 161 — Infection urinaire · 36 — Contraception</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":0},{"id":"24-23","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes d’orientation diagnostique et de gravité en cas de fièvre au cours de la grossesse","contenu":"<div class=\"notion-course\"><p>La <span>fièvre</span> pendant la <span>grossesse</span> est une situation <strong>fréquente</strong> (<span>10-15 %</span> des grossesses). <strong>Définition :</strong> température maternelle <span>&gt; 38 °C</span>.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Dogme.</strong> Toute <span>fièvre</span> in utero est une infection <strong>jusqu’à preuve du contraire</strong> — et plus précisément une <span><span class=\"nc-red nc-bold\">listériose</span> jusqu’à preuve du contraire</span>.\n      </div>\n\n      <h4>Étiologies à connaître par fréquence</h4>\n      <table>\n        <thead><tr><th>Étiologie</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Infections bénignes</strong> (<span><span class=\"nc-green_bg\">grippe</span></span>, <span class=\"nc-green_bg\">gastro-entérite</span>, <span class=\"nc-green_bg\">angine</span>)</td><td>Le plus souvent — PEC à domicile possible</td></tr>\n          <tr><td><strong><span><span class=\"nc-brown_bg\">Pyélonéphrite</span></span><span class=\"nc-brown_bg\"> aiguë gravidique</span></strong> ⭐</td><td><strong>Étiologie la plus fréquente</strong> — <span>fièvre</span> + douleur lombaire + brûlures mictionnelles</td></tr>\n          <tr><td><strong><span>Listériose</span></strong></td><td>Grave — passage <span class=\"nc-red nc-bold\">transplacentaire</span>, risque de mort fœtale, prématurité, séquelles néonatales</td></tr>\n          <tr><td><strong><span><span class=\"nc-orange nc-bold\">Chorioamniotite</span></span></strong></td><td>Grave — <span>fièvre</span> + CU + <span><span class=\"nc-red_bg nc-bold\">tachycardie</span></span><span class=\"nc-red_bg nc-bold\"> fœtale</span> + <span class=\"nc-yellow_bg\">leucorrhées suspectes</span></td></tr>\n          <tr><td><strong>Infections materno-fœtales</strong></td><td><span><span class=\"nc-purple_bg\">Rubéole</span></span>, <span><span class=\"nc-purple_bg\">toxoplasmose</span></span>, <span><span class=\"nc-purple_bg\">herpès</span></span>, <span><span class=\"nc-purple_bg\">syphilis</span></span>, <span><span class=\"nc-purple_bg\">CMV</span></span>, <span><span class=\"nc-purple_bg\">VIH</span></span>, hépatites virales (donnent rarement de la <span>fièvre</span>)</td></tr>\n          <tr><td><strong>Causes digestives</strong></td><td><span><span class=\"nc-orange nc-bold\">Appendicite</span></span>, <span>cholécystite</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Signes d’orientation par contexte</h4>\n      <ul>\n        <li><strong>Signes urinaires</strong> (douleurs lombaires, brûlures mictionnelles, <span>BU</span> positive) → <strong><span>PNA</span> gravidique</strong> ++</li>\n        <li><strong>Signes obstétricaux</strong> (CU + écoulement liquide amniotique + <span class=\"nc-yellow_bg\">leucorrhées suspectes</span>) → <strong><span><span class=\"nc-orange nc-bold\">chorioamniotite</span></span> / <span>RPM</span></strong></li>\n        <li><strong>Syndrome grippal</strong> en période d’épidémie → infection bénigne probable</li>\n        <li><strong>Signes digestifs</strong> (douleur fosse iliaque droite, défense, signe de Murphy) → <span><span class=\"nc-orange nc-bold\">appendicite</span></span> / <span><span class=\"nc-orange nc-bold\">cholécystite</span></span></li>\n        <li><strong><span>Fièvre</span> isolée, <span class=\"nc-green_bg\">mal expliquée</span></strong>, hors contexte épidémique → <strong>évoquer <span><span class=\"nc-orange\">listériose</span></span></strong> ++</li>\n        <li><strong><span class=\"nc-red_bg\">Diminution des mouvements actifs</span> fœtaux + <span><span class=\"nc-red_bg nc-bold\">tachycardie</span></span><span class=\"nc-red_bg nc-bold\"> fœtale</span></strong> → souffrance fœtale → <strong><span><span class=\"nc-orange\">listériose</span></span> ? <span><span class=\"nc-orange nc-bold\">chorioamniotite</span></span> ?</strong></li>\n      </ul>\n\n      <h4><span>Signes de gravité</span> — Indications d’<span>hospitalisation</span></h4>\n      <div class=\"callout callout-danger\">\n        <strong>Indications d’<span>hospitalisation</span> systématique :</strong>\n        <ul>\n          <li><span>Signes évocateurs de <span class=\"nc-orange nc-bold\">PNA</span></span></li>\n          <li><span>Signes évocateurs de <span class=\"nc-orange nc-bold\">chorioamniotite</span></span></li>\n          <li><strong><span>Fièvre</span> en apparence bénigne mais <span class=\"nc-green_bg\">mal expliquée</span></strong> (isolée, syndrome grippal hors contexte épidémique...)</li>\n          <li><strong><span>Fièvre</span> + <span class=\"nc-red_bg\">signes d’hypoxie fœtale</span></strong> (<span class=\"nc-red nc-bold\">diminution</span> mouvements, <span><span class=\"nc-red_bg nc-bold\">tachycardie</span></span><span class=\"nc-red_bg nc-bold\"> fœtale</span>) → <span><span class=\"nc-orange\">listériose</span></span> ? <span><span class=\"nc-orange nc-bold\">chorioamniotite</span></span> ?</li>\n          <li><strong><span><span class=\"nc-orange nc-bold\">Appendicite</span></span>, <span><span class=\"nc-orange nc-bold\">cholécystite</span></span></strong> ou autre cause chirurgicale</li>\n          <li><strong><span>Hyperthermie</span> &gt; <span>38,5 °C</span></strong> sans cause identifiée</li>\n          <li><strong>Mauvaise tolérance maternelle</strong> (<span>frissons</span>, <span>AEG</span>, signes de <span>sepsis</span>)</li>\n        </ul>\n      </div>\n\n      <h4>Retentissement obstétrical à évaluer systématiquement</h4>\n      <ul>\n        <li><strong><span><span class=\"nc-red_bg\">Menace</span></span><span class=\"nc-red_bg\"> d’accouchement prématuré</span></strong> (la <span>fièvre</span> peut provoquer des CU = FR de MAP)</li>\n        <li><strong><span class=\"nc-red_bg\">Hypoxie fœtale</span></strong> (<span><span class=\"nc-red_bg nc-bold\">tachycardie</span></span><span class=\"nc-red_bg nc-bold\"> fœtale</span>, <span class=\"nc-red_bg\">diminution des mouvements actifs</span>)</li>\n        <li><strong><span><span class=\"nc-red_bg\">Rupture</span></span><span class=\"nc-red_bg\"> prématurée des membranes</span></strong></li>\n      </ul>\n\n      <h4>Situations autorisant une PEC à domicile</h4>\n      <ul>\n        <li><strong><span class=\"nc-green_bg\">Étiologie bénigne clairement identifiée</span></strong> : syndrome grippal typique en période d’épidémie, <span class=\"nc-green_bg\">gastro-entérite</span> bénigne...</li>\n        <li><strong>Absence de CU</strong></li>\n        <li><strong>Mouvements fœtaux et RCF normaux</strong></li>\n        <li><strong>Tolérance maternelle correcte</strong></li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — Infection urinaire · 157 — Septicémie/Bactériémie · 147 — <span>Fièvre</span> aiguë chez l’adulte · 162 — IST · 27 — Prévention des risques fœtaux (<span class=\"nc-purple_bg\">toxoplasmose</span>)</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":1},{"id":"24-24","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le bilan en cas de fièvre au cours de la grossesse","contenu":"<div class=\"notion-course\"><p>Le bilan d’une <span>fièvre</span> pendant la <span>grossesse</span> vise à <strong>identifier rapidement</strong> la cause (notamment <strong><span>listériose</span></strong> ++) et à <strong>évaluer le retentissement obstétrical</strong>.</p>\n\n      <h4>Interrogatoire</h4>\n      <ul>\n        <li><strong>ATCD prédisposants :</strong> infections urinaires à répétition, uropathies, maladies chroniques, immunodépression, prématurité, <span>tabac</span>...</li>\n        <li><strong>Traitements en cours</strong></li>\n        <li><strong>Contexte :</strong> épidémie, voyage, alimentation à risque (fromage au lait cru → <span>listeria</span>)</li>\n        <li><strong>Signes d’accompagnement :</strong>\n          <ul>\n            <li><strong>Généraux :</strong> <span>frissons</span>, ORL, pulmonaires, digestifs, syndrome grippal</li>\n            <li><strong>Urinaires :</strong> douleurs lombaires, brûlures mictionnelles</li>\n            <li><strong>Obstétricaux :</strong> CU, écoulement de liquide amniotique, leucorrhées, saignements</li>\n          </ul>\n        </li>\n        <li><strong>Mouvements actifs fœtaux</strong></li>\n        <li><strong>Résultats des <span>sérologies</span></strong> (<span><span class=\"nc-purple_bg\">toxoplasmose</span></span>, <span><span class=\"nc-purple_bg\">rubéole</span></span> — donnent rarement de la <span>fièvre</span>)</li>\n      </ul>\n\n      <h4>Examen clinique</h4>\n      <ul>\n        <li><strong>Constantes :</strong> température, pouls, PA</li>\n        <li><strong>Examen général :</strong> ORL, cardiorespiratoire, aires lymphonodales, état cutané, <span>syndrome méningé</span>, abdomen, fosses lombaires</li>\n        <li><strong>Examen urinaire :</strong> aspect des urines, <span>bandelette urinaire</span></li>\n        <li><strong>Examen obstétrical :</strong>\n          <ul>\n            <li><strong>Hauteur utérine</strong></li>\n            <li><strong>Bruits du cœur / RCF</strong></li>\n            <li><strong>Vulve :</strong> vésicules ou ulcérations herpétiques</li>\n            <li><strong>Au spéculum :</strong> <span>rupture</span> des membranes, leucorrhées, vésicules herpétiques</li>\n            <li><strong><span>TV</span> :</strong> modifications cervicales</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>Bilan paraclinique systématique</h4>\n      <table>\n        <thead><tr><th>Examen</th><th>Justification</th></tr></thead>\n        <tbody>\n          <tr><td><span>ECBU</span></td><td>Recherche d’une <strong><span>infection urinaire</span> / <span>PNA</span></strong></td></tr>\n          <tr><td><span><span class=\"nc-blue_bg\">NFS, CRP</span></span></td><td><span>Syndrome inflammatoire</span>. <strong>Attention :</strong> hyperleucocytose physiologique pendant la <span>grossesse</span></td></tr>\n          <tr><td><span>VS</span></td><td><strong>N’a aucune valeur</strong> pendant la <span>grossesse</span> — <strong>physiologiquement augmentée</strong></td></tr>\n          <tr><td><span><span class=\"nc-purple_bg\">Hémocultures</span></span></td><td>Si T° <strong>&gt; <span>38,5 °C</span></strong> — <strong>2 paires</strong>, recherche de <strong><span>Listeria</span></strong> ++</td></tr>\n          <tr><td><strong><span class=\"nc-brown_bg\">Électro-cardiotocographie</span></strong></td><td>Enregistrement du RCF + CU si âge gestationnel le permet (<strong>&gt; <span>25 SA</span></strong>)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Bilan en milieu hospitalier — Examens complémentaires</h4>\n      <table>\n        <thead><tr><th>Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-purple_bg\">ECBU</span> + <span class=\"nc-purple_bg\">Prélèvement vaginal</span> + <span class=\"nc-purple_bg\">Hémocultures</span> avec recherche de Listeria</span></td><td>Bilan microbiologique complet (la <strong><span>sérologie</span> <span>listeria</span> est sans valeur</strong>)</td></tr>\n          <tr><td><span><span class=\"nc-blue_bg\">NFS / CRP</span></span></td><td>Recherche d’hyperleucocytose (GB <span class=\"nc-red\">&gt; </span><span><span class=\"nc-red\">15 G/L</span></span>) ; pondérer avec l’hyperleucocytose physiologique</td></tr>\n          <tr><td><span>Sérologies selon contexte</span></td><td><span><span class=\"nc-purple_bg\">Rubéole</span></span>, <span><span class=\"nc-purple_bg\">toxoplasmose</span></span>, <span>hépatite</span>, <span><span class=\"nc-purple_bg\">CMV</span></span>, <span><span class=\"nc-purple_bg\">VIH</span></span>, <span>parvovirus B19</span></td></tr>\n          <tr><td><strong>RCF + CU</strong></td><td>Si âge gestationnel &gt; <span>25 SA</span></td></tr>\n          <tr><td><span><span class=\"nc-brown_bg\">Échographie obstétricale</span></span></td><td>Apprécier le bien-être fœtal + quantité de liquide amniotique</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Examens orientés selon contexte clinique</h4>\n      <ul>\n        <li><strong>Suspicion de <span>chorioamniotite</span></strong> : <span>NFS, CRP, <span class=\"nc-purple_bg\">prélèvement vaginal</span>, bactériologie du liquide amniotique, écouvillon</span></li>\n        <li><strong>Suspicion de <span>RPM</span></strong> : <span>IGFBP-1, PAMG-1, DAO, Amniocheck, PromTest®</span></li>\n        <li><strong>Suspicion d’<span>appendicite</span></strong> : <span>NFS</span>, <span>CRP</span>, <span>échographie abdominale</span> (± <span>IRM</span> en cas de doute, <span>TDM</span> dosimétrie limitée)</li>\n        <li><strong>Suspicion d’<span>hépatite</span></strong> : <span>ASAT</span>/<span>ALAT</span>, <span>PAL</span>, <span>bilirubine</span>, <span>sérologies</span> hépatiques (Ag HBs, Ac anti-HBs, Ac anti-HBc, VHA, <span>VHC</span>), test de la MNI</li>\n        <li><strong>Si <span>fièvre</span> à l’accouchement</strong> : prélèvements périphériques + <span class=\"nc-blue_bg\">aspiration du liquide gastrique chez le nouveau-né</span> + <strong><span class=\"nc-blue_bg\">mise en culture du placenta</span></strong></li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — Infection urinaire · 27 — Prévention des risques fœtaux (<span class=\"nc-purple_bg\">toxoplasmose</span>) · 173 — Zoonose · 147 — <span>Fièvre</span> aiguë adulte · 168 — Herpesvirus</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":0},{"id":"24-25","rang":"A","rubrique":"Prise en charge","titre":"Connaître la prise en charge d’une fièvre au cours de la grossesse","contenu":"<div class=\"notion-course\"><p>La PEC d’une <span>fièvre</span> pendant la <span>grossesse</span> repose sur (1) <strong><span>antibiothérapie</span> probabiliste anti-<span>Listeria</span> immédiate</strong> en cas d’<span>hospitalisation</span>, (2) <strong>traitement symptomatique</strong> (<span><span class=\"nc-pink nc-bold\">paracétamol</span></span>), (3) <strong><span>surveillance</span> maternelle et fœtale rapprochée</strong>, (4) <strong>traitement étiologique adapté</strong> aux résultats.</p>\n\n      <h4>PEC à domicile — situations autorisées</h4>\n      <div class=\"callout callout-info\">\n        <strong>Domicile autorisé seulement si :</strong>\n        <ul>\n          <li><strong><span class=\"nc-green_bg\">Étiologie bénigne clairement identifiée</span></strong> (syndrome grippal en épidémie, <span class=\"nc-green_bg\">gastro-entérite</span>)</li>\n          <li><strong>Absence de CU</strong></li>\n          <li><strong>Mouvements fœtaux normaux</strong></li>\n          <li><strong>RCF normal</strong> (si âge gestationnel adapté)</li>\n        </ul>\n        <strong>Mesures :</strong> <span>paracétamol</span>, traitement symptomatique adapté, bonne hydratation, <span>surveillance</span> rapprochée + consigne de reconsulter en <span>urgence</span> si aggravation, CU, baisse des mouvements fœtaux, persistance &gt; <span>48 h</span>.\n      </div>\n\n      <h4>PEC hospitalière — Sans attendre les résultats</h4>\n      <div class=\"callout callout-danger\">\n        <strong><span>Antibiothérapie</span> probabiliste anti-<span>Listeria</span> immédiate</strong> en cas d’<span>hospitalisation</span>, <strong>en dehors d’une orientation étiologique claire</strong> :\n        <ul>\n          <li><strong>1ʳᵉ intention :</strong> <span><span class=\"nc-pink_bg\">Amoxicilline</span> <span class=\"nc-pink nc-bold\">3 g/jour</span></span> per os ou IV pendant <strong><span><span class=\"nc-pink nc-bold\">10 jours</span></span></strong></li>\n          <li><strong>Si <span>allergie</span> :</strong> <span><span class=\"nc-pink_bg\">érythromycine</span></span></li>\n          <li><strong>Si signes de <span><span class=\"nc-orange nc-bold\">chorioamniotite</span></span></strong> : <span><span class=\"nc-pink nc-bold\">C3G</span> (céfotaxime / ceftriaxone) + <span class=\"nc-pink nc-bold\">Aminoside</span> (gentamicine)</span> en IV — <em><span>amoxicilline</span> selon KB</em></li>\n        </ul>\n        <strong>+ Antipyrétique :</strong> <span>paracétamol</span> <span>1 g</span> ×<span> 4/jour</span>. <strong>Pas d’<span>AINS</span> pendant la <span>grossesse</span></strong> ❌.<br>\n        <strong>+ Bonne hydratation</strong>.\n      </div>\n\n      <h4><span>Surveillance</span> étroite</h4>\n      <ul>\n        <li><strong>Maternelle :</strong> température, FC, PA, FR, état général, diurèse</li>\n        <li><strong>Obstétricale :</strong> CU (tocométrie), col utérin (<span>TV</span> répété ± écho), pertes vaginales</li>\n        <li><strong>Fœtale :</strong> RCF en continu ou enregistrements répétés, mouvements actifs perçus par la mère</li>\n        <li><strong><span>Biologique</span> :</strong> <span>NFS</span> + <span>CRP</span> de contrôle à <span>48 h</span> ± <span>hémocultures</span> de contrôle</li>\n      </ul>\n\n      <h4>PEC étiologique selon résultats</h4>\n      <table>\n        <thead><tr><th>Étiologie</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Listériose</span> confirmée</strong></td><td><span><span class=\"nc-pink_bg\">Amoxicilline</span> IV 6 g/jour</span> pendant <strong><span>3 semaines</span></strong> ± <span>gentamicine</span>. <strong>Déclaration obligatoire</strong>.</td></tr>\n          <tr><td><strong><span><span class=\"nc-brown_bg\">Pyélonéphrite</span></span><span class=\"nc-brown_bg\"> aiguë gravidique</span></strong></td><td><span>C3G (céfotaxime / ceftriaxone)</span> IV puis relais oral (amox-clav, FQ <span>contre-indiquées</span> sauf <span>E. coli</span> résistant) — durée totale <span>10-14 jours</span>. <strong><span>Hospitalisation</span> systématique</strong>.</td></tr>\n          <tr><td><strong><span><span class=\"nc-orange nc-bold\">Chorioamniotite</span></span></strong></td><td><span><span class=\"nc-pink nc-bold\">C3G</span> + <span class=\"nc-pink nc-bold\">Aminoside</span></span> IV + <strong>extraction fœtale en <span>urgence</span> par césarienne</strong> ++ ; <span>tocolyse CI</span> dans ce contexte ⚠️</td></tr>\n          <tr><td><strong>Infections virales</strong> (<span><span class=\"nc-green_bg\">grippe</span></span>, <span class=\"nc-green_bg\">gastro-entérite</span>)</td><td>Traitement symptomatique. <strong><span>Oseltamivir</span></strong> possible si <span><span class=\"nc-green_bg\">grippe</span></span> avérée et formes graves.</td></tr>\n          <tr><td><strong><span>Toxoplasmose</span> maternelle</strong> (séroconversion)</td><td><span>Spiramycine</span> jusqu’à <span>18 SA</span> puis <span>pyriméthamine</span>-<span>sulfadiazine</span> selon contamination fœtale</td></tr>\n          <tr><td><strong><span>Appendicite</span> / <span><span class=\"nc-orange nc-bold\">cholécystite</span></span></strong></td><td>Traitement chirurgical en <span>urgence</span> ± ATB</td></tr>\n        </tbody>\n      </table>\n\n      <h4>PEC néonatale en cas de <span>fièvre</span> à l’accouchement</h4>\n      <ul>\n        <li><strong>Prélèvements périphériques</strong> chez le nouveau-né</li>\n        <li><strong>Aspiration du liquide gastrique</strong></li>\n        <li><strong><span class=\"nc-blue_bg\">Mise en culture du placenta</span></strong></li>\n        <li><strong>ATB néonatale probabiliste</strong> selon contexte (anti-<span>Listeria</span> + anti-Strepto B)</li>\n        <li><strong><span>Surveillance</span> pédiatrique rapprochée</strong> (<span>sepsis</span> néonatal)</li>\n      </ul>\n\n      <h4>Cas particuliers — Conseils alimentaires anti-<span>Listeria</span></h4>\n      <div class=\"callout callout-warn\">\n        <strong><span>Prévention primaire</span> de la <span>listériose</span> pendant la <span>grossesse</span> :</strong>\n        <ul>\n          <li>Éviter <strong>fromages au lait cru</strong>, à pâte molle, croûtes</li>\n          <li>Éviter <strong>charcuteries</strong> artisanales, rillettes, pâtés, foie gras non stérilisé</li>\n          <li>Éviter <strong>poissons fumés, crustacés crus, sushis</strong></li>\n          <li>Bien <strong>cuire les viandes</strong> et lavages soigneux des fruits/légumes</li>\n          <li>Respecter la chaîne du froid, dates de péremption</li>\n        </ul>\n      </div>\n\n      <h4>Synthèse — Algorithme</h4>\n      <ol>\n        <li><strong><span>Fièvre</span> &gt; <span>38 °C</span> confirmée</strong> → interrogatoire + examen complet</li>\n        <li><strong>Étiologie bénigne identifiée + bonne tolérance</strong> → PEC à domicile, <span><span class=\"nc-pink nc-bold\">paracétamol</span></span>, <span>surveillance</span></li>\n        <li><strong>Sinon ou doute</strong> → <span>hospitalisation</span></li>\n        <li><strong>Bilan paraclinique</strong> (cf. obj-23) + <strong><span>amoxicilline</span> <span>3 g/j</span></strong> sans attendre</li>\n        <li><strong><span>Surveillance</span> maternelle + fœtale</strong> rapprochée</li>\n        <li><strong>Adaptation</strong> selon résultats microbiologiques</li>\n      </ol>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — Infection urinaire · 27 — Prévention des risques fœtaux (<span class=\"nc-purple_bg\">toxoplasmose</span>) · 173 — Zoonose (<span class=\"nc-red nc-bold\">listériose</span>) · 147 — <span>Fièvre</span> aiguë adulte · 166 — <span><span class=\"nc-green_bg\">Grippe</span></span></em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prématurité spontanée, 2016</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF–SFAR · Prééclampsie sévère, 2020/2022</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prééclampsie, RPC 2023</a></li><li><a href=\"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/\" target=\"_blank\" rel=\"noopener noreferrer\">RCOG · Placenta prævia, accreta et vasa prævia</a></li><li><a href=\"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022</a></li></ul></details>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://archives.uness.fr/sites/campus-unf3s-2014/maieutique/UE-obstetrique/rcf/site/html/cours.pdf","label":"UNESS / UNF3S — Cours RCF (maïeutique, PDF)"},{"href":"https://www.aly-abbara.com/livre_gyn_obs/termes/bien_etre_foetal/rythme_cardiaque_foetal_RCF.html","label":"Aly-Abbara — Rythme cardiaque fœtal (exemples)"},{"href":"https://cego-obgyn.fr/deuxieme-cycle/","label":"Collège CNGOF–CEGO · Référentiel, 6e édition 2024"},{"href":"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf","label":"CNGOF · Hémorragies du post-partum, 2014"},{"href":"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download","label":"OMS · Acide tranexamique et HPP, 2017"},{"href":"https://cngof.fr/app/uploads/2025/11/MAP202016_Prmaturit_spontane.pdf","label":"CNGOF · Prématurité spontanée, 2016"},{"href":"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie202022-severe20RFE.pdf","label":"CNGOF–SFAR · Prééclampsie sévère, 2020/2022"},{"href":"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf","label":"CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024"},{"href":"https://cngof.fr/app/uploads/2025/11/PrC3A920C3A9clampsie2020202320RPC.pdf","label":"CNGOF · Prééclampsie, RPC 2023"},{"href":"https://www.rcog.org.uk/for-the-public/browse-our-patient-information/placenta-praevia-placenta-accreta-and-vasa-praevia/","label":"RCOG · Placenta prævia, accreta et vasa prævia"},{"href":"https://www.perinatalite-occitanie.fr/sites/rpo/files/upload/AmeliorationDesPratiques/2022_ref_MTR_transferts.pdf","label":"Réseau de périnatalité Occitanie · Métrorragies et transferts, 2022"}],"cards":[{"i":"0c08555dde0e","n":24,"o":"24-1","u":"Diagnostic positif","t":"Connaître la prise en charge d’une hémorragie du premier trimestre","q":"Que retenir concernant la prise en charge d’une hémorragie du premier trimestre ?","a":"<div class=\"notion-course\"><p>Les hémorragies du 1er trimestre concernent <span>25 %</span> des grossesses ; <strong><span><span class=\"nc-red nc-bold\">50 %</span></span><span class=\"nc-red nc-bold\"> de ces femmes auront une </span><span><span class=\"nc-red nc-bold\">évolution</span></span><span class=\"nc-red nc-bold\"> défavorable</span></strong>. Trois diagnostics dominent : <span><span class=\"nc-green_bg\">GIU évolutive</span></span> avec <span><span class=\"nc-orange nc-bold\">hématome décidual</span></span>, <span>fausse couche spontanée</span>, <span><span class=\"nc-red_bg\">GEU</span></span>.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Dogme.</strong> Toute femme avec hémorragie du 1er trimestre = <span><span class=\"nc-red_bg\">GEU</span> jusqu’à preuve du contraire</span>.\n      </div>\n\n      \n\n      <h4>Étiologies du 1er trimestre</h4>\n      <table>\n        <thead><tr><th>Étiologie</th><th>Fréquence / particularités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span><span class=\"nc-green_bg\">GIU évolutive</span></span> + <span><span class=\"nc-orange_bg\">hématome décidual</span></span></strong></td><td><span>12 %</span> — saignement bénin, abdomen <span class=\"nc-green_bg nc-bold\">indolore</span>, écho conforme à l’âge gestationnel + <span>image liquidienne entre œuf et paroi</span></td></tr>\n          <tr><td><strong><span>Avortement spontané</span> (<span>fausse couche</span>)</strong></td><td><span>12 %</span> — <span class=\"nc-blue_bg\">métrorragies</span> rouges <span class=\"nc-red nc-bold\">abondantes</span> avec <span class=\"nc-red nc-bold\">caillots</span>/<span class=\"nc-red nc-bold\">débris</span>, douleurs « comme des règles »</td></tr>\n          <tr><td><strong><span>GEU</span></strong></td><td><span>1 %</span> — sang sépia, douleurs latéralisées, β-hCG &gt; 1500 + vacuité utérine</td></tr>\n          <tr><td><strong>Causes cervico-vaginales</strong></td><td>Au spéculum : <span><span class=\"nc-red nc-bold\">cancer du col</span></span>, <span class=\"nc-green nc-bold\">ectropion</span>, <span class=\"nc-orange_bg\">cervicite</span>, polype</td></tr>\n          <tr><td><strong>Rares</strong></td><td><span class=\"nc-orange nc-bold\">Lyse d’un jumeau</span> (gémellaire), <span><span class=\"nc-red nc-bold\">grossesse môlaire</span></span> (hCG &gt; 100 000, <span>« nid d’abeilles »</span> écho)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>CAT systématique devant métrorragies du 1er trimestre</h4>\n      <ol>\n        <li><strong>Examen au spéculum</strong> — différencier origine cervico-vaginale <span>vs</span> endo-utérine</li>\n        <li><span>β-<span class=\"nc-blue_bg nc-bold\">hCG</span> <span class=\"nc-blue_bg\">plasmatique</span></span> en cas de doute sur l’état de <span>grossesse</span> + <span><span class=\"nc-blue_bg\">groupe sanguin + Rhésus</span> + RAI</span> systématiques ⭐</li>\n        <li><span><span class=\"nc-blue_bg\">Échographie pelvienne</span> par voie endovaginale</span> + abdominale (recherche hémopéritoine)</li>\n        <li>Si <strong>Rh-</strong> et fœtus Rh+ ou inconnu : <span>Ig anti-D</span> dans les <span>72 h</span></li>\n      </ol>\n\n      <h4>Orientation clinique synthétique</h4>\n      <table>\n        <thead><tr><th></th><th><span>GIU évolutive</span></th><th><span>GEU</span></th><th><span>Avortement spontané</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Signes sympathiques</strong></td><td>Oui</td><td>Oui</td><td><span>Disparition</span> ⭐</td></tr>\n          <tr><td><strong>Douleurs</strong></td><td>Absentes ⭐</td><td>Latéralisées, sourdes</td><td><span class=\"nc-red nc-bold\">Médianes</span>, intermittentes</td></tr>\n          <tr><td><strong><span class=\"nc-blue_bg\">Métrorragies</span></strong></td><td>Faibles</td><td>Peu <span class=\"nc-red nc-bold\">abondantes</span>, noirâtres (sépia)</td><td><span class=\"nc-red nc-bold\">Abondantes</span>, rouges, avec <span class=\"nc-red nc-bold\">caillots</span>/<span class=\"nc-red nc-bold\">débris</span></td></tr>\n          <tr><td><strong><span>TV</span> col</strong></td><td>Fermé</td><td>Tonique, fermé</td><td><span class=\"nc-yellow_bg nc-bold\">Mou</span>, <span class=\"nc-yellow_bg nc-bold\">perméable au doigt</span></td></tr>\n          <tr><td><strong>Utérus</strong></td><td>Taille = terme</td><td>Plus petit qu’attendu ± <span>masse</span> latéro-utérine</td><td>Taille = terme</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span><span class=\"nc-blue_bg\">Échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span> — résultats normaux et interprétation</h4>\n      <ul>\n        <li><strong>Sac ovulaire intra-utérin</strong> (<span>image liquidienne entourée d’une couronne échogène trophoblastique</span>) : visible dès <span><span class=\"nc-pink nc-bold\">5 SA</span></span></li>\n        <li><strong>Embryon + <span class=\"nc-green nc-bold\">activité</span> cardiaque</strong> : entre <span>5,5 et 6 SA</span></li>\n        <li><strong>Sac intra-utérin conforme</strong> → <span><span class=\"nc-green nc-bold\">GIU évolutive</span></span></li>\n        <li><strong><span>Œuf clair, aplati, contour irrégulier, petit</span></strong> → <span><span class=\"nc-orange nc-bold\">avortement spontané</span></span></li>\n        <li><strong><span>Utérus vide</span></strong> avec β-hCG &gt; 1500 → <span>GEU</span> jusqu’à preuve du contraire ; <span>masse hétérogène floconneuse vésiculaire</span> → <span>môle</span></li>\n        <li><strong>Si doute</strong> : refaire écho <span>5-7 jours</span> après le 1er contrôle</li>\n      </ul>\n\n      <h4>Cinétique des β-hCG à <span>48 h</span></h4>\n      <ul>\n        <li><strong>Doublement</strong> → <span><span class=\"nc-orange nc-bold\">grossesse</span></span> évolutive (<span class=\"nc-green nc-bold\">GIU</span> le plus souvent, parfois <span><span class=\"nc-red nc-bold\">GEU</span></span>)</li>\n        <li><strong>Décroissance × 2</strong> → <span>fausse couche spontanée</span></li>\n        <li><strong>Stagnation ou élévation insuffisante</strong> → <span><span class=\"nc-red nc-bold\">GEU</span></span> plutôt</li>\n        <li><em>KB :</em> toute cinétique peut se voir en <span><span class=\"nc-red nc-bold\">GEU</span></span> — la cinétique oriente mais n’élimine jamais formellement</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span class=\"nc-red_bg\">GEU</span> · 43 — Hémorragie génitale chez la femme · 23 — <span><span class=\"nc-orange nc-bold\">Grossesse</span></span> normale · 27 — Prévention des risques fœtaux</em></p></div>"},{"i":"390a76e421bf","n":24,"o":"24-2","u":"Prise en charge","t":"Connaître la prise en charge une fausse couche du premier trimestre","q":"Que retenir concernant la prise en charge une fausse couche du premier trimestre ?","a":"<div class=\"notion-course\"><p>La <span><span class=\"nc-yellow_bg\">fausse couche spontanée</span> précoce (FCP)</span> = expulsion d’une <span class=\"nc-green nc-bold\">GIU</span> avant <span>14 SA</span>. Fréquence <span>10-15 %</span> des grossesses. Cause principale : <strong>anomalie chromosomique embryonnaire (<span>60 %</span>)</strong>.</p>\n\n      <h4>Terminologie clé</h4>\n      <table>\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Grossesse</span> de localisation indéterminée</strong></td><td>hCG positif mais écho ne visualisant aucune <span>grossesse</span></td></tr>\n          <tr><td><strong>GIU d’<span>évolution</span> incertaine</strong></td><td>Sac gestationnel &lt; <span>25 mm</span> sans embryon, ou embryon avec LCC &lt; <span>7 mm</span> sans <span class=\"nc-green nc-bold\">activité</span> cardiaque</td></tr>\n          <tr><td><strong><span>Grossesse</span> arrêtée précoce</strong></td><td>Arrêt <span class=\"nc-pink nc-bold\">&lt; </span><span><span class=\"nc-pink nc-bold\">14 SA</span></span> : stagnation du sac et/ou LCC, disparition de l’AC</td></tr>\n          <tr><td><strong><span>FCP</span> complète</strong></td><td>Vacuité utérine + absence de symptôme</td></tr>\n          <tr><td><strong><span>FCP</span> incomplète</strong></td><td>Persistance de matériel intra-utérin à l’écho</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span>Diagnostic positif</span></h4>\n      <ul>\n        <li><strong>Clinique :</strong> disparition récente des signes sympathiques + <span class=\"nc-blue_bg\">métrorragies</span> rouges <span class=\"nc-red nc-bold\">franches</span> avec <span class=\"nc-red nc-bold\">caillots</span>/<span class=\"nc-red nc-bold\">débris</span> + douleurs <span class=\"nc-red nc-bold\">médianes</span> <span class=\"nc-red nc-bold\">intermittentes</span> « comme des règles »</li>\n        <li><strong><span>TV</span> :</strong> col <span class=\"nc-yellow_bg nc-bold\">mou</span> <span class=\"nc-yellow_bg nc-bold\">perméable au doigt</span> (ouvert après expulsion), culs-de-sac libres, <span class=\"nc-green_bg\">mobilisation utérine indolore</span></li>\n        <li><strong>Écho :</strong> sac ovulaire reconnaissable mais anormal — embryon sans AC, ou œuf clair sans embryon, aplati, <span class=\"nc-red nc-bold\">à contours irréguliers</span></li>\n      </ul>\n\n      <h4>Stratégies thérapeutiques</h4>\n      <table>\n        <thead><tr><th>Option</th><th>Indications / modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Abstention surveillée</strong></td><td><span class=\"nc-green_bg\">Expulsion spontanée dans la majorité des cas</span> (avec majoration transitoire d’hémorragie et douleurs)</td></tr>\n          <tr><td><strong><span class=\"nc-pink_bg\">Traitement</span> médical</strong> — <span><span class=\"nc-pink nc-bold\">misoprostol</span></span> (prostaglandine)</td><td>Si <strong>œuf de petite taille</strong> et <strong><span class=\"nc-green nc-bold\">hémorragies peu importantes</span></strong>. À éviter si <span>FCP</span> avec fœtus déjà expulsé.</td></tr>\n          <tr><td><strong><span class=\"nc-pink_bg\">Traitement</span> <span class=\"nc-pink_bg\">chirurgical</span></strong></td><td><span>Hospitalisation</span> + bilan préop + consultation <span class=\"nc-green_bg\">anesthésie</span>. AG ou AL : <strong><span class=\"nc-pink nc-bold\">dilatation du col</span> + <span class=\"nc-pink_bg\">aspiration</span> à la canule</strong> + <strong>examen anatomopathologique du produit</strong>. <span class=\"nc-yellow_bg\">Sortie le</span> <span class=\"nc-yellow_bg\">jour même</span> <span class=\"nc-yellow_bg\">ou le</span> <span class=\"nc-yellow_bg\">lendemain</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <h4>CAT KB selon le tableau</h4>\n      <ul>\n        <li><strong><span>Grossesse</span> arrêtée</strong> (pas d’embryon visible, ou embryon sans AC, non expulsé) → expulsion par <span><span class=\"nc-pink nc-bold\">misoprostol</span></span> ou aspiration</li>\n        <li><strong><span>FCP</span> fœtus expulsé</strong> → abstention si expulsion complète, aspiration si débris trophoblastiques ou hémorragie ; <em>éviter <span><span class=\"nc-pink nc-bold\">misoprostol</span></span></em></li>\n      </ul>\n\n      <h4>Mesures associées systématiques</h4>\n      <ul>\n        <li><span>Groupe + Rhésus + RAI</span></li>\n        <li>Si <strong>Rh-</strong> et fœtus Rh+ ou inconnu : <span>Ig anti-D</span> dans les <span>72 h</span></li>\n        <li><strong>Soutien psychologique</strong> — banale pour le médecin, source de traumatisme pour la femme</li>\n        <li>Information : <strong><span class=\"nc-green_bg\">aucune conséquence sur l’avenir obstétrical</span></strong> ; <span class=\"nc-green nc-bold\">activité</span> <span class=\"nc-green nc-bold\">physique</span> et <span class=\"nc-green nc-bold\">voiture</span> <span>ne sont pas</span> des causes ❌</li>\n        <li><strong>Bilan étiologique</strong> seulement si <strong><span><span class=\"nc-orange_bg nc-bold\">≥ 3</span></span><span class=\"nc-orange_bg nc-bold\"> épisodes</span> consécutifs &lt; <span>14 SA</span></strong></li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Avortements spontanés à répétition (rang C).</strong> <span>≥ 3</span> FCS <span class=\"nc-pink nc-bold\">&lt; </span><span><span class=\"nc-pink nc-bold\">14 SA</span></span> consécutives. Bilan : <span>caryotype des 2 conjoints</span> (translocations équilibrées), <span>anticoagulant circulant + anti-cardiolipine + anti-β2GP1</span> (<span class=\"nc-orange nc-bold\">SAPL</span>), <span>écho 3D pelvienne</span> (malformation), <span>prélèvements bactério vaginaux/endocervicaux</span> (endométrite chronique), <span><span class=\"nc-blue_bg\">bilan hormonal + glycémie</span></span>. <span class=\"nc-pink_bg\">Traitement</span> préventif <span>aspirine faible dose + HBPM préventive</span> uniquement efficace si <span class=\"nc-orange nc-bold\">SAPL</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span class=\"nc-red_bg\">GEU</span> · 23 — <span><span class=\"nc-orange nc-bold\">Grossesse</span></span> normale · 43 — Hémorragie génitale chez la femme · 27 — Prévention des risques fœtaux</em></p></div>"},{"i":"936f703ea206","n":24,"o":"24-3","u":"Identifier une urgence","t":"Connaître la prise en charge d’une grossesse extra-utérine","q":"Que retenir concernant la prise en charge d’une grossesse extra-utérine ?","a":"<div class=\"notion-course\"><p>Cet objectif est <strong>traité intégralement dans l’item 25 — <span><span class=\"nc-orange nc-bold\">Grossesse</span></span> extra-utérine</strong>. Synthèse opérationnelle ici pour la PEC de l’item 24.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Dogme.</strong> Toute <span>femme en âge de procréer</span> avec douleur pelvienne et/ou <span class=\"nc-blue_bg\">métrorragies</span> = <strong><span><span class=\"nc-red_bg\">GEU</span></span> jusqu’à preuve du contraire</strong>. Triade systématique : <strong>examen clinique + écho endovaginale + abdominale + β-<span class=\"nc-blue_bg nc-bold\">hCG</span></strong>.\n      </div>\n\n      <h4>Tableau clinique typique</h4>\n      <ul>\n        <li><strong><span class=\"nc-blue_bg\">Métrorragies</span> :</strong> peu <span class=\"nc-red nc-bold\">abondantes</span>, foncées (<em>sépia</em>)</li>\n        <li><strong>Douleurs :</strong> latéralisées, sourdes avec accès plus intenses</li>\n        <li><strong><span>TV</span> :</strong> col tonique fermé, utérus plus petit qu’attendu, <span>masse</span> latéro-utérine, douleur au Douglas / <span class=\"nc-red nc-bold\">mobilisation utérine</span></li>\n        <li><strong>Formes évoluées :</strong> scapulalgies (irritation diaphragmatique), <span>malaise</span>, agitation</li>\n      </ul>\n\n      <h4><span>Signes de gravité</span> = <span>urgence</span> chirurgicale</h4>\n      <ul>\n        <li><span>Hypotension, tachycardie, malaise</span></li>\n        <li><span>Défense / contracture abdominale</span></li>\n        <li><span>Hémopéritoine</span> à l’écho (Douglas, espace de Morisson)</li>\n      </ul>\n\n      <h4>Stratégie thérapeutique</h4>\n      <table>\n        <thead><tr><th>Option</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Cœlioscopie</span></strong> (gold standard)</td><td>Patiente symptomatique, β-hCG &gt; 5000, <span>masse</span> &gt; <span>4 cm</span>, AC visible, instabilité</td></tr>\n          <tr><td><strong><span>Laparotomie</span></strong></td><td>Hémopéritoine massif + <span>choc</span>, CI à la <span>cœlioscopie</span></td></tr>\n          <tr><td><strong><span>Méthotrexate</span></strong> IM</td><td><span>GEU</span> paucisymptomatique, β-hCG &lt; 5000 (jusqu’à 10 000), pas d’AC, pas de <span>masse</span> &gt; <span>4 cm</span>. <span>Surveillance</span> hebdo β-hCG. Contraception <span>3 mois</span>.</td></tr>\n          <tr><td><strong>Abstention surveillée</strong></td><td>Asymptomatique + β-hCG &lt; 1000 + décroissance constante + observance</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Mesures associées</h4>\n      <ul>\n        <li><strong>Si Rh-</strong> : <span>Ig anti-D</span> dans les <span>72 h</span></li>\n        <li><strong><span>Dépistage</span> IST</strong> chez patiente + partenaire si séquelles d’IGH à la cœlio</li>\n        <li><strong>Récidive ≈ <span>20 %</span></strong> → écho précoce à <span>6 SA</span> pour <span>grossesse</span> suivante ⭐</li>\n        <li><strong><span>Sevrage</span> tabagique</strong> systématique</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Item lié principal : 25 — <span><span class=\"nc-orange nc-bold\">Grossesse</span></span> extra-utérine · 43 — Hémorragie génitale chez la femme · 162 — IST · 332 — États de <span>choc</span></em></p></div>"},{"i":"7ebc4f6fa281","n":24,"o":"24-4","u":"Diagnostic","t":"Connaître la prise en charge d’une hémorragie du deuxième ou du troisième trimestre","q":"Que retenir concernant la prise en charge d’une hémorragie du deuxième ou du troisième trimestre ?","a":"<div class=\"notion-course\"><ul><li><b>Hémorragie du deuxième ou troisième trimestre : évaluation obstétricale urgente.</b> Apprécier quantité, douleur, constantes et état fœtal ; réanimation, bilan et diagnostic peuvent être simultanés. L’importance du saignement extériorisé peut sous-estimer l’hémorragie, notamment dans l’HRP.</li><li><b>Ne pas effectuer de toucher vaginal digital avant exclusion d’un placenta prævia.</b> L’<span class=\"nc-blue_bg\">échographie</span>, y compris endovaginale, localise le placenta ; enregistrement du rythme fœtal selon terme. Bilan : NFS-<span class=\"nc-pink_bg\">plaquettes</span>, groupe/RAI, hémostase et <span class=\"nc-pink_bg\">fibrinogène</span> selon gravité ; anticiper les besoins transfusionnels. Anti-D si mère RhD négatif non immunisée et fœtus RhD positif ou inconnu, selon protocole du terme concerné.</li><li><b>Placenta prævia :</b> saignement souvent rouge et <span class=\"nc-green_bg nc-bold\">indolore</span>, <span class=\"nc-green_bg\">utérus</span> <span class=\"nc-green_bg nc-bold\">souple</span>. Préciser le recouvrement et la distance au col ; la notion de placenta bas inséré utilise généralement une distance inférieure à 20 mm, et non 50 mm. Un placenta antérieur bas sur cicatrice expose aussi au placenta accreta.</li><li><b>Placenta prævia stable :</b> surveillance et préparation de la naissance selon saignements, terme et conditions locales ; corticothérapie si naissance prématurée probable. Tocolyse seulement dans des situations sélectionnées, jamais pour retarder une naissance urgente. Pas d’alitement strict systématique prolongé.</li><li><b>Voie et terme de naissance :</b> un placenta <span class=\"nc-red nc-bold\">recouvrant</span> impose une césarienne ; hors recouvrement, décision selon distance au col, saignements et conditions obstétricales. Programmer avant le travail selon le protocole spécialisé ; ne pas retenir « après 39 SA » comme règle. Les repères varient entre recommandations (RCOG souvent 36–37 SA ; protocole régional français cité 38–38+6 SA dans certaines situations stables). Une hémorragie importante ou une anomalie fœtale impose une décision plus précoce.</li><li><b><span class=\"nc-orange nc-bold\">Hématome rétroplacentaire</span> :</b> douleur brutale, utérus contracturé, sang parfois <span class=\"nc-red nc-bold\">noirâtre</span>, troubles du rythme fœtal et coagulopathie possibles. L’<span class=\"nc-blue_bg\">échographie</span> peut être normale : elle n’exclut pas le diagnostic. Rechercher HTA/<span class=\"nc-orange_bg\">prééclampsie</span> et autres facteurs de risque.</li><li><b>HRP : avis obstétrical et réanimation immédiats.</b> <span class=\"nc-pink nc-bold\">Naissance rapide</span> si compromis maternel ou fœtal ; voie selon état maternel, vitalité fœtale et avancement du travail. En cas de <span class=\"nc-red\">mort fœtale</span>, voie basse souvent privilégiée si compatible avec la sécurité maternelle. Corriger la coagulopathie et surveiller après la naissance ; stratégie individualisée pour les formes stables.</li><li><b>Hémorragie de Benckiser :</b> rupture de vaisseaux fœtaux prævia, souvent à la rupture des membranes ; anomalie brutale du rythme alors que la mère peut rester stable. Urgence fœtale extrême nécessitant une naissance immédiate et une réanimation néonatale. Rechercher aussi rupture <span class=\"nc-pink_bg nc-bold\">utérine</span>, lésion cervicovaginale ou hématome marginal.</li><li><b>Après l’épisode :</b> surveillance clinique et biologique, traitement de l’anémie, information et prévention adaptée à la cause. Après pathologie vasculaire placentaire, discuter la prévention par aspirine d’une grossesse ultérieure selon CNGOF 2023.</li></ul></div>"},{"i":"b25bfc46d085","n":24,"o":"24-5","u":"Diagnostic positif","t":"Connaître la définition de l’hémorragie du post partum (HPP)","q":"Que retenir concernant la définition de l’hémorragie du post partum (HPP) ?","a":"<div class=\"notion-course\"><p>L’<span><span class=\"nc-orange_bg\">hémorragie du post-partum</span> (HPP)</span> est définie de manière <strong>quantitative</strong> à partir des pertes sanguines mesurées dans les <span>24 h</span> suivant l’accouchement.</p>\n\n      <h4>Définitions à connaître</h4>\n      <table>\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong>HPP</strong></td><td>Pertes sanguines <span>≥ 500 mL</span> dans les <strong><span>24 h</span> suivant l’accouchement</strong> (voie basse ou césarienne)</td></tr>\n          <tr><td><strong>HPP sévère</strong></td><td>Pertes <span>≥ 1000 mL</span> dans les <span>24 h</span></td></tr>\n          <tr><td><strong>Hémorragie de la délivrance</strong></td><td>HPP dans les <strong><span>2 h</span> post-accouchement par voie basse</strong> (période d’hémorragies immédiates les plus fréquentes)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Repères épidémiologiques</h4>\n      <ul>\n        <li><strong>Fréquence :</strong> <span>≈ 7 %</span> des accouchements (selon source de référence)</li>\n        <li><strong>1ʳᵉ cause de <span>mortalité</span> maternelle</strong> dans le monde et en France</li>\n        <li><strong>Cause principale = <span class=\"nc-red nc-bold\">atonie utérine</span></strong> (mécanisme le plus fréquent)</li>\n      </ul>\n\n      <h4>Mesure des pertes sanguines</h4>\n      <ul>\n        <li><strong>Sac de recueil sous-fessier gradué</strong> systématique à l’accouchement par voie basse — seule méthode fiable</li>\n        <li>L’estimation visuelle <strong>sous-estime</strong> systématiquement les pertes réelles ❌</li>\n        <li><strong>Évaluation horaire</strong> des pertes pendant les <span>2 h</span> post-accouchement (<span>surveillance</span> en salle de naissance)</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Mécanismes physiopathologiques.</strong> Les 4 « T » à retenir :\n        <ul>\n          <li><strong>Tonus</strong> — <span class=\"nc-red nc-bold\">atonie utérine</span> (cause n°1, ≈ <span>80 %</span>)</li>\n          <li><strong>Tissu</strong> — rétention placentaire (cotylédon, <span>placenta accreta</span>)</li>\n          <li><strong>Traumatisme</strong> — déchirure cervico-vaginale, <span>rupture utérine</span></li>\n          <li><strong>Thrombine</strong> — coagulopathie (<span>HRP</span>, <span>CIVD</span>, traitement <span>anticoagulant</span>)</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 329 — Transfusion sanguine · 332 — États de <span>choc</span> · 213 — Anémie</em></p></div>"},{"i":"bf8f47594f81","n":24,"o":"24-6","u":"Prise en charge","t":"Connaître les principes de prise en charge d’une HPP","q":"Que retenir concernant les principes de prise en charge d’une HPP ?","a":"<div class=\"notion-course\"><ul><li>Reconnaître l’hémorragie et sa dynamique : quantifier les pertes, suivre pouls, PA, conscience et diurèse. L’état clinique peut imposer le <span class=\"nc-pink_bg\">traitement</span> avant tout seuil volumique.</li><li>Alerter immédiatement obstétricien, anesthésiste et équipe ; chronométrer. Réanimation, voies veineuses, bilan NFS–plaquettes–coagulation–fibrinogène, groupage/RAI et préparation transfusionnelle en parallèle du contrôle de la cause.</li><li>Rechercher les 4 T : Tone (atonie), Tissue (rétention), Trauma (lésion), Thrombin (coagulopathie). Délivrance artificielle/révision si indiquées, examen et suture des lésions, massage utérin et oxytocine si atonie.</li><li>Acide tranexamique IV précoce dans les trois heures suivant la naissance : 1 g sur dix minutes, renouvelable une fois si le saignement persiste après trente minutes ou reprend dans les vingt-quatre heures, selon contre-indications/protocole.</li><li>Si atonie persistante : utérotonique de deuxième ligne, notamment sulprostone selon protocole, puis tamponnement intra-utérin si adapté. L’instabilité ou l’échec impose une escalade immédiate.</li><li>Embolisation si conditions hémodynamiques et disponibilité compatibles ; chirurgie d’hémostase si nécessaire, jusqu’à l’hystérectomie de sauvetage. Ne pas prolonger des étapes inefficaces ni retarder la chirurgie pour attendre une embolisation.</li></ul></div>"},{"i":"d998bb4588b9","n":24,"o":"24-7","u":"Prise en charge","t":"Connaître les modalités de prévention de l’HPP","q":"Que retenir concernant les modalités de prévention de l’HPP ?","a":"<div class=\"notion-course\"><p>La prévention de l’HPP repose sur <strong>3 piliers</strong> : identification des FR avant l’accouchement, <strong>délivrance dirigée systématique</strong>, <span>surveillance</span> rapprochée du post-partum immédiat.</p>\n\n      <h4>Identification des FR</h4>\n      <table>\n        <thead><tr><th>Catégorie</th><th><span>Facteurs de risque</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Antécédents</strong></td><td>ATCD d’HPP, <span class=\"nc-pink_bg\">ATCD de</span> <span class=\"nc-pink\">césarienne</span>, <span class=\"nc-green nc-bold\">multiparité</span> (<span>≥ 4</span>), grand âge maternel</td></tr>\n          <tr><td><strong>Distension utérine</strong></td><td><span>Grossesse</span> multiple, macrosomie, hydramnios</td></tr>\n          <tr><td><strong>Travail anormal</strong></td><td>Travail prolongé, déclenchement, dystocie, instrumentation, césarienne</td></tr>\n          <tr><td><strong>Placentaires</strong></td><td><span><span class=\"nc-red_bg\">Placenta praevia</span></span>, <span>placenta accreta</span>, <span>HRP</span>, rétention placentaire ancienne</td></tr>\n          <tr><td><strong>Coagulation</strong></td><td>Coagulopathie connue, traitement <span>anticoagulant</span>, <span>prééclampsie</span> sévère, <span>HELLP</span></td></tr>\n          <tr><td><strong>Anémie pré-accouchement</strong></td><td>Tolérance hémodynamique moindre</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Délivrance dirigée — pivot de la prévention</h4>\n      <div class=\"callout callout-info\">\n        <strong>Définition.</strong> Administration d’un <span>utérotonique</span> au moment du dégagement des épaules (voie basse) ou à l’extraction (césarienne).\n        <ul>\n          <li><strong>Molécule :</strong> <span>oxytocine 5-10 UI IV lente</span> (ou IM)</li>\n          <li><strong>Alternative :</strong> <span>carbétocine</span> (Pabal®) après césarienne</li>\n          <li><strong>Bénéfice :</strong> <span>réduction</span> du risque d’HPP de <span>≈ 60 %</span></li>\n          <li><strong>Recommandation :</strong> à proposer à <strong>toutes les patientes</strong>, indépendamment des FR</li>\n        </ul>\n      </div>\n\n      <h4>Mesures organisationnelles</h4>\n      <ul>\n        <li><strong>Sac de recueil sous-fessier gradué</strong> systématique à l’accouchement par voie basse</li>\n        <li><strong><span>Surveillance</span> des <span>2 h</span> post-partum</strong> en salle de naissance : globe utérin, pertes sanguines, constantes</li>\n        <li><strong>Protocole HPP</strong> écrit, affiché, connu de toutes les équipes</li>\n        <li><strong>Salle équipée</strong> en utérotoniques (oxytocine, sulprostone, <span>misoprostol</span>)</li>\n        <li><strong>Disponibilité immédiate</strong> de PSL (CGR, PFC) et accès rapide à l’embolisation / <span>chirurgie</span></li>\n      </ul>\n\n      <h4>Mesures spécifiques selon FR</h4>\n      <ul>\n        <li><strong>Anémie prénatale :</strong> correction par <span>fer oral / IV</span> en fin de <span>grossesse</span> (objectif Hb <span>≥ 11 g/dL</span> à l’accouchement)</li>\n        <li><strong><span>Placenta accreta</span> suspecté :</strong> orientation vers maternité avec plateau technique chirurgical complet</li>\n        <li><strong>ATCD d’HPP :</strong> <span>RCP</span> anténatale, choix d’une maternité adaptée, voie d’abord large</li>\n        <li><strong>Traitement <span>anticoagulant</span> :</strong> protocole de relais péri-accouchement</li>\n      </ul>\n\n      <h4>Information de la patiente</h4>\n      <ul>\n        <li>Explication du <strong>risque <span>hémorragique</span> du post-partum</strong> et des mesures de prévention</li>\n        <li><strong>Consentement éclairé</strong> aux gestes de sauvetage (embolisation, hystérectomie)</li>\n        <li>Anticipation des situations à risque (<span>RCP</span>, choix de la maternité)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 213 — Anémie · 326 — Anti-thrombotiques · 326 — <span>Antalgiques</span> (péridurale)</em></p></div>"},{"i":"934df91b25e0","n":24,"o":"24-8","u":"Définition","t":"Connaître la définition de l’hypertension artérielle (HTA) gravidique (HTAg)","q":"Que retenir concernant la définition de l’hypertension artérielle (HTA) gravidique (HTAg) ?","a":"<div class=\"notion-course\"><ul><li><b>HTA pendant la grossesse :</b> PAS ≥ 140 mmHg et/ou PAD ≥ 90 mmHg, confirmée par des mesures correctes. En cas de valeur sévère (PAS ≥ 160 ou PAD ≥ 110 mmHg), confirmer rapidement et traiter sans attendre quatre heures.</li><li><b>HTA chronique :</b> connue avant la grossesse ou découverte avant 20 SA ; la réévaluation après l’accouchement permet de confirmer sa persistance. <b>HTA gestationnelle :</b> apparue après 20 SA, sans protéinurie ni signe de complication au bilan initial ; elle peut évoluer vers une <span class=\"nc-orange_bg\">prééclampsie</span>.</li><li><b><span class=\"nc-orange_bg\">Prééclampsie</span>, définition CNGOF 2023 :</b> HTA après 20 SA associée à une protéinurie ≥ 0,3 g/24 h ou un rapport protéinurie/créatininurie ≥ 30 mg/mmol. <span class=\"nc-orange_bg\">Prééclampsie</span> surajoutée si elle survient sur une HTA chronique.</li><li><b>Urgence même sans protéinurie :</b> atteinte neurologique, HELLP, œdème pulmonaire ou autre défaillance nécessite une prise en charge immédiate. Certaines définitions internationales sont plus larges ; les distinguer de la définition CNGOF.</li><li><b>Éclampsie :</b> crise convulsive dans ce contexte, après recherche des diagnostics différentiels. <b>HELLP :</b> hémolyse, élévation des enzymes hépatiques et thrombopénie. Ces complications peuvent apparaître après la naissance.</li><li><b>Mesure :</b> repos, position adaptée, brassard de bonne taille et appareil validé pour la grossesse. Automesure ou MAPA en cas de doute, sans retarder la prise en charge de signes de gravité.</li></ul></div>"},{"i":"61239f179624","n":24,"o":"24-9","u":"Epidémiologie","t":"Connaître la fréquence de l’HTAg","q":"Que retenir concernant la fréquence de l’HTAg ?","a":"<div class=\"notion-course\"><p>L’<span>HTA</span> pendant la <span>grossesse</span> est <strong>fréquente</strong> et constitue l’une des principales causes de morbi-<span>mortalité</span> maternelle et fœtale dans les pays développés.</p>\n\n      <h4>Données épidémiologiques</h4>\n      <table>\n        <thead><tr><th>Entité</th><th>Fréquence</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Troubles hypertensifs de la <span>grossesse</span> (toutes formes)</strong></td><td><span>10-15 %</span> des grossesses</td></tr>\n          <tr><td><strong><span>HTA</span> gravidique (HTAg)</strong></td><td><span>5-10 %</span> des grossesses</td></tr>\n          <tr><td><strong><span>Prééclampsie</span></strong></td><td><span>2-3 %</span> des grossesses en France (<span>5-7 %</span> primipares, <span>1-2 %</span> multipares)</td></tr>\n          <tr><td><strong><span>Prééclampsie</span> sévère</strong></td><td><span>~ 1 %</span> des grossesses</td></tr>\n          <tr><td><strong><span>Éclampsie</span></strong></td><td><span>1/2 000 à 1/3 000</span> grossesses</td></tr>\n          <tr><td><strong><span>HELLP</span> syndrome</strong></td><td><span>~ 0,5 %</span> des grossesses, complique <span>10-20 %</span> des prééclampsies sévères</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span>Mortalité</span> maternelle</h4>\n      <ul>\n        <li>La <strong><span><span class=\"nc-orange_bg\">prééclampsie</span></span>/<span>éclampsie</span></strong> est la <strong>2ᵉ cause de <span>mortalité</span> maternelle</strong> en France (après l’HPP)</li>\n        <li><strong>1ʳᵉ cause de <span>mortalité</span> maternelle</strong> par cause directe dans les pays développés selon certaines séries</li>\n        <li><strong>~ 30 décès maternels / an</strong> en France attribuables aux troubles hypertensifs</li>\n      </ul>\n\n      <h4><span>Mortalité</span> et morbidité fœtales</h4>\n      <ul>\n        <li><strong>1ʳᵉ cause d’accouchement prématuré induit</strong> (~ <span>15 %</span> des AP &lt; <span>32 SA</span>)</li>\n        <li><strong>1ʳᵉ cause de <span>RCIU</span></strong> d’origine vasculaire</li>\n        <li>Risque de <strong>mort fœtale in utero</strong> par <span>HRP</span> ou insuffisance placentaire sévère</li>\n      </ul>\n\n      <h4><span>Facteurs de risque</span> épidémiologiques</h4>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Facteurs</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Terrain</span></strong></td><td>Primiparité, âge &gt;<span> 35 ans</span> (ou &lt; 18), <span>obésité</span>, origine afro-caribéenne</td></tr>\n          <tr><td><strong>Antécédents</strong></td><td>ATCD personnel de <span>prééclampsie</span> (RR × 7), ATCD familial de <span>prééclampsie</span> au 1ᵉʳ degré</td></tr>\n          <tr><td><strong>Pathologies associées</strong></td><td><span>HTA</span> chronique, <span>diabète</span> préexistant, néphropathie chronique, <span>lupus</span> / SAPL, thrombophilie</td></tr>\n          <tr><td><strong><span>Grossesse</span></strong></td><td><span>Grossesse</span> multiple, grossesse issue de don d’ovocyte, intervalle long entre grossesses</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span>HTA</span> · 344 — HTA gravidique et <span class=\"nc-orange_bg\">prééclampsie</span> · 255 — <span>Diabète gestationnel</span> · 22 — Maladies rares</em></p></div>"},{"i":"a96e8fef4769","n":24,"o":"24-10","u":"Examens complémentaires","t":"Savoir prescrire et interpréter les examens complémentaires en cas d’HTA gravidique","q":"Que retenir concernant prescrire et interpréter les examens complémentaires en cas d’HTA gravidique ?","a":"<div class=\"notion-course\"><ul><li><b>Trois objectifs :</b> distinguer HTA gestationnelle et prééclampsie, rechercher une atteinte maternelle et apprécier le retentissement fœtal. Interpréter les résultats avec le terme, les symptômes et leur évolution.</li><li><b>Protéinurie :</b> quantification des 24 h ou rapport protéinurie/créatininurie sur échantillon. Les seuils ≥ 0,3 g/24 h ou ≥ 30 mg/mmol s’interprètent avec une HTA apparue après 20 SA ; une protéinurie isolée ne suffit pas à définir la <span class=\"nc-orange_bg\">prééclampsie</span>.</li><li><b>Bilan maternel :</b> NFS-plaquettes, créatinine, transaminases ; LDH, haptoglobine, bilirubine et frottis si hémolyse suspectée. Hémostase/fibrinogène selon gravité, saignement ou thrombopénie. L’uricémie ne pose pas à elle seule le diagnostic et ne décide pas seule de la naissance.</li><li><b>HELLP :</b> arguments d’hémolyse, cytolyse hépatique et thrombopénie ; douleur épigastrique ou de l’hypochondre droit fait rechercher une complication hépatique. Une anomalie évolutive peut précéder un syndrome complet.</li><li><b>Fœtus :</b> échographie de croissance et liquide amniotique, Doppler et surveillance du rythme selon indication. Un poids estimé inférieur au 10e percentile définit un petit poids pour l’âge gestationnel ; la restriction de croissance nécessite le contexte et la dynamique, pas le percentile seul.</li><li><b>Examens orientés :</b> imagerie cérébrale si signe neurologique atypique/persistant, bilan cardiopulmonaire si dyspnée ou douleur thoracique. PlGF ou ratio sFlt-1/PlGF ne sont pas recommandés en routine par CNGOF 2023 dans le seul but de réduire la morbidité.</li><li><b>Pas de bilan systématique de thrombophilie héréditaire après <span class=\"nc-orange_bg\">prééclampsie</span> isolée.</b> La recherche d’un SAPL est discutée séparément selon les critères obstétricaux et le contexte. Adapter la répétition des examens à la gravité et à l’évolution.</li></ul></div>"},{"i":"5ac03ec06a2f","n":24,"o":"24-11","u":"Suivi et/ou pronostic","t":"Connaître les complications de l’HTAg","q":"Que retenir concernant les complications de l’HTAg ?","a":"<div class=\"notion-course\"><p>L’<span>HTA</span> gravidique expose à des <strong>complications maternelles</strong> (<span><span class=\"nc-orange_bg\">prééclampsie</span></span> et ses formes graves) et <strong>fœtales</strong> (<span>RCIU</span>, prématurité induite, <span>MFIU</span>).</p>\n\n      <h4>Complications maternelles</h4>\n      <table>\n        <thead><tr><th>Complication</th><th>Mécanisme / clinique</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Prééclampsie</span></strong></td><td>~ <span>20 %</span> des HTAg pures évoluent vers <span>prééclampsie</span> (<span>HTA</span> + <span>protéinurie</span>)</td></tr>\n          <tr><td><span>Éclampsie</span></td><td><span>Crise convulsive</span> tonico-clonique généralisée sur <span><span class=\"nc-orange_bg\">prééclampsie</span></span> — peut survenir <em>avant, pendant ou après</em> l’accouchement (jusqu’à <span>7 jours</span> post-partum)</td></tr>\n          <tr><td><span>HELLP syndrome</span></td><td>Hémolyse + cytolyse hépatique + thrombopénie ; risque <strong>d’hématome sous-capsulaire du foie</strong></td></tr>\n          <tr><td><span>Hématome rétroplacentaire (HRP)</span></td><td>Décollement prématuré → <span>CIVD</span> + souffrance fœtale ; <em>fréquemment associé à l’HTAg / <span><span class=\"nc-orange_bg\">prééclampsie</span></span></em></td></tr>\n          <tr><td><strong><span>Insuffisance rénale aiguë</span></strong></td><td><span>NTA</span>, voire <span>nécrose</span> corticale ; favorisée par hypovolémie + <span>CIVD</span></td></tr>\n          <tr><td><strong><span>Œdème aigu pulmonaire</span> (<span>OAP</span>)</strong></td><td>Surcharge + altération de la perméabilité capillaire</td></tr>\n          <tr><td><strong><span>AVC</span> <span>hémorragique</span></strong></td><td>Cause principale de <span>mortalité</span> maternelle dans la <span>prééclampsie</span> sévère</td></tr>\n          <tr><td><strong><span>PRES</span> syndrome</strong> (<span>œdème</span> cérébral postérieur réversible)</td><td><span>Céphalées</span> + troubles visuels + crises ; <span>IRM</span> caractéristique</td></tr>\n          <tr><td><strong><span>CIVD</span></strong></td><td>Surtout en cas de <span>HELLP</span>, <span>HRP</span> ou <span>hémorragie massive</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Complications fœtales</h4>\n      <table>\n        <thead><tr><th>Complication</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>RCIU</span> (retard de croissance intra-utérin)</strong></td><td>Insuffisance vasculaire utéroplacentaire ; surtout en cas de <span><span class=\"nc-orange_bg\">prééclampsie</span></span> précoce</td></tr>\n          <tr><td><strong>Prématurité induite</strong></td><td>Accouchement déclenché pour sauvetage maternel ou fœtal</td></tr>\n          <tr><td><strong>Souffrance fœtale aiguë</strong></td><td>Anomalies du RCF, oligoamnios, <span>doppler</span> ombilical pathologique</td></tr>\n          <tr><td><strong>Mort fœtale in utero (<span>MFIU</span>)</strong></td><td>Insuffisance placentaire sévère ou <span>HRP</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Complications du post-partum à connaître</h4>\n      <ul>\n        <li><strong><span>Éclampsie</span> du post-partum</strong> — possible jusqu’à <strong><span>7 jours</span> après l’accouchement</strong> ⚠️</li>\n        <li><strong>Persistance de l’<span>HTA</span></strong> au-delà de <span>6 semaines</span> → réévaluer en cardio (<span>HTA</span> chronique sous-jacente ?)</li>\n        <li><strong><span>Thrombose veineuse profonde</span> / EP</strong> — risque <span>MTEV</span> majoré</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong>Triade de l’<span>éclampsie</span> imminente.</strong>\n        <ul>\n          <li><span>Céphalées intenses</span> (en casque, frontales)</li>\n          <li><span>Troubles visuels</span> (phosphènes, flou visuel, scotomes)</li>\n          <li><span>Douleur épigastrique en barre</span> (signe de Chaussier — distension de la capsule de Glisson)</li>\n        </ul>\n        <strong>Hyperréflexie ostéo-tendineuse</strong> souvent associée.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span>HTA</span> · 344 — HTA gravidique et <span class=\"nc-orange_bg\">prééclampsie</span> · 332 — États de <span>choc</span> · 105 — Épilepsies · 213 — Anémie</em></p></div>"},{"i":"d911eca39394","n":24,"o":"24-12","u":"Suivi et/ou pronostic","t":"Connaître les éléments de sévérité","q":"Que retenir concernant les éléments de sévérité ?","a":"<div class=\"notion-course\"><p>L’identification des <strong><span>critères de</span> sévérité</strong> conditionne la <strong>conduite à tenir immédiate</strong> : <span>hospitalisation</span>, <span>surveillance</span> rapprochée, indication d’accouchement.</p>\n\n      <h4><span>Critères de</span> sévérité maternels — Cliniques</h4>\n      <div class=\"callout callout-danger\">\n        <strong><span>HTA</span> sévère.</strong>\n        <ul>\n          <li><span>PAS ≥ 160 mmHg</span> et/ou <span>PAD ≥ 110 mmHg</span></li>\n        </ul>\n        <strong>Signes fonctionnels d’<span>éclampsie</span> imminente.</strong>\n        <ul>\n          <li><span>Céphalées intenses, rebelles aux antalgiques</span></li>\n          <li><span>Troubles visuels :</span> phosphènes, flou, scotomes, amaurose</li>\n          <li><span>Douleur épigastrique en barre (signe de Chaussier)</span></li>\n          <li><span>Nausées / vomissements</span></li>\n          <li><span>Hyperréflexie ostéo-tendineuse</span></li>\n          <li><span>Crise convulsive</span> = <span>éclampsie</span> déclarée</li>\n        </ul>\n        <strong>Signes d’hypoperfusion / <span>défaillance</span>.</strong>\n        <ul>\n          <li><strong><span>Oligurie</span></strong> (&lt; <span>500 mL</span>/<span>24 h</span>)</li>\n          <li><strong><span>OAP</span></strong> (<span>dyspnée</span>, <span>crépitants</span>)</li>\n          <li><strong>Troubles de la conscience</strong></li>\n        </ul>\n      </div>\n\n      <h4><span>Critères de</span> sévérité — Biologiques</h4>\n      <table>\n        <thead><tr><th>Paramètre</th><th>Seuil de sévérité</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Protéinurie</span></strong></td><td>&gt; <span>3 g / 24 h</span> (<span>prééclampsie</span> sévère)</td></tr>\n          <tr><td><strong><span>Créatininémie</span></strong></td><td>&gt; <span>90 µmol/L</span> ou doublement de la créat de base</td></tr>\n          <tr><td><strong><span>Plaquettes</span></strong></td><td>&lt; <span>100 G/L</span> (<span>HELLP</span>)</td></tr>\n          <tr><td><strong>Transaminases (<span>ASAT</span>/<span>ALAT</span>)</strong></td><td>&gt; <span>2 × normale</span> (<span>HELLP</span>)</td></tr>\n          <tr><td><strong><span>LDH</span> + <span>bilirubine</span></strong></td><td>↑ + <span>haptoglobine</span> ↓ = hémolyse (<span>HELLP</span>)</td></tr>\n          <tr><td><strong>Uricémie</strong></td><td>Élevée et corrélée à la sévérité</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span>Critères de</span> sévérité — Fœtaux</h4>\n      <ul>\n        <li><strong><span>RCIU</span> sévère</strong> &lt; 3ᵉ percentile</li>\n        <li><strong>Oligoamnios</strong> sévère (index amniotique <span>≤ 5</span>)</li>\n        <li><strong><span>Doppler</span> ombilical pathologique</strong> : <span>diastole nulle ou reverse-flow</span></li>\n        <li><strong>Anomalies sévères du RCF</strong></li>\n        <li><strong>Mort fœtale in utero</strong></li>\n      </ul>\n\n      <h4>Critères selon le terme</h4>\n      <ul>\n        <li><strong><span>Prééclampsie</span> précoce &lt; <span>32-34 SA</span></strong> → forme habituellement plus sévère, <span>pronostic</span> moins bon</li>\n        <li><strong><span>Prééclampsie</span> tardive <span>≥ 34 SA</span></strong> → <span>pronostic</span> globalement meilleur</li>\n      </ul>\n\n      <h4>Conduite à tenir devant un <span>critère de</span> sévérité</h4>\n      <ol>\n        <li><strong><span>Hospitalisation</span> immédiate</strong> en maternité de niveau adapté (3 si &lt; <span>32 SA</span>)</li>\n        <li><strong>Bilan complet</strong> maternel + fœtal (cf. obj-9)</li>\n        <li><strong>Traitement antihypertenseur</strong> en <span>urgence</span> si <span>HTA</span> sévère (cf. obj-12)</li>\n        <li><strong>Sulfate de magnésium</strong> en prévention de l’<span>éclampsie</span> si signes neurologiques</li>\n        <li><strong><span>Corticothérapie</span> prénatale</strong> &lt; <span>34 SA</span> (préparation à l’accouchement éventuel)</li>\n        <li><strong>Discussion d’extraction fœtale</strong> selon terme et tolérance maternelle</li>\n      </ol>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span>HTA</span> · 344 — HTA gravidique et <span class=\"nc-orange_bg\">prééclampsie</span> · 332 — États de <span>choc</span> · 105 — Épilepsies · 359 — <span>Détresse</span> respiratoire aiguë</em></p></div>"},{"i":"6f552ef02904","n":24,"o":"24-13","u":"Prise en charge","t":"Savoir prescrire les mesures de repos et le traitement antihypertenseur chez une femme enceinte","q":"Que retenir concernant prescrire les mesures de repos et le traitement antihypertenseur chez une femme enceinte ?","a":"<div class=\"notion-course\"><p>La PEC de l’HTAg associe <strong>mesures non médicamenteuses</strong>, <strong>antihypertenseurs adaptés à la <span>grossesse</span></strong>, et <strong>traitement spécifique des formes sévères</strong> (sulfate de Mg, accouchement).</p>\n\n      <h4>Mesures non médicamenteuses</h4>\n      <table>\n        <thead><tr><th>Mesure</th><th>Recommandation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Repos relatif</strong></td><td><strong>Pas d’alitement strict</strong> ❌ (majore le risque de <span>MTEV</span>) — <strong>repos modulé</strong>, arrêt de travail si pénible</td></tr>\n          <tr><td><strong>Arrêt de travail</strong></td><td>Selon situation et terme</td></tr>\n          <tr><td><strong>Régime</strong></td><td><strong>Pas de régime hyposodé</strong> ❌ — peut aggraver l’hypovolémie maternelle</td></tr>\n          <tr><td><strong>Bas de contention</strong></td><td>Prévention de la <span>MTEV</span> en cas de repos</td></tr>\n          <tr><td><strong><span>Surveillance</span> domicile</strong></td><td>Auto-mesure tensionnelle, recherche signes d’alerte</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Antihypertenseurs autorisés pendant la <span>grossesse</span></h4>\n      <table>\n        <thead><tr><th>Classe</th><th>Molécules</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Antihypertenseurs centraux</strong></td><td><span>Alpha-méthyldopa</span> (Aldomet®)</td><td><strong>1ʳᵉ intention historique</strong>, recul d’utilisation pendant la <span>grossesse</span>, bonne tolérance fœtale</td></tr>\n          <tr><td><strong><span>Inhibiteurs calciques</span></strong></td><td><span>Nicardipine</span> (Loxen®), <span>Nifédipine</span></td><td><strong>1ʳᵉ intention</strong> orale et IV ; rapide d’action, utilisable en aigu</td></tr>\n          <tr><td><strong><span>Bêtabloquants</span></strong></td><td><span>Labétalol</span> (Trandate®, α + β-)</td><td><strong>1ʳᵉ intention</strong> particulièrement en aigu IV ; alternative orale</td></tr>\n          <tr><td><strong>Vasodilatateurs périphériques</strong></td><td><span>Clonidine</span></td><td>Réserve</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Antihypertenseurs CONTRE-INDIQUÉS pendant la <span>grossesse</span></h4>\n      <div class=\"callout callout-danger\">\n        <strong><span>Contre-indications</span> absolues — à connaître ⭐.</strong>\n        <ul>\n          <li><span>IEC</span> (énalapril, <span>ramipril</span>...) — <strong>fœtotoxicité</strong> : oligoamnios, <span>IRA</span> fœtale, malformations rénales</li>\n          <li><span>ARA II / sartans</span> (<span>losartan</span>, <span>valsartan</span>...) — <strong>même toxicité que les <span>IEC</span></strong></li>\n          <li><span>Inhibiteurs directs de la rénine</span> (aliskirène)</li>\n          <li><span>Diurétiques</span> (sauf indication spécifique : <span>OAP</span>, IC) — risque d’hypoperfusion utéroplacentaire</li>\n        </ul>\n      </div>\n\n      <h4>Objectifs tensionnels</h4>\n      <table>\n        <thead><tr><th>Situation</th><th>Objectif PA</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>HTA</span> non sévère</strong></td><td>PAS &lt; <span>150 mmHg</span> et PAD &lt; <span>100 mmHg</span> (objectif large, pas trop bas pour préserver la perfusion utéroplacentaire)</td></tr>\n          <tr><td><strong><span>HTA</span> sévère (PAS <span>≥ 160</span> ou PAD ≥ 110)</strong></td><td><span>Réduction</span> progressive vers PAS 140-150 / PAD 90-100 — <strong>pas de chute brutale</strong> ⚠️ (risque d’hypoperfusion fœtale)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Stratégie thérapeutique selon sévérité</h4>\n      <ul>\n        <li><strong>HTAg modérée :</strong> traitement oral (alpha-méthyldopa OU nicardipine OU <span>labétalol</span>), monothérapie en 1ʳᵉ intention</li>\n        <li><strong>HTAg sévère (<span>urgence</span>) :</strong> <span>hospitalisation</span> + <span>nicardipine IV à la seringue électrique</span> ou <span>labétalol IV</span></li>\n        <li><strong>Bithérapie</strong> si <span>HTA</span> non contrôlée par la monothérapie</li>\n      </ul>\n\n      <h4>Sulfate de magnésium — prévention de l’<span>éclampsie</span></h4>\n      <div class=\"callout callout-warn\">\n        <strong>Indications du sulfate de Mg ⭐.</strong>\n        <ul>\n          <li><strong><span>Prééclampsie</span> sévère</strong> avec signes neurologiques (<span>céphalées</span>, phosphènes, hyperréflexie)</li>\n          <li><strong><span>Éclampsie</span></strong> (traitement curatif)</li>\n          <li><strong>Neuroprotection fœtale</strong> avant <span>32 SA</span> en cas de naissance imminente</li>\n        </ul>\n        <strong>Posologie :</strong> dose de charge <span>4 g</span> IVL en <span>20 min</span> puis entretien <span>1 g/h</span>.<br>\n        <strong><span>Surveillance</span> :</strong> ROT (disparition = surdosage), FR (&gt;<span> 12/min</span>), diurèse.<br>\n        <strong>Antidote :</strong> gluconate de calcium IV.\n      </div>\n\n      <h4>Indications d’extraction fœtale</h4>\n      <ul>\n        <li><strong>HTAg non sévère :</strong> accouchement à partir de <strong><span>37-38 SA</span></strong></li>\n        <li><strong><span>Prééclampsie</span> modérée :</strong> accouchement à <strong><span>37 SA</span></strong></li>\n        <li><strong><span>Prééclampsie</span> sévère :</strong> accouchement <strong>quel que soit le terme</strong> (<span>urgence</span> si retentissement maternel ou fœtal)</li>\n        <li><strong><span>Éclampsie</span> / <span>HELLP</span> / <span>HRP</span> :</strong> accouchement en <span>urgence</span> (césarienne le plus souvent)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span>HTA</span> · 326 — Prescription des antihypertenseurs · 344 — HTA gravidique et <span class=\"nc-orange_bg\">prééclampsie</span> · 359 — <span>Détresse</span> respiratoire aiguë</em></p></div>"},{"i":"7ff80781a5f8","n":24,"o":"24-14","u":"Suivi et/ou pronostic","t":"Savoir surveiller une HTAg","q":"Que retenir concernant surveiller une HTAg ?","a":"<div class=\"notion-course\"><p>La <span>surveillance</span> d’une HTAg doit être <strong>rapprochée et structurée</strong>, à la fois <strong>maternelle</strong> (recherche d’<span>évolution</span> vers une <span>prééclampsie</span>, d’une sévérité) et <strong>fœtale</strong> (croissance, bien-être, perfusion).</p>\n\n      <h4>Rythme de <span>surveillance</span> — HTAg pure (non sévère, sans <span>protéinurie</span>)</h4>\n      <table>\n        <thead><tr><th>Volet</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Consultations</strong></td><td><strong>Toutes les <span>1 à 2 semaines</span></strong> selon <span>évolution</span></td></tr>\n          <tr><td><strong>Auto-mesure tensionnelle</strong></td><td>Plusieurs fois/jour à domicile, carnet de <span>surveillance</span></td></tr>\n          <tr><td><strong><span>Bandelette urinaire</span></strong></td><td>À chaque consultation — <span>dépistage</span> de l’apparition d’une <span>protéinurie</span></td></tr>\n          <tr><td><strong>Biologie</strong></td><td><span>NFS</span> <span>plaquettes</span>, <span>créatinine</span>, <span>ASAT</span>/<span>ALAT</span>, <span>uricémie</span>, <span>protéinurie</span>/<span>24 h</span> <strong>toutes les <span>2 semaines</span></strong></td></tr>\n          <tr><td><strong><span>Échographie</span> fœtale</strong></td><td><strong>Toutes les <span>3-4 semaines</span></strong> — croissance, <span>doppler</span> ombilical/utérin</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Critères imposant une <span>hospitalisation</span></h4>\n      <div class=\"callout callout-danger\">\n        <strong><span>Hospitalisation</span> immédiate si :</strong>\n        <ul>\n          <li><span>HTA sévère</span> (PAS <span>≥ 160</span> ou PAD ≥ 110)</li>\n          <li><span>Apparition de protéinurie</span> <span>≥ 0,3 g/24 h</span></li>\n          <li><span>Signes neurologiques</span> (<span>céphalées</span>, troubles visuels)</li>\n          <li><span>Signes biologiques</span> de <span>HELLP</span> ou <span>IRA</span></li>\n          <li><span>RCIU</span> ou <span>doppler</span> ombilical pathologique</li>\n          <li><strong>Mauvaise observance</strong>, <span>surveillance</span> ambulatoire impossible</li>\n        </ul>\n      </div>\n\n      <h4>Auto-<span>surveillance</span> — éducation de la patiente</h4>\n      <ul>\n        <li><strong>Auto-mesure tensionnelle</strong> matin + soir + en cas de symptôme</li>\n        <li><strong>Signes d’alerte</strong> à connaître et signaler en <span>urgence</span> : <span>céphalées</span>, phosphènes, douleur épigastrique, <span>nausées</span>, diminution des mouvements fœtaux</li>\n        <li><strong>Carnet de <span>surveillance</span></strong> avec chiffres tensionnels et symptômes</li>\n        <li><strong>Numéro d’<span>urgence</span></strong> de la maternité</li>\n      </ul>\n\n      <h4><span>Surveillance</span> fœtale — <span>critères de</span> bien-être</h4>\n      <ul>\n        <li><strong>Mouvements actifs fœtaux</strong> ressentis par la mère</li>\n        <li><strong><span>Échographie</span> :</strong> croissance, biométrie (poids estimé), quantité de liquide amniotique</li>\n        <li><strong><span>Doppler</span> ombilical :</strong> recherche d’une diminution du flux diastolique, signe d’insuffisance placentaire</li>\n        <li><strong>RCF / Cardiotocographie</strong> en <span>hospitalisation</span> si <span>HTA</span> mal contrôlée ou signes de sévérité</li>\n      </ul>\n\n      <h4>Lieux de prise en charge</h4>\n      <ul>\n        <li><strong>HTAg modérée bien contrôlée :</strong> <span>surveillance</span> ambulatoire en consultation</li>\n        <li><strong>HTAg sévère ou <span>prééclampsie</span> :</strong> <span>hospitalisation</span> en maternité de niveau adapté</li>\n        <li><strong>Avant <span>32 SA</span> + retentissement fœtal :</strong> <strong>maternité de niveau 3</strong> (réa néonatale)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 224 — <span>HTA</span> · 344 — HTA gravidique et <span class=\"nc-orange_bg\">prééclampsie</span></em></p></div>"},{"i":"e57b926b2ff2","n":24,"o":"24-15","u":"Prise en charge","t":"Connaître la conduite à tenir après l’accouchement en cas d’HTAg","q":"Que retenir concernant la conduite à tenir après l’accouchement en cas d’HTAg ?","a":"<div class=\"notion-course\"><p>Le post-partum est une période <strong>à haut risque</strong> chez les patientes ayant présenté une HTAg/<span><span class=\"nc-orange_bg\">prééclampsie</span></span>. L’<span>éclampsie</span> peut survenir <strong>jusqu’à <span>7 jours</span> après l’accouchement</strong>. La <span>surveillance</span> et le traitement doivent être poursuivis.</p>\n\n      <h4><span>Surveillance</span> immédiate (premières <span>48 h</span>)</h4>\n      <ul>\n        <li><strong>Monitorage tensionnel</strong> rapproché (toutes les <span>4 h</span>, puis allégé selon <span>évolution</span>)</li>\n        <li><strong><span>Surveillance</span> neurologique</strong> : ROT, <span>céphalées</span>, troubles visuels (risque d’<span>éclampsie</span> post-partum jusqu’à <strong><span>7 jours</span></strong>)</li>\n        <li><strong>Diurèse</strong> horaire pendant <span>24 h</span> (<span>surveillance</span> fonction rénale)</li>\n        <li><strong>Bilan <span>biologique</span></strong> à <span>H6</span>, H24, H48 : <span>NFS</span> <span>plaquettes</span>, créat, <span>ASAT</span>/<span>ALAT</span>, <span>LDH</span> (recherche aggravation <span>HELLP</span>)</li>\n        <li><strong>Poursuite du sulfate de Mg</strong> <span>24 h</span> après l’accouchement si <span><span class=\"nc-orange_bg\">prééclampsie</span></span> sévère / <span>éclampsie</span></li>\n      </ul>\n\n      <h4><span>Évolution</span> attendue de l’<span>HTA</span></h4>\n      <table>\n        <thead><tr><th>Phase</th><th>Évolution typique</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>J0</span>-J3</strong></td><td>Possibilité d’aggravation transitoire de l’<span>HTA</span> (pic des résistances vasculaires)</td></tr>\n          <tr><td><strong><span>J3</span>-J10</strong></td><td>Diurèse augmentée, baisse progressive de la TA</td></tr>\n          <tr><td><strong>J10-S6</strong></td><td>Normalisation tensionnelle attendue dans l’HTAg pure</td></tr>\n          <tr><td><strong>&gt; <span>6 semaines</span></strong></td><td>Persistance de l’<span>HTA</span> → suspicion d’<strong><span>HTA</span> chronique sous-jacente</strong> (<span>réévaluation</span> cardio)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Adaptation du traitement antihypertenseur</h4>\n      <ul>\n        <li><strong>Poursuite</strong> de l’antihypertenseur en post-partum, en adaptant la posologie à la TA</li>\n        <li><strong>Décroissance progressive</strong> sur <span>2-6 semaines</span> en cas de normalisation</li>\n        <li><strong>Possibilité d’élargir l’éventail</strong> de molécules après l’accouchement (les <span>IEC</span> redeviennent utilisables — <strong>captopril, énalapril</strong> sont compatibles avec l’<span>allaitement</span>)</li>\n      </ul>\n\n      <h4><span>Allaitement</span></h4>\n      <table>\n        <thead><tr><th>Molécule</th><th>Compatibilité allaitement</th></tr></thead>\n        <tbody>\n          <tr><td><span>Alpha-méthyldopa</span></td><td>Compatible</td></tr>\n          <tr><td><span>Nicardipine</span></td><td>Compatible</td></tr>\n          <tr><td><span>Labétalol</span></td><td>Compatible (préférer aux <span>bêtabloquants</span> liposolubles)</td></tr>\n          <tr><td><span>Captopril / Énalapril</span></td><td>Compatible avec l’<span>allaitement</span> (en post-partum uniquement, jamais pendant la grossesse)</td></tr>\n          <tr><td><span>Diurétiques</span></td><td>Peuvent diminuer la lactation</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Prévention thromboembolique</h4>\n      <ul>\n        <li>Le post-partum d’une HTAg / <span><span class=\"nc-orange_bg\">prééclampsie</span></span> est un <strong>contexte à risque accru de <span>MTEV</span></strong></li>\n        <li><strong>Thromboprophylaxie par <span>HBPM</span></strong> à discuter (durée <span>6 semaines</span> selon FR associés)</li>\n        <li><strong>Bas de contention</strong> + mobilisation précoce</li>\n      </ul>\n\n      <h4>Consultation post-natale (<span>6-8 semaines</span>)</h4>\n      <ul>\n        <li><strong><span>Réévaluation</span> tensionnelle</strong> — confirmer la résolution ou identifier une <span>HTA</span> chronique</li>\n        <li><strong>Bilan rénal complet</strong> (créat, <span>protéinurie</span>/<span>24 h</span>)</li>\n        <li><strong>Information sur le risque cardiovasculaire à long terme</strong> (cf. obj-16)</li>\n        <li><strong>Discussion des grossesses ultérieures</strong> (cf. obj-15)</li>\n        <li><strong>Choix contraceptif</strong> tenant compte des FR vasculaires (privilégier méthodes non-œstrogéniques)</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong><span>Éclampsie</span> du post-partum.</strong> Survenue possible jusqu’à <strong><span>7 jours</span> après l’accouchement</strong>. <span>Surveillance</span> neurologique active + maintien du sulfate de Mg <span>24 h</span> après la naissance dans les prééclampsies sévères.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span>HTA</span> · 326 — Anti-thrombotiques · 344 — HTA gravidique et <span class=\"nc-orange_bg\">prééclampsie</span> · 36 — Contraception</em></p></div>"},{"i":"0ca3553c181c","n":24,"o":"24-16","u":"Prise en charge","t":"Connaître la prévention lors des grossesses ultérieures","q":"Que retenir concernant la prévention lors des grossesses ultérieures ?","a":"<div class=\"notion-course\"><p>Après une HTAg ou une <span><span class=\"nc-orange_bg\">prééclampsie</span></span>, le risque de <strong>récidive lors d’une <span>grossesse</span> ultérieure est significatif</strong> : <span>10-20 %</span> pour la <span><span class=\"nc-orange_bg\">prééclampsie</span></span> (jusqu’à <span>40 %</span> en cas de PE précoce sévère). La <strong>prévention par <span>aspirine</span></strong> est le pivot.</p>\n\n      <h4>Risque de récidive</h4>\n      <table>\n        <thead><tr><th>Contexte</th><th>Risque de récidive</th></tr></thead>\n        <tbody>\n          <tr><td><strong>HTAg pure (non compliquée)</strong></td><td>Risque modéré de récidive d’HTAg, faible risque de <span>prééclampsie</span></td></tr>\n          <tr><td><strong><span>Prééclampsie</span> modérée à terme</strong></td><td><span>~ 10-15 %</span> de récidive</td></tr>\n          <tr><td><strong><span>Prééclampsie</span> sévère ou précoce (&lt; <span>34 SA</span>)</strong></td><td><span>~ 30-40 %</span> de récidive</td></tr>\n          <tr><td><strong>Antécédent d’<span>éclampsie</span> ou <span>HELLP</span></strong></td><td>Risque élevé de récidive (idem PE sévère)</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span>Aspirine</span> faible dose — pivot de la prévention</h4>\n      <div class=\"callout callout-info\">\n        <strong>Indications de l’<span>aspirine 100-160 mg/jour</span> ⭐.</strong>\n        <ul>\n          <li><strong>ATCD personnel de <span>prééclampsie</span></strong> (surtout précoce ou sévère)</li>\n          <li><strong><span>HTA</span> chronique</strong> ou <strong>néphropathie chronique</strong></li>\n          <li><strong><span>Diabète</span> préexistant</strong> (<span>DT1</span> ou <span>DT2</span>)</li>\n          <li><strong><span>Lupus</span> / SAPL</strong> connu</li>\n          <li>Présence de <strong><span>≥ 2</span> FR modérés</strong> : 1ʳᵉ <span>grossesse</span>, âge &gt;<span> 35-40 ans</span>, IMC <span>≥ 35,</span> ATCD familial PE, intervalle long entre grossesses, grossesse multiple, origine afro-caribéenne</li>\n        </ul>\n        <strong>Modalités :</strong>\n        <ul>\n          <li><strong>Début :</strong> entre 12 et <span>16 SA</span> (au plus tard avant <span>20 SA</span>)</li>\n          <li><strong>Prise vespérale</strong> (efficacité maximale démontrée)</li>\n          <li><strong>Arrêt à <span>35-36 SA</span></strong> (avant l’accouchement)</li>\n          <li><strong><span>Réduction</span> du risque de PE de <span>40-60 %</span></strong> dans les indications validées</li>\n        </ul>\n      </div>\n\n      <h4>Autres mesures préventives</h4>\n      <table>\n        <thead><tr><th>Mesure</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Consultation préconceptionnelle</strong></td><td>Bilan complet de la pathologie sous-jacente, optimisation du traitement (substitution <span>IEC</span>/ARA II → alpha-méthyldopa/<span>labétalol</span>), équilibration du <span>diabète</span>, <span>perte de poids</span></td></tr>\n          <tr><td><strong>Supplémentation en calcium</strong></td><td><span>1 g/jour</span> recommandée chez les femmes à apport calcique faible (efficacité modérée)</td></tr>\n          <tr><td><strong><span>Sevrage</span> tabagique</strong></td><td>Important — bien que paradoxalement le <span>tabac</span> diminue le risque de PE, il majore le risque de <span>HRP</span> et <span>RCIU</span></td></tr>\n          <tr><td><strong>Contrôle pondéral</strong></td><td><span>Réduction</span> de l’IMC avant la conception si <span>obésité</span></td></tr>\n          <tr><td><strong>Bilan thrombophilie</strong></td><td>Si <span>prééclampsie</span> précoce / sévère : recherche SAPL, déficit en protéine S, protéine C, antithrombine, mutation Leiden, prothrombine</td></tr>\n        </tbody>\n      </table>\n\n      <h4><span>Surveillance</span> rapprochée de la <span>grossesse</span> suivante</h4>\n      <ul>\n        <li><strong>Consultations rapprochées</strong> dès le 1ᵉʳ trimestre</li>\n        <li><strong><span>Bandelette urinaire</span> + TA</strong> à chaque consultation</li>\n        <li><strong><span>Échographie</span> + <span>doppler</span> utérin à <span>22-24 SA</span></strong> — recherche d’<strong>incisure protodiastolique</strong> ou index de pulsatilité élevé (signes prédictifs de PE)</li>\n        <li><strong><span>Suivi</span> conjoint</strong> obstétricien + médecin référent de la pathologie sous-jacente (cardio, néphro, internal med)</li>\n        <li><strong>Maternité de niveau adapté</strong> au risque</li>\n      </ul>\n\n      <h4>Mesures NON recommandées</h4>\n      <ul>\n        <li><strong>Repos au lit</strong> ❌ — pas d’efficacité préventive prouvée, majore le risque <span>MTEV</span></li>\n        <li><strong>Régime hyposodé</strong> ❌ — pas d’efficacité, peut aggraver l’hypovolémie</li>\n        <li><strong>Vitamines C/E</strong> ❌ — pas d’efficacité (essais négatifs)</li>\n        <li><strong><span>HBPM</span> systématique</strong> ❌ — uniquement si thrombophilie diagnostiquée</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 224 — <span>HTA</span> · 326 — Anti-thrombotiques · 344 — HTA gravidique et <span class=\"nc-orange_bg\">prééclampsie</span></em></p></div>"},{"i":"239e5b8bf20b","n":24,"o":"24-17","u":"Diagnostic positif","t":"Connaître les complications à long terme de l’HTAg","q":"Que retenir concernant les complications à long terme de l’HTAg ?","a":"<div class=\"notion-course\"><p>L’<span>HTA</span> gravidique et la <span><span class=\"nc-orange_bg\">prééclampsie</span></span> ne sont pas des « événements isolés » de la <span>grossesse</span> : elles constituent un <strong>marqueur de risque cardiovasculaire à long terme</strong> pour la femme, justifiant un <strong><span>suivi</span> médical au long cours</strong>.</p>\n\n      <h4>Risques cardiovasculaires à long terme</h4>\n      <table>\n        <thead><tr><th>Risque</th><th>Magnitude</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>HTA</span> chronique</strong></td><td>RR <span>× 2-4</span> <span>vs</span> population générale ; ~ <span>20-30 %</span> des HTAg/PE développent une <span>HTA</span> chronique dans les <span>10-15 ans</span></td></tr>\n          <tr><td><strong>Maladie coronarienne / <span>IDM</span></strong></td><td>RR <span>× 2</span> à long terme (jusqu’à × 8 si PE précoce sévère)</td></tr>\n          <tr><td><strong><span>AVC</span></strong></td><td>RR <span>× 1,5-2</span></td></tr>\n          <tr><td><strong><span>Insuffisance rénale chronique</span></strong></td><td>Risque accru, notamment en cas de PE sévère ou récidivante</td></tr>\n          <tr><td><strong><span>Diabète de type 2</span></strong></td><td>Risque modérément augmenté (<span>terrain</span> métabolique partagé)</td></tr>\n          <tr><td><strong><span>Mortalité</span> cardiovasculaire</strong></td><td>RR <span>× 2</span> globalement</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Mécanismes proposés</h4>\n      <ul>\n        <li><strong>Marqueur d’un <span>terrain</span> prédisposant</strong> (insulinorésistance, dysfonction endothéliale, terrain <span>inflammatoire</span>)</li>\n        <li><strong>Effet propre</strong> de l’<span>HTA</span>/PE sur l’endothélium et la fonction rénale</li>\n        <li><strong>Persistance de <span>facteurs de risque</span></strong> partagés (<span>surpoids</span>, <span>sédentarité</span>)</li>\n      </ul>\n\n      <h4>Conséquences à très long terme — Spécifiques</h4>\n      <ul>\n        <li><strong>Risque accru de <span>prééclampsie</span></strong> dans les grossesses ultérieures (cf. obj-15)</li>\n        <li><strong><span>Insuffisance rénale chronique</span> :</strong> <span>dépistage</span> par <span>créatininémie</span> + <span>protéinurie</span> tous les <span>1-2 ans</span>, surtout si PE sévère ou avec atteinte rénale</li>\n        <li><strong>Hématome sous-capsulaire hépatique</strong> en post-<span>HELLP</span> : généralement résolutif mais risque de séquelles hépatiques</li>\n        <li><strong>Persistance de séquelles neurologiques</strong> exceptionnelles après <span>éclampsie</span> ou <span>PRES</span> syndrome</li>\n      </ul>\n\n      <h4><span>Suivi</span> médical au long cours — recommandations</h4>\n      <div class=\"callout callout-info\">\n        <strong>Plan de <span>suivi</span> systématique après HTAg / <span>prééclampsie</span>.</strong>\n        <ul>\n          <li><strong>Consultation à <span>6-8 semaines</span> :</strong> bilan tensionnel + <span>bilan rénal</span> complet</li>\n          <li><strong>Consultation à <span>3-6 mois</span> :</strong> confirmation de la normalisation</li>\n          <li><strong><span>Suivi</span> annuel</strong> par le médecin traitant : TA, IMC, <span>glycémie à jeun</span>, <span>bilan lipidique</span>, créat + <span>protéinurie</span></li>\n          <li><strong>Évaluation cardiologique</strong> rapprochée si signes ou ATCD de PE sévère</li>\n        </ul>\n        <strong>Éducation à long terme.</strong>\n        <ul>\n          <li>Activité physique régulière</li>\n          <li>Alimentation équilibrée (régime méditerranéen)</li>\n          <li>Maintien d’un poids normal</li>\n          <li><span>Sevrage</span> tabagique impératif</li>\n          <li><span>Dépistage</span> des autres <span>FRCV</span> (<span>diabète</span>, <span>dyslipidémie</span>)</li>\n        </ul>\n      </div>\n\n      <h4>Complications fœtales à long terme</h4>\n      <ul>\n        <li><strong>Enfants nés prématurément</strong> (PE → AP induit) : risque accru de troubles du neurodéveloppement, séquelles respiratoires</li>\n        <li><strong>Enfants avec <span>RCIU</span></strong> : risque augmenté à l’âge adulte d’<span>HTA</span>, <span>diabète</span>, maladie cardiovasculaire (hypothèse de Barker)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span>HTA</span> · 253 — <span>Obésité</span> · 222 — FDR cardiovasculaire · 254 — Nutrition</em></p></div>"},{"i":"25a27d52fd66","n":24,"o":"24-18","u":"Epidémiologie","t":"Définir et diagnostiquer une menace d’accouchement prématuré","q":"Que retenir concernant définir et diagnostiquer une menace d’accouchement prématuré ?","a":"<div class=\"notion-course\"><p>La <span>menace d’accouchement prématuré (MAP)</span> = <span class=\"nc-yellow_bg\">association de </span><strong><span class=\"nc-yellow_bg\">modifications cervicales</span> + <span class=\"nc-yellow_bg\">contractions utérines</span> <span class=\"nc-yellow_bg nc-bold\">régulières</span> et <span class=\"nc-yellow_bg nc-bold\">douloureuses</span></strong>, survenant entre <strong><span>22 SA</span> et <span>36 SA</span> + <span>6 jours</span></strong>. C’est l’une des principales causes d’<span>hospitalisation</span> pendant la <span>grossesse</span>.</p>\n\n      \n\n      <h4>Définitions à connaître</h4>\n      <table>\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Prématurité</strong></td><td>Naissance avant <span>37 SA</span></td></tr>\n          <tr><td><strong><span>Menace</span> d’accouchement prématuré (MAP)</strong></td><td>Modifications cervicales + CU <span class=\"nc-yellow_bg nc-bold\">régulières</span> et <span class=\"nc-yellow_bg nc-bold\">douloureuses</span>, entre <span>22 SA</span> et <span>36 SA + 6 j</span></td></tr>\n          <tr><td><strong>Prématurité <span class=\"nc-red\">moyenne</span> / <span class=\"nc-red\">tardive</span></strong></td><td><span>32-36 SA + 6 j</span> — ≈ <span>80 %</span> des AP</td></tr>\n          <tr><td><strong>Grande prématurité</strong></td><td><span>28-31 SA + 6 j</span> — ≈ <span>10 %</span> des AP</td></tr>\n          <tr><td><strong>Très grande prématurité / prématurité <span class=\"nc-red\">extrême</span></strong></td><td><span>22-27 SA + 6 j</span> — ≈ <span>10 %</span> des AP</td></tr>\n          <tr><td><strong>Seuil de viabilité</strong></td><td>Terme <span><span class=\"nc-pink nc-bold\">≥ 22 SA</span></span> et/ou poids <span><span class=\"nc-pink nc-bold\">≥ 500 g</span></span> et/ou taille <span>≥ 25 cm</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Diagnostic de MAP — <span class=\"nc-red nc-bold\">3 critères</span> associés</h4>\n      <table>\n        <thead><tr><th>Critère</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Terme</strong></td><td>Entre <span>22 SA et 37 SA</span></td></tr>\n          <tr><td><strong><span class=\"nc-yellow_bg\">Contractions utérines</span></strong></td><td>\n            <strong><span class=\"nc-yellow_bg nc-bold\">Régulières</span>, <span class=\"nc-yellow_bg nc-bold\">douloureuses</span></strong> (à distinguer des CU <span class=\"nc-green nc-bold\">physiologiques</span> <span class=\"nc-green nc-bold\">irrégulières</span> et <span class=\"nc-green nc-bold\">indolores</span>)<br>\n            <strong>Cardiotocographie externe</strong> : objective et précise la nature des CU\n          </td></tr>\n          <tr><td><strong>Modifications cervicales</strong></td><td>\n            <strong>Au <span>TV</span> :</strong> <span class=\"nc-red nc-bold\">ramollissement</span>, <span class=\"nc-red nc-bold\">effacement</span>, <span class=\"nc-red nc-bold\">dilatation du col</span><br>\n            <strong><span><span class=\"nc-blue_bg\">Échographie</span></span><span class=\"nc-blue_bg\"> du col</span> :</strong> <span>longueur cervicale <span class=\"nc-pink nc-bold\">&lt; 25 mm</span></span> = <span class=\"nc-red nc-bold\">col raccourci</span> → MAP\n          </td></tr>\n        </tbody>\n      </table>\n\n      <h4>Marqueur <span>biologique</span> d’aide au diagnostic</h4>\n      <div class=\"callout callout-info\">\n        <strong>Fibronectine fœtale</strong> (non systématique).\n        <ul>\n          <li><strong>Intérêt :</strong> prédit le risque d’accouchement avant <span>34 SA</span> (<span>VPN à 90 %</span>, spécificité supérieure au <span>TV</span>)</li>\n          <li><strong>Rationnel :</strong> fibronectine <span class=\"nc-red nc-bold\">normalement </span><strong><span class=\"nc-red nc-bold\">absente des sécrétions vaginales au-delà de </span><span><span class=\"nc-red nc-bold\">24 SA</span></span></strong></li>\n          <li>Sa positivité oriente vers un risque accru, sa négativité quasi-élimine la MAP</li>\n          <li><em>Réservée aux cas douteux ; ne se prescrit pas si MAP évidente</em></li>\n        </ul>\n      </div>\n\n      <h4>Col normal <span>vs</span> col raccourci</h4>\n      <ul>\n        <li><strong>Col normal de la nullipare :</strong> long, postérieur, fermé, consistance dure (« comme un nez »)</li>\n        <li>En cas de CU actives → le col se <strong>raccourcit, se centre, se ramollit, s’ouvre</strong></li>\n        <li><strong>Mesure échographique du col :</strong> coupe sagittale, visualisation orifices interne et externe, mesure de la longueur en dehors et pendant la contraction → <strong>seuil <span>25 mm</span></strong></li>\n      </ul>\n\n      <h4><span>Diagnostic différentiel</span></h4>\n      <ul>\n        <li><strong><span class=\"nc-yellow_bg\">Contractions utérines</span> <span class=\"nc-green nc-bold\">physiologiques</span></strong> (Braxton-Hicks) : <span class=\"nc-green nc-bold\">irrégulières</span>, <span class=\"nc-green nc-bold\">indolores</span>, ne modifient pas le col</li>\n        <li><strong>Faux travail :</strong> CU douloureuses mais sans modification cervicale</li>\n        <li><strong>Travail réel</strong> avant <span>37 SA</span> : CU + col en travail (<span class=\"nc-red nc-bold\">effacement</span> et dilatation avancés) → <span>urgence</span></li>\n        <li><strong><span><span class=\"nc-red_bg\">Rupture</span></span><span class=\"nc-red_bg\"> prématurée des membranes</span></strong> : peut être associée à MAP, ou isolée</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Attention.</strong> Ce n’est pas parce qu’une femme a des <span class=\"nc-yellow_bg\">contractions utérines</span> qu’elle a forcément une MAP. <strong>Au moindre doute → <span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> du col</span></strong> pour mesurer objectivement la longueur cervicale.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 27 — Prévention des risques fœtaux · 359 — <span>Détresse</span> respiratoire néonatale</em></p></div>"},{"i":"a495b5001da3","n":24,"o":"24-19","u":"Epidémiologie","t":"Connaître les facteurs de risque de la menace d’accouchement prématuré","q":"Que retenir concernant les facteurs de risque de la menace d’accouchement prématuré ?","a":"<div class=\"notion-course\"><p>Le bilan étiologique d’une MAP est <strong>indispensable</strong> mais reste <strong>négatif dans <span>40 %</span></strong> des cas (MAP idiopathique). La connaissance des FR oriente la PEC et la prévention.</p>\n\n      <h4><span>Facteurs de risque</span> maternels (terrain)</h4>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Facteurs</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Âge</strong></td><td><span>&lt; 18 ans</span> ou <span>&gt; 35 ans</span></td></tr>\n          <tr><td><strong>Toxiques</strong></td><td><span><span class=\"nc-red nc-bold\">Tabac</span></span>, <span><span class=\"nc-red nc-bold\">alcool</span></span>, <span><span class=\"nc-red nc-bold\">drogues</span></span> (cocaïne ++)</td></tr>\n          <tr><td><strong>Socio-éducatif</strong></td><td><span class=\"nc-green_bg\">Célibat</span>, <span class=\"nc-green_bg\">très bas niveau socio-économique</span>, mauvais <span>suivi</span> prénatal</td></tr>\n          <tr><td><strong>Travail / vie quotidienne</strong></td><td><span class=\"nc-green_bg\">Travail pénible</span>, <span class=\"nc-green_bg\">trajets longs quotidiens</span>, <span class=\"nc-green_bg\">nombreux enfants à charge</span></td></tr>\n          <tr><td><strong>Psychologique</strong></td><td><span><span class=\"nc-orange_bg\">Dépression</span></span>, <span class=\"nc-orange_bg\">anxiété</span>, <span class=\"nc-orange_bg\">stress maternel</span></td></tr>\n          <tr><td><strong>Traumatisme</strong></td><td><span class=\"nc-orange_bg\">Traumatisme abdominal</span></td></tr>\n          <tr><td><strong>Métrorragies</strong></td><td>Au 2ᵉ/3ᵉ trimestre, même hors <span><span class=\"nc-orange_bg\">placenta praevia</span></span> (favorisent <span>RPM</span>)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Causes infectieuses</h4>\n      <ul>\n        <li><strong>Toute infection</strong> peut entraîner des CU via la <span>fièvre</span></li>\n        <li><strong><span class=\"nc-purple_bg\">Infections urinaires</span></strong>, <span class=\"nc-purple_bg\">bactériuries asymptomatiques</span> (colonisation urinaire gravidique)</li>\n        <li><strong><span class=\"nc-purple_bg\">Infections vaginales</span></strong> (<span><span class=\"nc-red_bg\">vaginose bactérienne</span></span>)</li>\n        <li><strong><span>Chorioamniotite</span></strong> (« infection de l’œuf ») et/ou <span>RPM</span></li>\n      </ul>\n\n      <h4>Facteurs cervicaux</h4>\n      <ul>\n        <li><strong><span class=\"nc-pink_bg\">ATCD de conisation</span></strong> (<span>chirurgie</span> visant à réséquer une partie du col)</li>\n        <li><strong><span class=\"nc-yellow_bg\">Col court</span></strong> mesuré en <span>échographie</span> (mesure non systématique)</li>\n        <li><strong>Béance cervico-isthmique</strong> (incompétence cervicale) — cause principale de <span>FCT</span> et AP très précoce / <span>RPM</span> avant <span>32 SA</span></li>\n      </ul>\n\n      <h4>Facteurs corps utérin</h4>\n      <ul>\n        <li><strong><span class=\"nc-red nc-bold\">Diminution</span> de la taille utérine</strong> avant <span>grossesse</span> : fibromes, <span class=\"nc-orange_bg\">utérus polymyomateux</span>, utérus diéthylstilbœstrol (exposition in utero à Distilbène®), malformations utérines (utérus hypoplasiques, unicornes, bicornes, cloisonnés)</li>\n        <li><strong>Augmentation de la distension utérine</strong> pendant la <span>grossesse</span> : <span class=\"nc-orange_bg\">hydramnios</span>, macrosomie fœtale, <strong><span class=\"nc-green_bg\">grossesses multiples</span></strong> (taux de prématurité <span>45 %</span>, RR × 7)</li>\n      </ul>\n\n      <h4>Autres FR liés à la <span>grossesse</span></h4>\n      <ul>\n        <li><strong>FIV</strong></li>\n        <li><strong>Intervalle court</strong> entre <span <span=\"\">&gt;2</span> grossesses (<span class=\"nc-pink nc-bold\">&lt; </span><span><span class=\"nc-pink nc-bold\">18 mois</span></span>)</li>\n        <li><strong><span><span class=\"nc-orange_bg\">Placenta praevia</span></span></strong> (RR × 6-7 d’AP), décollement placentaire</li>\n        <li><strong>Anémie maternelle</strong></li>\n        <li><strong><span>Diabète gestationnel</span></strong> (par macrosomie, hydramnios, infection intercurrente)</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Facteurs de gravité de la MAP (rang C — à connaître).</strong>\n        <ul>\n          <li>Âge gestationnel <span>&lt; 28 SA</span></li>\n          <li>Importance des modifications cervicales</li>\n          <li>Patiente accueillie dans une <span class=\"nc-green_bg\">maternité</span> de <strong>niveau non adapté</strong></li>\n          <li><strong><span>Grossesse</span> multiple</strong></li>\n          <li><strong><span><span class=\"nc-red_bg\">Rupture</span></span><span class=\"nc-red_bg\"> des membranes</span> ou <span><span class=\"nc-purple_bg\">chorioamniotite</span></span></strong> associée</li>\n          <li><strong>Métrorragies</strong> associées</li>\n          <li>Col fortement modifié, très menaçant, poche des eaux visible au spéculum</li>\n          <li>Tentative inefficace de tocolyse</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 255 — <span>Diabète gestationnel</span> · 75 — Addiction <span>tabac</span> · 76 — Addictions <span><span class=\"nc-red nc-bold\">alcool</span></span> · 78 — Addictions <span class=\"nc-red nc-bold\">drogues</span></em></p></div>"},{"i":"a67a78cc6b89","n":24,"o":"24-20","u":"Diagnostic positif","t":"Connaître le bilan d’une menace d’accouchement prématuré","q":"Que retenir concernant le bilan d’une menace d’accouchement prématuré ?","a":"<div class=\"notion-course\"><p>Le bilan d’une MAP comporte 4 volets : <strong>clinique</strong>, <strong>fœtal</strong>, <strong>étiologique</strong>, <strong>pré-thérapeutique</strong>.</p>\n\n      <h4>1. Bilan clinique</h4>\n      <ul>\n        <li><strong>Constantes habituelles</strong> : PA, FC, température, <span>BU</span></li>\n        <li><strong><span class=\"nc-yellow_bg\">Examen au spéculum</span></strong> : recherche d’un <strong>écoulement liquidien</strong> (<span>RPM</span> ?), métrorragies, leucorrhées</li>\n        <li><strong>Toucher vaginal</strong> : évaluation du col (<span class=\"nc-red nc-bold\">ramollissement</span>, <span class=\"nc-red nc-bold\">effacement</span>, dilatation)</li>\n        <li><strong>Mesure de la hauteur utérine :</strong>\n          <ul>\n            <li><strong>Augmentée</strong> → oriente vers une <strong>macrosomie fœtale</strong> ou un <strong><span class=\"nc-red nc-bold\">hydramnios</span></strong></li>\n            <li><strong>Diminuée</strong> → peut faire suspecter une <strong><span><span class=\"nc-red nc-bold\">rupture</span></span><span class=\"nc-red nc-bold\"> spontanée des membranes</span></strong></li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>2. Bilan fœtal</h4>\n      <ul>\n        <li><strong>Enregistrement du RCF</strong> par cardiotocographie externe</li>\n        <li><strong><span><span class=\"nc-blue_bg\">Échographie</span></span><span class=\"nc-blue_bg\"> obstétricale</span> :</strong> mouvements actifs fœtaux, estimation du poids fœtal, quantité de liquide amniotique, présentation, position du placenta</li>\n        <li><strong><span><span class=\"nc-blue_bg\">Échographie</span></span><span class=\"nc-blue_bg\"> du col</span></strong> par voie endovaginale : mesure de la longueur cervicale, recherche d’une protrusion des membranes</li>\n      </ul>\n\n      <h4>3. Bilan étiologique</h4>\n      <table>\n        <thead><tr><th>Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><span>NFS, CRP</span></td><td>Recherche d’un <strong><span>syndrome inflammatoire</span></strong> (<span>chorioamniotite</span>, infection)</td></tr>\n          <tr><td><span>ECBU</span></td><td>Recherche d’une <strong><span>infection urinaire</span></strong> ou bactériurie</td></tr>\n          <tr><td><span>Prélèvement cervico-vaginal</span></td><td>Recherche de <strong><span>vaginose</span></strong>, <strong><span>streptocoque B</span></strong>, autres germes</td></tr>\n          <tr><td><strong>Test biochimique de <span>RPM</span></strong></td><td>Si doute sur <span>RPM</span> : <span><span class=\"nc-pink nc-bold\">IGFBP-1</span> (Actim-PROM)</span>, <span><span class=\"nc-pink nc-bold\">PAMG-1</span> (AmniSure)</span>, ou DAO — recherche de composants du liquide amniotique dans le vagin</td></tr>\n        </tbody>\n      </table>\n\n      <h4>4. <span>Bilan pré-thérapeutique</span></h4>\n      <ul>\n        <li><strong><span><span class=\"nc-pink nc-bold\">Glycémie</span></span></strong> — risque de <strong>déséquilibre d’un <span>diabète gestationnel</span> non diagnostiqué</strong> sous <span>corticothérapie</span></li>\n        <li><strong><span><span class=\"nc-blue_bg\">ECG</span></span></strong> avant <span>32 SA</span>, en prévision d’un traitement par <strong><span class=\"nc-pink_bg\">sulfate de magnésium</span></strong> (jugé inutile selon Masson, à pondérer)</li>\n        <li><span><span class=\"nc-blue_bg\">Groupe, Rhésus, RAI</span></span> en cas d’<span class=\"nc-orange nc-bold\">accouchement imminent</span></li>\n      </ul>\n\n      <h4><span class=\"nc-pink_bg\">Fibronectine fœtale</span> — quand la prescrire ?</h4>\n      <div class=\"callout callout-info\">\n        <strong>Indication.</strong> Cas <strong>douteux</strong> (CU ressenties par la patiente, col légèrement modifié) où le diagnostic de MAP n’est ni évident ni écarté.\n        <ul>\n          <li><strong>Si négative</strong> → quasi-élimine une MAP (VPN ≈ <span>90 %</span>) → <span>surveillance</span> allégée</li>\n          <li><strong>Si positive</strong> → renforce le diagnostic → <span>hospitalisation</span>, traitement</li>\n          <li><strong>Non indiquée si MAP évidente</strong> (col déjà très modifié) ❌</li>\n        </ul>\n      </div>\n\n      <h4>Conclusion du bilan</h4>\n      <ul>\n        <li>Confirmer / écarter le diagnostic de MAP</li>\n        <li>Identifier une étiologie traitable (infection, <span>RPM</span>)</li>\n        <li>Évaluer la sévérité (terme, modifications cervicales, RCF, <span>signes de gravité</span> associés)</li>\n        <li>Orienter vers une <strong><span class=\"nc-green_bg\">maternité</span> de niveau adapté</strong> (cf. obj-20)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 161 — Infection urinaire · 255 — <span>Diabète gestationnel</span></em></p></div>"},{"i":"1301ed4011e7","n":24,"o":"24-21","u":"Prise en charge","t":"Connaître les principes de la prise en charge d’une menace d’accouchement prématuré","q":"Que retenir concernant les principes de la prise en charge d’une menace d’accouchement prématuré ?","a":"<div class=\"notion-course\"><ul><li>Confirmer le risque d’accouchement prématuré : terme, contractions et modifications cervicales, membranes, infection et état fœtal. Une simple activité utérine ne suffit pas à diagnostiquer une MAP.</li><li>Organiser l’accueil dans une <span class=\"nc-green_bg\">maternité</span> adaptée aux besoins néonataux : transfert in utero si réalisable sans danger, en concertation avec le réseau. La stabilité maternelle et fœtale prime ; une naissance imminente ou une urgence ne doit pas être retardée pour un transfert.</li><li>Si naissance probable avant 34 SA : corticothérapie anténatale, habituellement bétaméthasone 12 mg IM puis 12 mg 24 heures plus tard. Elle ne justifie pas de différer une extraction urgente.</li><li><span class=\"nc-yellow_bg\">Tocolyse</span> courte, généralement jusqu’à 48 heures, pour permettre corticothérapie et transfert chez une femme éligible. <span class=\"nc-pink nc-bold\">Nifédipine</span> ou <span class=\"nc-pink nc-bold\">atosiban</span> selon le contexte ; pas de traitement d’entretien systématique.</li><li>Pas de tocolyse en cas d’infection intra-amniotique suspectée, hémorragie menaçante, souffrance fœtale ou indication maternelle à faire naître. Les antibiotiques ne sont pas systématiques à membranes intactes ; traiter une infection documentée et appliquer le protocole de <span class=\"nc-red_bg\">rupture prématurée des membranes</span>.</li><li>Si naissance imminente avant 32 SA : discuter <span class=\"nc-pink_bg\">sulfate de magnésium</span> pour neuroprotection selon protocole, distinct de son emploi dans la prééclampsie. Information parentale et avis pédiatrique.</li></ul></div>"},{"i":"a35820df91e9","n":24,"o":"24-22","u":"Prise en charge","t":"Connaître les mesures de prévention de la menace d’accouchement prématuré","q":"Que retenir concernant les mesures de prévention de la menace d’accouchement prématuré ?","a":"<div class=\"notion-course\"><p>La prévention de la MAP repose sur (1) <strong>prévention pré-conceptionnelle</strong>, (2) <strong>prise en charge des FR</strong> pendant la <span>grossesse</span>, (3) <strong>traitements spécifiques</strong> chez les patientes à haut risque.</p>\n\n      <h4>Prévention pré-conceptionnelle</h4>\n      <ul>\n        <li><strong><span>Sevrage</span> tabagique</strong> — <span class=\"nc-yellow_bg\">seul FR modifiable d’AP dont le sevrage est associé à une diminution de la prématurité</span></li>\n        <li><strong>Limitation des <span class=\"nc-green_bg\">grossesses multiples</span></strong> en cas de PMA (transfert d’1 seul embryon)</li>\n        <li><strong>Information</strong> sur les risques des <span class=\"nc-red_bg\">grossesses rapprochées</span> (intervalle <span class=\"nc-pink\">&lt; </span><span><span class=\"nc-pink\">18 mois</span></span>)</li>\n        <li><strong>Bilan préconceptionnel</strong> en cas d’ATCD d’AP ou de <span>FCT</span></li>\n      </ul>\n\n      <h4>Prise en charge des FR pendant la <span>grossesse</span></h4>\n      <table>\n        <thead><tr><th>FR</th><th>Mesure</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span><span class=\"nc-yellow_bg\">Tabac</span></span></strong></td><td><strong><span>Sevrage</span></strong> (seul FR modifiable avec efficacité prouvée)</td></tr>\n          <tr><td><strong><span>Alcool</span>, toxiques</strong></td><td>Arrêt + accompagnement addictologique</td></tr>\n          <tr><td><strong><span class=\"nc-green_bg\">Travail pénible</span></strong></td><td>Arrêt de travail (station debout &gt; <span>6 h</span>, longs trajets)</td></tr>\n          <tr><td><strong><span class=\"nc-orange_bg\">Stress maternel</span></strong></td><td>PEC psychologique possible, soutien</td></tr>\n          <tr><td><strong>Alimentation</strong></td><td>Équilibrée</td></tr>\n          <tr><td><strong>Pathologies préexistantes</strong></td><td>Optimisation (<span>diabète</span>, <span>asthme</span>, <span>HTA</span>...)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Malformations utérines</h4>\n      <ul>\n        <li><strong>Rechercher</strong> les malformations utérines (<span>échographie</span> pelvienne 3D, <span>hystérographie</span>)</li>\n        <li><strong>Corriger</strong> avant la <span>grossesse</span> si possible : <span><span class=\"nc-pink nc-bold\">résection de cloison utérine</span></span></li>\n      </ul>\n\n      <h4><span class=\"nc-red_bg\">Vaginose </span><span><span class=\"nc-red_bg\">bactérienne</span></span></h4>\n      <div class=\"callout callout-info\">\n        <strong>Si ATCD d’AP dans un contexte d’infection materno-fœtale <span>bactérienne</span> :</strong>\n        <ol>\n          <li><strong><span>Dépistage</span></strong> de la <span><span class=\"nc-red_bg\">vaginose bactérienne</span></span> par <strong>prélèvement vaginal au 1ᵉʳ trimestre</strong></li>\n          <li><strong>Si positive → traitement systématique :</strong> <span><span class=\"nc-pink nc-bold\">métronidazole</span></span> ou <span><span class=\"nc-pink nc-bold\">clindamycine</span></span> pendant <span><span class=\"nc-pink_bg\">7 jours</span></span></li>\n        </ol>\n      </div>\n\n      <h4>Béance cervicale — <span class=\"nc-pink nc-bold\">Cerclage</span> <span>vs</span> <span class=\"nc-pink_bg\">progestérone</span></h4>\n      <table>\n        <thead><tr><th>Contexte</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>≥ 3</span> ATCD d’AP ou <span>FCT</span></strong></td><td><strong>Cerclage formellement indiqué</strong> (placé à la fin du 1ᵉʳ trimestre)</td></tr>\n          <tr><td><strong>1 ou 2 ATCD d’AP ou <span>FCT</span></strong></td><td><span>Surveillance</span> écho col entre 16 et <span>22 SA</span> + <strong><span class=\"nc-pink nc-bold\">cerclage</span> si col <span class=\"nc-pink\">&lt; </span><span><span class=\"nc-pink\">25 mm</span></span></strong> ; <span class=\"nc-pink nc-bold\">progestérone micronisée vaginale</span> possible</td></tr>\n          <tr><td><strong>Pas d’ATCD</strong></td><td><span>Échographie</span> entre <span class=\"nc-pink\">16 et </span><span><span class=\"nc-pink\">24 SA</span></span> ; si <strong>col <span class=\"nc-pink\">&lt; </span><span><span class=\"nc-pink\">20 mm</span></span> → <span class=\"nc-pink nc-bold\">progestérone micronisée vaginale</span></strong> formellement indiquée</td></tr>\n          <tr><td><strong>Cerclage préventif systématique</strong></td><td><span>Non recommandé</span> sur seul <span class=\"nc-pink_bg\">ATCD de conisation</span>, <span class=\"nc-orange_bg\">malformation utérine</span>, <span>grossesse</span> gémellaire ou ATCD isolé d’AP</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Principe du cerclage</h4>\n      <ul>\n        <li><strong>Définition :</strong> mise en place d’un « nœud » (suture) autour du col pour empêcher mécaniquement son ouverture</li>\n        <li><strong>Placement :</strong> fin du 1ᵉʳ trimestre</li>\n        <li><strong>Retrait :</strong> en fin de <span>grossesse</span> pour permettre l’accouchement</li>\n        <li><strong>Attention :</strong> le cerclage n’est <strong>pas un traitement de la MAP</strong> mais une mesure préventive chez patientes à risque</li>\n      </ul>\n\n      <h4>Mesures NON recommandées</h4>\n      <ul>\n        <li><strong><span>Hospitalisation</span> prolongée</strong> ❌ — ne réduit pas le risque d’AP, majore le risque <span><span class=\"nc-orange nc-bold\">MTEV</span></span></li>\n        <li><strong><span class=\"nc-green_bg\">Repos</span> au lit strict</strong> ❌ — pas d’efficacité, majore <span><span class=\"nc-orange nc-bold\">MTEV</span></span></li>\n        <li><strong>Recherche systématique de <span class=\"nc-pink_bg\">fibronectine fœtale</span></strong> ❌ — réservée aux cas de suspicion de MAP</li>\n        <li><strong>Mesure systématique du col</strong> en <span>échographie</span> chez patientes sans FR ❌</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Risque de récidive</strong> lors de la <span>grossesse</span> suivante est <strong>important</strong>, justifiant un bilan étiologique attentif, bien souvent négatif (<span>40 %</span> idiopathiques).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 75 — Addiction <span>tabac</span> · 161 — Infection urinaire · 36 — Contraception</em></p></div>"},{"i":"d12e4e422bf5","n":24,"o":"24-23","u":"Diagnostic positif","t":"Connaître les signes d’orientation diagnostique et de gravité en cas de fièvre au cours de la grossesse","q":"Que retenir concernant les signes d’orientation diagnostique et de gravité en cas de fièvre au cours de la grossesse ?","a":"<div class=\"notion-course\"><p>La <span>fièvre</span> pendant la <span>grossesse</span> est une situation <strong>fréquente</strong> (<span>10-15 %</span> des grossesses). <strong>Définition :</strong> température maternelle <span>&gt; 38 °C</span>.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Dogme.</strong> Toute <span>fièvre</span> in utero est une infection <strong>jusqu’à preuve du contraire</strong> — et plus précisément une <span><span class=\"nc-red nc-bold\">listériose</span> jusqu’à preuve du contraire</span>.\n      </div>\n\n      <h4>Étiologies à connaître par fréquence</h4>\n      <table>\n        <thead><tr><th>Étiologie</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Infections bénignes</strong> (<span><span class=\"nc-green_bg\">grippe</span></span>, <span class=\"nc-green_bg\">gastro-entérite</span>, <span class=\"nc-green_bg\">angine</span>)</td><td>Le plus souvent — PEC à domicile possible</td></tr>\n          <tr><td><strong><span><span class=\"nc-brown_bg\">Pyélonéphrite</span></span><span class=\"nc-brown_bg\"> aiguë gravidique</span></strong> ⭐</td><td><strong>Étiologie la plus fréquente</strong> — <span>fièvre</span> + douleur lombaire + brûlures mictionnelles</td></tr>\n          <tr><td><strong><span>Listériose</span></strong></td><td>Grave — passage <span class=\"nc-red nc-bold\">transplacentaire</span>, risque de mort fœtale, prématurité, séquelles néonatales</td></tr>\n          <tr><td><strong><span><span class=\"nc-orange nc-bold\">Chorioamniotite</span></span></strong></td><td>Grave — <span>fièvre</span> + CU + <span><span class=\"nc-red_bg nc-bold\">tachycardie</span></span><span class=\"nc-red_bg nc-bold\"> fœtale</span> + <span class=\"nc-yellow_bg\">leucorrhées suspectes</span></td></tr>\n          <tr><td><strong>Infections materno-fœtales</strong></td><td><span><span class=\"nc-purple_bg\">Rubéole</span></span>, <span><span class=\"nc-purple_bg\">toxoplasmose</span></span>, <span><span class=\"nc-purple_bg\">herpès</span></span>, <span><span class=\"nc-purple_bg\">syphilis</span></span>, <span><span class=\"nc-purple_bg\">CMV</span></span>, <span><span class=\"nc-purple_bg\">VIH</span></span>, hépatites virales (donnent rarement de la <span>fièvre</span>)</td></tr>\n          <tr><td><strong>Causes digestives</strong></td><td><span><span class=\"nc-orange nc-bold\">Appendicite</span></span>, <span>cholécystite</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Signes d’orientation par contexte</h4>\n      <ul>\n        <li><strong>Signes urinaires</strong> (douleurs lombaires, brûlures mictionnelles, <span>BU</span> positive) → <strong><span>PNA</span> gravidique</strong> ++</li>\n        <li><strong>Signes obstétricaux</strong> (CU + écoulement liquide amniotique + <span class=\"nc-yellow_bg\">leucorrhées suspectes</span>) → <strong><span><span class=\"nc-orange nc-bold\">chorioamniotite</span></span> / <span>RPM</span></strong></li>\n        <li><strong>Syndrome grippal</strong> en période d’épidémie → infection bénigne probable</li>\n        <li><strong>Signes digestifs</strong> (douleur fosse iliaque droite, défense, signe de Murphy) → <span><span class=\"nc-orange nc-bold\">appendicite</span></span> / <span><span class=\"nc-orange nc-bold\">cholécystite</span></span></li>\n        <li><strong><span>Fièvre</span> isolée, <span class=\"nc-green_bg\">mal expliquée</span></strong>, hors contexte épidémique → <strong>évoquer <span><span class=\"nc-orange\">listériose</span></span></strong> ++</li>\n        <li><strong><span class=\"nc-red_bg\">Diminution des mouvements actifs</span> fœtaux + <span><span class=\"nc-red_bg nc-bold\">tachycardie</span></span><span class=\"nc-red_bg nc-bold\"> fœtale</span></strong> → souffrance fœtale → <strong><span><span class=\"nc-orange\">listériose</span></span> ? <span><span class=\"nc-orange nc-bold\">chorioamniotite</span></span> ?</strong></li>\n      </ul>\n\n      <h4><span>Signes de gravité</span> — Indications d’<span>hospitalisation</span></h4>\n      <div class=\"callout callout-danger\">\n        <strong>Indications d’<span>hospitalisation</span> systématique :</strong>\n        <ul>\n          <li><span>Signes évocateurs de <span class=\"nc-orange nc-bold\">PNA</span></span></li>\n          <li><span>Signes évocateurs de <span class=\"nc-orange nc-bold\">chorioamniotite</span></span></li>\n          <li><strong><span>Fièvre</span> en apparence bénigne mais <span class=\"nc-green_bg\">mal expliquée</span></strong> (isolée, syndrome grippal hors contexte épidémique...)</li>\n          <li><strong><span>Fièvre</span> + <span class=\"nc-red_bg\">signes d’hypoxie fœtale</span></strong> (<span class=\"nc-red nc-bold\">diminution</span> mouvements, <span><span class=\"nc-red_bg nc-bold\">tachycardie</span></span><span class=\"nc-red_bg nc-bold\"> fœtale</span>) → <span><span class=\"nc-orange\">listériose</span></span> ? <span><span class=\"nc-orange nc-bold\">chorioamniotite</span></span> ?</li>\n          <li><strong><span><span class=\"nc-orange nc-bold\">Appendicite</span></span>, <span><span class=\"nc-orange nc-bold\">cholécystite</span></span></strong> ou autre cause chirurgicale</li>\n          <li><strong><span>Hyperthermie</span> &gt; <span>38,5 °C</span></strong> sans cause identifiée</li>\n          <li><strong>Mauvaise tolérance maternelle</strong> (<span>frissons</span>, <span>AEG</span>, signes de <span>sepsis</span>)</li>\n        </ul>\n      </div>\n\n      <h4>Retentissement obstétrical à évaluer systématiquement</h4>\n      <ul>\n        <li><strong><span><span class=\"nc-red_bg\">Menace</span></span><span class=\"nc-red_bg\"> d’accouchement prématuré</span></strong> (la <span>fièvre</span> peut provoquer des CU = FR de MAP)</li>\n        <li><strong><span class=\"nc-red_bg\">Hypoxie fœtale</span></strong> (<span><span class=\"nc-red_bg nc-bold\">tachycardie</span></span><span class=\"nc-red_bg nc-bold\"> fœtale</span>, <span class=\"nc-red_bg\">diminution des mouvements actifs</span>)</li>\n        <li><strong><span><span class=\"nc-red_bg\">Rupture</span></span><span class=\"nc-red_bg\"> prématurée des membranes</span></strong></li>\n      </ul>\n\n      <h4>Situations autorisant une PEC à domicile</h4>\n      <ul>\n        <li><strong><span class=\"nc-green_bg\">Étiologie bénigne clairement identifiée</span></strong> : syndrome grippal typique en période d’épidémie, <span class=\"nc-green_bg\">gastro-entérite</span> bénigne...</li>\n        <li><strong>Absence de CU</strong></li>\n        <li><strong>Mouvements fœtaux et RCF normaux</strong></li>\n        <li><strong>Tolérance maternelle correcte</strong></li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — Infection urinaire · 157 — Septicémie/Bactériémie · 147 — <span>Fièvre</span> aiguë chez l’adulte · 162 — IST · 27 — Prévention des risques fœtaux (<span class=\"nc-purple_bg\">toxoplasmose</span>)</em></p></div>"},{"i":"36708ab96061","n":24,"o":"24-24","u":"Diagnostic positif","t":"Connaître le bilan en cas de fièvre au cours de la grossesse","q":"Que retenir concernant le bilan en cas de fièvre au cours de la grossesse ?","a":"<div class=\"notion-course\"><p>Le bilan d’une <span>fièvre</span> pendant la <span>grossesse</span> vise à <strong>identifier rapidement</strong> la cause (notamment <strong><span>listériose</span></strong> ++) et à <strong>évaluer le retentissement obstétrical</strong>.</p>\n\n      <h4>Interrogatoire</h4>\n      <ul>\n        <li><strong>ATCD prédisposants :</strong> infections urinaires à répétition, uropathies, maladies chroniques, immunodépression, prématurité, <span>tabac</span>...</li>\n        <li><strong>Traitements en cours</strong></li>\n        <li><strong>Contexte :</strong> épidémie, voyage, alimentation à risque (fromage au lait cru → <span>listeria</span>)</li>\n        <li><strong>Signes d’accompagnement :</strong>\n          <ul>\n            <li><strong>Généraux :</strong> <span>frissons</span>, ORL, pulmonaires, digestifs, syndrome grippal</li>\n            <li><strong>Urinaires :</strong> douleurs lombaires, brûlures mictionnelles</li>\n            <li><strong>Obstétricaux :</strong> CU, écoulement de liquide amniotique, leucorrhées, saignements</li>\n          </ul>\n        </li>\n        <li><strong>Mouvements actifs fœtaux</strong></li>\n        <li><strong>Résultats des <span>sérologies</span></strong> (<span><span class=\"nc-purple_bg\">toxoplasmose</span></span>, <span><span class=\"nc-purple_bg\">rubéole</span></span> — donnent rarement de la <span>fièvre</span>)</li>\n      </ul>\n\n      <h4>Examen clinique</h4>\n      <ul>\n        <li><strong>Constantes :</strong> température, pouls, PA</li>\n        <li><strong>Examen général :</strong> ORL, cardiorespiratoire, aires lymphonodales, état cutané, <span>syndrome méningé</span>, abdomen, fosses lombaires</li>\n        <li><strong>Examen urinaire :</strong> aspect des urines, <span>bandelette urinaire</span></li>\n        <li><strong>Examen obstétrical :</strong>\n          <ul>\n            <li><strong>Hauteur utérine</strong></li>\n            <li><strong>Bruits du cœur / RCF</strong></li>\n            <li><strong>Vulve :</strong> vésicules ou ulcérations herpétiques</li>\n            <li><strong>Au spéculum :</strong> <span>rupture</span> des membranes, leucorrhées, vésicules herpétiques</li>\n            <li><strong><span>TV</span> :</strong> modifications cervicales</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>Bilan paraclinique systématique</h4>\n      <table>\n        <thead><tr><th>Examen</th><th>Justification</th></tr></thead>\n        <tbody>\n          <tr><td><span>ECBU</span></td><td>Recherche d’une <strong><span>infection urinaire</span> / <span>PNA</span></strong></td></tr>\n          <tr><td><span><span class=\"nc-blue_bg\">NFS, CRP</span></span></td><td><span>Syndrome inflammatoire</span>. <strong>Attention :</strong> hyperleucocytose physiologique pendant la <span>grossesse</span></td></tr>\n          <tr><td><span>VS</span></td><td><strong>N’a aucune valeur</strong> pendant la <span>grossesse</span> — <strong>physiologiquement augmentée</strong></td></tr>\n          <tr><td><span><span class=\"nc-purple_bg\">Hémocultures</span></span></td><td>Si T° <strong>&gt; <span>38,5 °C</span></strong> — <strong>2 paires</strong>, recherche de <strong><span>Listeria</span></strong> ++</td></tr>\n          <tr><td><strong><span class=\"nc-brown_bg\">Électro-cardiotocographie</span></strong></td><td>Enregistrement du RCF + CU si âge gestationnel le permet (<strong>&gt; <span>25 SA</span></strong>)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Bilan en milieu hospitalier — Examens complémentaires</h4>\n      <table>\n        <thead><tr><th>Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-purple_bg\">ECBU</span> + <span class=\"nc-purple_bg\">Prélèvement vaginal</span> + <span class=\"nc-purple_bg\">Hémocultures</span> avec recherche de Listeria</span></td><td>Bilan microbiologique complet (la <strong><span>sérologie</span> <span>listeria</span> est sans valeur</strong>)</td></tr>\n          <tr><td><span><span class=\"nc-blue_bg\">NFS / CRP</span></span></td><td>Recherche d’hyperleucocytose (GB <span class=\"nc-red\">&gt; </span><span><span class=\"nc-red\">15 G/L</span></span>) ; pondérer avec l’hyperleucocytose physiologique</td></tr>\n          <tr><td><span>Sérologies selon contexte</span></td><td><span><span class=\"nc-purple_bg\">Rubéole</span></span>, <span><span class=\"nc-purple_bg\">toxoplasmose</span></span>, <span>hépatite</span>, <span><span class=\"nc-purple_bg\">CMV</span></span>, <span><span class=\"nc-purple_bg\">VIH</span></span>, <span>parvovirus B19</span></td></tr>\n          <tr><td><strong>RCF + CU</strong></td><td>Si âge gestationnel &gt; <span>25 SA</span></td></tr>\n          <tr><td><span><span class=\"nc-brown_bg\">Échographie obstétricale</span></span></td><td>Apprécier le bien-être fœtal + quantité de liquide amniotique</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Examens orientés selon contexte clinique</h4>\n      <ul>\n        <li><strong>Suspicion de <span>chorioamniotite</span></strong> : <span>NFS, CRP, <span class=\"nc-purple_bg\">prélèvement vaginal</span>, bactériologie du liquide amniotique, écouvillon</span></li>\n        <li><strong>Suspicion de <span>RPM</span></strong> : <span>IGFBP-1, PAMG-1, DAO, Amniocheck, PromTest®</span></li>\n        <li><strong>Suspicion d’<span>appendicite</span></strong> : <span>NFS</span>, <span>CRP</span>, <span>échographie abdominale</span> (± <span>IRM</span> en cas de doute, <span>TDM</span> dosimétrie limitée)</li>\n        <li><strong>Suspicion d’<span>hépatite</span></strong> : <span>ASAT</span>/<span>ALAT</span>, <span>PAL</span>, <span>bilirubine</span>, <span>sérologies</span> hépatiques (Ag HBs, Ac anti-HBs, Ac anti-HBc, VHA, <span>VHC</span>), test de la MNI</li>\n        <li><strong>Si <span>fièvre</span> à l’accouchement</strong> : prélèvements périphériques + <span class=\"nc-blue_bg\">aspiration du liquide gastrique chez le nouveau-né</span> + <strong><span class=\"nc-blue_bg\">mise en culture du placenta</span></strong></li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — Infection urinaire · 27 — Prévention des risques fœtaux (<span class=\"nc-purple_bg\">toxoplasmose</span>) · 173 — Zoonose · 147 — <span>Fièvre</span> aiguë adulte · 168 — Herpesvirus</em></p></div>"},{"i":"8eae9b7f46cd","n":24,"o":"24-25","u":"Prise en charge","t":"Connaître la prise en charge d’une fièvre au cours de la grossesse","q":"Que retenir concernant la prise en charge d’une fièvre au cours de la grossesse ?","a":"<div class=\"notion-course\"><p>La PEC d’une <span>fièvre</span> pendant la <span>grossesse</span> repose sur (1) <strong><span>antibiothérapie</span> probabiliste anti-<span>Listeria</span> immédiate</strong> en cas d’<span>hospitalisation</span>, (2) <strong>traitement symptomatique</strong> (<span><span class=\"nc-pink nc-bold\">paracétamol</span></span>), (3) <strong><span>surveillance</span> maternelle et fœtale rapprochée</strong>, (4) <strong>traitement étiologique adapté</strong> aux résultats.</p>\n\n      <h4>PEC à domicile — situations autorisées</h4>\n      <div class=\"callout callout-info\">\n        <strong>Domicile autorisé seulement si :</strong>\n        <ul>\n          <li><strong><span class=\"nc-green_bg\">Étiologie bénigne clairement identifiée</span></strong> (syndrome grippal en épidémie, <span class=\"nc-green_bg\">gastro-entérite</span>)</li>\n          <li><strong>Absence de CU</strong></li>\n          <li><strong>Mouvements fœtaux normaux</strong></li>\n          <li><strong>RCF normal</strong> (si âge gestationnel adapté)</li>\n        </ul>\n        <strong>Mesures :</strong> <span>paracétamol</span>, traitement symptomatique adapté, bonne hydratation, <span>surveillance</span> rapprochée + consigne de reconsulter en <span>urgence</span> si aggravation, CU, baisse des mouvements fœtaux, persistance &gt; <span>48 h</span>.\n      </div>\n\n      <h4>PEC hospitalière — Sans attendre les résultats</h4>\n      <div class=\"callout callout-danger\">\n        <strong><span>Antibiothérapie</span> probabiliste anti-<span>Listeria</span> immédiate</strong> en cas d’<span>hospitalisation</span>, <strong>en dehors d’une orientation étiologique claire</strong> :\n        <ul>\n          <li><strong>1ʳᵉ intention :</strong> <span><span class=\"nc-pink_bg\">Amoxicilline</span> <span class=\"nc-pink nc-bold\">3 g/jour</span></span> per os ou IV pendant <strong><span><span class=\"nc-pink nc-bold\">10 jours</span></span></strong></li>\n          <li><strong>Si <span>allergie</span> :</strong> <span><span class=\"nc-pink_bg\">érythromycine</span></span></li>\n          <li><strong>Si signes de <span><span class=\"nc-orange nc-bold\">chorioamniotite</span></span></strong> : <span><span class=\"nc-pink nc-bold\">C3G</span> (céfotaxime / ceftriaxone) + <span class=\"nc-pink nc-bold\">Aminoside</span> (gentamicine)</span> en IV — <em><span>amoxicilline</span> selon KB</em></li>\n        </ul>\n        <strong>+ Antipyrétique :</strong> <span>paracétamol</span> <span>1 g</span> ×<span> 4/jour</span>. <strong>Pas d’<span>AINS</span> pendant la <span>grossesse</span></strong> ❌.<br>\n        <strong>+ Bonne hydratation</strong>.\n      </div>\n\n      <h4><span>Surveillance</span> étroite</h4>\n      <ul>\n        <li><strong>Maternelle :</strong> température, FC, PA, FR, état général, diurèse</li>\n        <li><strong>Obstétricale :</strong> CU (tocométrie), col utérin (<span>TV</span> répété ± écho), pertes vaginales</li>\n        <li><strong>Fœtale :</strong> RCF en continu ou enregistrements répétés, mouvements actifs perçus par la mère</li>\n        <li><strong><span>Biologique</span> :</strong> <span>NFS</span> + <span>CRP</span> de contrôle à <span>48 h</span> ± <span>hémocultures</span> de contrôle</li>\n      </ul>\n\n      <h4>PEC étiologique selon résultats</h4>\n      <table>\n        <thead><tr><th>Étiologie</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Listériose</span> confirmée</strong></td><td><span><span class=\"nc-pink_bg\">Amoxicilline</span> IV 6 g/jour</span> pendant <strong><span>3 semaines</span></strong> ± <span>gentamicine</span>. <strong>Déclaration obligatoire</strong>.</td></tr>\n          <tr><td><strong><span><span class=\"nc-brown_bg\">Pyélonéphrite</span></span><span class=\"nc-brown_bg\"> aiguë gravidique</span></strong></td><td><span>C3G (céfotaxime / ceftriaxone)</span> IV puis relais oral (amox-clav, FQ <span>contre-indiquées</span> sauf <span>E. coli</span> résistant) — durée totale <span>10-14 jours</span>. <strong><span>Hospitalisation</span> systématique</strong>.</td></tr>\n          <tr><td><strong><span><span class=\"nc-orange nc-bold\">Chorioamniotite</span></span></strong></td><td><span><span class=\"nc-pink nc-bold\">C3G</span> + <span class=\"nc-pink nc-bold\">Aminoside</span></span> IV + <strong>extraction fœtale en <span>urgence</span> par césarienne</strong> ++ ; <span>tocolyse CI</span> dans ce contexte ⚠️</td></tr>\n          <tr><td><strong>Infections virales</strong> (<span><span class=\"nc-green_bg\">grippe</span></span>, <span class=\"nc-green_bg\">gastro-entérite</span>)</td><td>Traitement symptomatique. <strong><span>Oseltamivir</span></strong> possible si <span><span class=\"nc-green_bg\">grippe</span></span> avérée et formes graves.</td></tr>\n          <tr><td><strong><span>Toxoplasmose</span> maternelle</strong> (séroconversion)</td><td><span>Spiramycine</span> jusqu’à <span>18 SA</span> puis <span>pyriméthamine</span>-<span>sulfadiazine</span> selon contamination fœtale</td></tr>\n          <tr><td><strong><span>Appendicite</span> / <span><span class=\"nc-orange nc-bold\">cholécystite</span></span></strong></td><td>Traitement chirurgical en <span>urgence</span> ± ATB</td></tr>\n        </tbody>\n      </table>\n\n      <h4>PEC néonatale en cas de <span>fièvre</span> à l’accouchement</h4>\n      <ul>\n        <li><strong>Prélèvements périphériques</strong> chez le nouveau-né</li>\n        <li><strong>Aspiration du liquide gastrique</strong></li>\n        <li><strong><span class=\"nc-blue_bg\">Mise en culture du placenta</span></strong></li>\n        <li><strong>ATB néonatale probabiliste</strong> selon contexte (anti-<span>Listeria</span> + anti-Strepto B)</li>\n        <li><strong><span>Surveillance</span> pédiatrique rapprochée</strong> (<span>sepsis</span> néonatal)</li>\n      </ul>\n\n      <h4>Cas particuliers — Conseils alimentaires anti-<span>Listeria</span></h4>\n      <div class=\"callout callout-warn\">\n        <strong><span>Prévention primaire</span> de la <span>listériose</span> pendant la <span>grossesse</span> :</strong>\n        <ul>\n          <li>Éviter <strong>fromages au lait cru</strong>, à pâte molle, croûtes</li>\n          <li>Éviter <strong>charcuteries</strong> artisanales, rillettes, pâtés, foie gras non stérilisé</li>\n          <li>Éviter <strong>poissons fumés, crustacés crus, sushis</strong></li>\n          <li>Bien <strong>cuire les viandes</strong> et lavages soigneux des fruits/légumes</li>\n          <li>Respecter la chaîne du froid, dates de péremption</li>\n        </ul>\n      </div>\n\n      <h4>Synthèse — Algorithme</h4>\n      <ol>\n        <li><strong><span>Fièvre</span> &gt; <span>38 °C</span> confirmée</strong> → interrogatoire + examen complet</li>\n        <li><strong>Étiologie bénigne identifiée + bonne tolérance</strong> → PEC à domicile, <span><span class=\"nc-pink nc-bold\">paracétamol</span></span>, <span>surveillance</span></li>\n        <li><strong>Sinon ou doute</strong> → <span>hospitalisation</span></li>\n        <li><strong>Bilan paraclinique</strong> (cf. obj-23) + <strong><span>amoxicilline</span> <span>3 g/j</span></strong> sans attendre</li>\n        <li><strong><span>Surveillance</span> maternelle + fœtale</strong> rapprochée</li>\n        <li><strong>Adaptation</strong> selon résultats microbiologiques</li>\n      </ol>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — Infection urinaire · 27 — Prévention des risques fœtaux (<span class=\"nc-purple_bg\">toxoplasmose</span>) · 173 — Zoonose (<span class=\"nc-red nc-bold\">listériose</span>) · 147 — <span>Fièvre</span> aiguë adulte · 166 — <span><span class=\"nc-green_bg\">Grippe</span></span></em></p></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d941811db6c7cb28b758360c?pvs=204","reviewedAt":"2026-10-15","note":"Cours personnel, couleurs des passages Notion correspondants, corrections et parcours interactifs sourcés. Les compléments sont distingués des figures d’origine."},"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Mauvaise tolérance ou hémorragie importante ?","detail":"<ul><li>Constantes, douleur, quantité, terme ; stabiliser en parallèle.</li></ul>","branches":[{"label":"Oui","to":"urgent"},{"label":"Non","to":"terme"}]},{"id":"urgent","kind":"urgent","label":"Alerte obstétricale et réanimation","detail":"<ul><li>Voies veineuses, bilan et préparation transfusionnelle ; traitement causal urgent.</li></ul>","branches":[]},{"id":"terme","kind":"decision","label":"Premier trimestre ou grossesse plus avancée ?","detail":"<ul><li>Échographie adaptée ; groupe/RAI selon contexte.</li></ul>","branches":[{"label":"Premier trimestre","to":"localiser"},{"label":"Deuxième / troisième trimestre","to":"placenta"}]},{"id":"localiser","kind":"decision","label":"Grossesse localisée et évolutive ?","detail":"<ul><li>β-hCG + échographie ; ne pas conclure sur une seule valeur.</li></ul>","branches":[{"label":"GEU / localisation indéterminée","to":"geu"},{"label":"Intra-utérine arrêtée / fausse couche","to":"fc"},{"label":"Intra-utérine évolutive","to":"surveiller"}]},{"id":"geu","kind":"finish","label":"Parcours GEU et suivi rapproché","detail":"<ul><li>Urgence si aggravation ; suivi jusqu’à localisation ou résolution.</li></ul>","branches":[]},{"id":"fc","kind":"finish","label":"Confirmer avant traitement","detail":"<ul><li>Expectative, médicament ou aspiration selon contexte et choix ; anti-D selon terme.</li></ul>","branches":[]},{"id":"placenta","kind":"decision","label":"Placenta prævia, HRP ou autre cause ?","detail":"<ul><li>Pas de toucher vaginal digital avant d’avoir écarté un placenta prævia ; évaluer mère et fœtus.</li></ul>","branches":[{"label":"Urgence maternelle/fœtale","to":"urgent"},{"label":"Stabilité","to":"surveiller"}]},{"id":"surveiller","kind":"finish","label":"Surveillance et consignes explicites","detail":"<ul><li>Étiologie, calendrier et accès urgent si saignement, douleur ou malaise.</li></ul>","branches":[]}]}};
